yield return new GeneralDefinition("s1_100805","孙坚",Homeland.Han,5,84,"勇挚刚毅","孙坚·汉·弓·5星。招募记录：开国之才、黄天当立；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100805.html", evidence="招募记录：开国之才、黄天当立；仅作试玩池依据，开放条件未复刻", nativeSkill="勇挚刚毅", nativeSkillText="自身受到攻击伤害后，有60.0%几率对敌军单体发动一次攻击（伤害率100.0%），自身受到策略攻击伤害后，有40.0%几率对敌军群体发动一次攻击（伤害率80.0%）；当自身兵力首次低于初始兵力的90%、80%、70%和60%时，造成的攻击伤害提升5.0%（受攻击属性影响），受到恢复效果提升5.0%（受防御属性影响），此效果最多叠加4次；", defense=83, strategy=62, speed=56, cost=3, attackGrowth=1.72, defenseGrowth=1.83, strategyGrowth=0.72, speedGrowth=1.18, siege=15, siegeGrowth=1.38, attackDistance=3, biography="【史】县吏出身，因勇敢又有谋略被官府赏识，提拔为军官。曾参与讨伐黄巾军的战役以及讨伐董卓的战役。后与刘表作战时阵亡。孙坚的儿子孙策、孙权后来创建了东吴政权。\n【演】在《三国演义》中，孙坚由于征讨黄巾有功，被封为长沙太守。在董卓乱政期间，孙坚作为诸侯联军的先锋，表现得十分活跃，但因袁术存在私心，拒不发粮，而被董卓将华雄击败。后来董卓迁都长安，孙坚进驻洛阳，意外发现传国玉玺，并藏匿返回。不料事情泄漏，与袁绍、刘表结仇。不久，孙坚在与刘表手下黄祖的交战中，中埋伏而死。", advancedTroops="弩兵、死士", combination="不忘初心(成员:孙坚(汉)、曹操(汉)、刘备(汉),加成属性:防御、【举义诛暴】发动率提高)", policyName="破虏治兵", policyText="可担任军事设施参军，使军事设施内所有汉阵营、吴阵营武将征兵时间降低8.0%，征兵消耗铜钱降低25.0%，重伤时间缩短60秒" };
yield return new GeneralDefinition("s1_100840","许褚",Homeland.Han,5,97,"蛮王御众","许褚·魏·步·5星。招募记录：黄天当立；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100840.html", evidence="招募记录：黄天当立；仅作试玩池依据，开放条件未复刻", nativeSkill="蛮王御众", nativeSkillText="令自身受到的所有伤害降低30.0% (受防御属性影响)，前2回合援护友军全体；自身每受到5次伤害，则使友军攻击最高单体有60.0%几率对敌军群体发动一次攻击（伤害率120.0%）；若友军兵种为蛮兵/藤甲兵/象兵,则该友军前3回合也享受自身来自蛮王御众伤害降低效果的一半，对其援护效果提升至4回合，蛮王御众令其发动攻击时，变为必定发动且伤害率额外增加120.0%。", defense=88, strategy=53, speed=51, cost=3, attackGrowth=2.2, defenseGrowth=1.95, strategyGrowth=0.48, speedGrowth=0.46, siege=17, siegeGrowth=1.2, attackDistance=2, biography="【史】主要负责曹操的护卫工作。官渡之战时发现欲谋害曹操者，将刺客全部消灭。渭南之战时在身披重甲的情况下左手掩面，右手控船桨令曹操安然成功渡河，上岸才发现早已身中数箭。相随曹操会面马超、韩遂时，许褚怒视马超，令其放弃袭击曹操的想法。当曹操去世时许褚哭至吐血，曹丕迁其作武卫将军，负责宫中安全。曹叡继位时封其为牟乡侯，不久去世，谥曰壮侯。\n【演】在《三国演义》中，许褚是曹操帐下数一数二的猛将。曹操讨伐黄劭、何仪时，许褚生擒何仪以及黄巾数百骑，典韦要人，许褚与典韦大战两次，不分胜败，为曹操赏识，收之用为护卫，从此为曹操征战四方。官渡破袁绍后，因谋士许攸辱骂，怒而斩之。许褚向来目光呆滞，征战英勇，人称“虎痴”，曾裸衣恶斗马超。汉中之战，许褚护粮，因酒醉为张飞所败，幸得众将相救。", advancedTroops="蛮兵、藤甲兵", combination="", policyName="百折不回", policyText="令群阵营武将所在部队单次出征战斗后恢复10.0%伤兵；该部队每在连续战斗中获得一次胜利，该回复比例提升5.0%，最多叠加2次。部队返回归属点后，其伤兵恢复比例重置" };
yield return new GeneralDefinition("s1_100693","王允",Homeland.Han,5,81,"连环计","王允·汉·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100693.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="连环计", nativeSkillText="对敌军单体施加连环计，依次发动下列战法：对连环计目标发动一次“伐谋”；若连环计目标谋略低于自身，则对随机敌军单体发动一次“迷阵”；若连环计目标处于暴走状态，则对随机敌军单体发动一次“落雷”。每个战法的效果与原战法在同等级下效果相同", defense=94, strategy=93, speed=58, cost=2.5, attackGrowth=0.91, defenseGrowth=1.33, strategyGrowth=1.97, speedGrowth=0.82, siege=13, siegeGrowth=0.72, attackDistance=3, biography="【史】东汉末年大臣。王允出身官宦世家。他十九岁就开始任公职，壮年时任豫州刺史。因为在和中常侍张让的斗争中失败，王允被迫去官隐居，在中平六年，何进掌权之后重新出仕，历任从事中郎和河南尹。在何进被宦官所害，董卓掌权时，他已经代替杨彪成为了司徒兼尚书令。\n身为地方官勤政爱民，由于朝廷腐败而被迫在此为官，从而密谋诛灭董卓。董卓死后，王允与吕布共执朝政，但是董卓余党李傕、郭汜、樊稠等率军攻破长安，吕布出逃，王允被处死，时年56岁。\n【演】在《三国演义》中，他是貂蝉的义父，貂蝉是造成吕布和董卓反目，以致于吕布最终诛灭了董卓的主要原因。", advancedTroops="长弓兵 、弩兵", combination="汉朝仕官(成员:王允(汉)、刘虞(汉)、王烈(汉),加成属性:防御、速度)、行刺太师(成员:王允(汉)、董卓(汉)、曹操(汉)、董卓(群)、貂蝉(汉),加成属性:攻击、谋略、攻击距离提高)", policyName="青琐忠魂", policyText="无法迁城与重振，令势力所有城邑预备兵恢复速度增加20.0%，由汉阵营武将担任参军的军事设施耐久上限提升20" };
yield return new GeneralDefinition("s1_100526","张机",Homeland.Han,5,81,"金匮要略","张机·汉·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100526.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="金匮要略", nativeSkillText="战斗开始后前3回合，使我军全体受到的所有伤害降低20.4%（受谋略属性影响），同时使我军全体受到伤害时，有50.0%的几率能恢复一定兵力（恢复率80.0%，受谋略属性影响）", defense=90, strategy=88, speed=55, cost=3, attackGrowth=1.17, defenseGrowth=1.79, strategyGrowth=1.63, speedGrowth=0.87, siege=12, siegeGrowth=0.85, attackDistance=3, biography="【史】名机，字仲景，南阳郡人。以表字行施于世，即汉末著名医学家“张仲景”。早年学医于同郡张伯祖，尽得其真传。初举孝廉，相传于建安年间任长沙太守，时大疫流行，乃钻研《内经》《难经》等古医书，博采众方，撰写《伤寒杂病论》，与华佗、董奉齐名，并称“建安三神医”，后世尊其为“医圣”。其著作辗转流散，经后人编次校勘，分别整理为《伤寒论》和《金匮要略》二书，流传至今。", advancedTroops="长弓兵 、弩兵", combination="", policyName="医圣", policyText="令势力所有拥有参军的军事设施，其所属己方部队每次出征时首场战斗后恢复伤兵，恢复比例为40.0%" };
yield return new GeneralDefinition("s1_100769","典韦",Homeland.Han,5,102,"舍身卫主","典韦·魏·步·5星。招募记录：汉室衰微；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100769.html", evidence="招募记录：汉室衰微；仅作试玩池依据，开放条件未复刻", nativeSkill="舍身卫主", nativeSkillText="战斗开始后，受到2距离以内敌军的伤害时，有60.0%几率对伤害来源发动一次攻击（伤害率120.0%）。位于前锋或中军时，战斗开始后前3回合，敌军对友军全体造成的攻击伤害由典韦承担。", defense=97, strategy=33, speed=35, cost=3, attackGrowth=2.5, defenseGrowth=2, strategyGrowth=0.33, speedGrowth=0.51, siege=18, siegeGrowth=1.73, attackDistance=1, biography="【史】曹操部将，相貌魁梧，膂力过人。本属张邈，后归曹操。曹操征讨吕布时被募为陷阵，表现英勇，被拜为校尉，宿卫曹操。后曹操于宛城时，张绣先降而复反，急迫曹操本营；典韦守着大门，殊死恶斗，破敌无算，最终因敌人太多而战死。 \n【演】在《三国演义》中，因其悍武，曹操称其为“古之恶来”。张绣背叛时，先令胡车儿暗盗韦双戟，再引军急迫曹操本营。典韦守大门，殊死恶斗，破敌无算，刀坏了竟双手各提一人为武器迎敌。群贼不敢近，只远远以箭射之，箭如骤雨，典韦犹死拒寨门。", advancedTroops="长枪兵、禁卫", combination="", policyName="竭忠卫主", policyText="可担任军事设施参军，令所属部队驻守己方或同盟建筑时，行军速度提升20" };
yield return new GeneralDefinition("s1_100443","陈宫",Homeland.Han,5,60,"迟智难酬","陈宫·群·弓·5星。招募记录：汉室衰微；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100443.html", evidence="招募记录：汉室衰微；仅作试玩池依据，开放条件未复刻", nativeSkill="迟智难酬", nativeSkillText="对敌军群体发动一次策略攻击（伤害率240.0%，受谋略属性影响），并使友军群体受到下1-2次策略攻击的伤害大幅度降低", defense=82, strategy=95, speed=60, cost=3, attackGrowth=0.9, defenseGrowth=1.8, strategyGrowth=2.4, speedGrowth=1.01, siege=9, siegeGrowth=0.72, attackDistance=4, biography="【史】为人性格刚直烈壮，少与海内知名之士皆相连结。初随曹操，后因曹操谋害边让而与曹操反目，弃曹投靠吕布。吕布战败后，随吕布等一同被曹操所擒，陈宫求即就戮，从容赴死。\n【演】在《三国演义》中，陈宫曾被刘晔评价为“陈宫多计”；荀攸评其“有谋而迟”。在下邳吕布战败后，陈宫亦于下邳城南门被曹操部将徐晃擒获。白门楼前，曹操劝降陈宫，陈宫不肯屈降，曹操忍痛下令斩首处决陈宫。", advancedTroops="长弓兵 、弩兵", combination="温侯无双(成员:陈宫(群)、高顺(群)、吕姬(群)、貂蝉(群)、张辽(群)、貂蝉(汉)、吕布(汉)、吕布(群),加成属性:攻击)", policyName="画策定谋", policyText="令势力所有谋略大于攻击的武将征兵时间降低8.0%，群阵营武将如果谋略高于150，则征兵粮草消耗额外降低5.0%" };
yield return new GeneralDefinition("s1_100655","郭皇后",Homeland.Han,5,61,"文德椒房","郭皇后·魏·弓·5星。招募记录：汉室衰微；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="魏", troop="弓", sourceUrl="https://stzb.163.com/herolist/100655.html", evidence="招募记录：汉室衰微；仅作试玩池依据，开放条件未复刻", nativeSkill="文德椒房", nativeSkillText="战斗中，每回合自身首次发动主动战法后，使我军群体进行策略攻击时的伤害提升10.0%（受谋略属性影响），此效果最多可叠加3次", defense=77, strategy=92, speed=72, cost=2.5, attackGrowth=0.65, defenseGrowth=1.35, strategyGrowth=1.61, speedGrowth=0.96, siege=12, siegeGrowth=0.86, attackDistance=3, biography="【史】曹魏王朝第一位皇后，曹丕之妻。其祖上世代为郡县官吏，但早失二亲。曹操为魏公时，入曹丕东宫。曹丕即王位，封为夫人（位次王后），同年魏受禅，进为贵嫔（位次皇后）。黄初三年（222年），册立为皇后。\n【演】在《三国演义》第九十一回短暂提及郭后 ，于曹丕称帝后，聘为贵妃，姿貌艳丽，颇有城府。郭贵妃欲谋为后，与宠臣张韬商议，谎称甄夫人以魇镇之术谋害天子。曹丕遂将甄夫人赐死，立郭贵妃为皇后。因郭后无出，养曹叡为子，虽甚爱之，不立为嗣。", advancedTroops="长弓兵 、弩兵", combination="母仪天下(成员:吴夫人(吴)、郭皇后(魏)、丁夫人(魏)、甘皇后(蜀)、何太后(汉)、卫子夫(汉)、阴丽华(汉),加成属性:谋略、速度)", policyName="文德皇后", policyText="可担任分城参军，令该分城城内设施的建造和升级资源消耗降低20.0%，如果曹丕也在施政，则城内设施的建造和升级时间额外降低15.0%" };
yield return new GeneralDefinition("s1_100804","曹操",Homeland.Han,5,76,"举义诛暴","曹操·汉·骑·5星。招募记录：开国之才、汉室衰微；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100804.html", evidence="招募记录：开国之才、汉室衰微；仅作试玩池依据，开放条件未复刻", nativeSkill="举义诛暴", nativeSkillText="对敌军群体发动一次攻击（伤害率150.0%），并使其全属性下降5.0%（受攻击属性影响），敌军群体受到下2次伤害时，都有50.0%几率陷入怯战、犹豫、混乱、暴走状态之一，持续1回合", defense=88, strategy=72, speed=78, cost=2.5, attackGrowth=1.48, defenseGrowth=2.32, strategyGrowth=1.38, speedGrowth=1.16, siege=4, siegeGrowth=0.33, attackDistance=3, biography="【史】三国中曹魏政权的奠基人。其人文武精通，可谓非常之人，超世之杰。以汉天子的名义征讨四方，对内消灭二袁、吕布、刘表、马超、韩遂等割据势力，对外降服南匈奴、乌桓、鲜卑等，统一了中国北方，并实行一系列政策恢复经济生产和社会秩序，奠定了曹魏立国的基础。\n【演】在《三国演义》中，曹操的事迹基本与正史相符。主要将其塑造成一个“奸雄”形象，并且更突出“奸”的一面。", advancedTroops="轻骑兵、铁骑兵", combination="不忘初心(成员:孙坚(汉)、曹操(汉)、刘备(汉),加成属性:防御、【举义诛暴】发动率提高)", policyName="命世之才", policyText="势力所属部队征兵时间降低3.0%，屯田获得资源收益提高10.0%" };
yield return new GeneralDefinition("s1_100450","孙策",Homeland.Han,5,96,"霸王渡江","孙策·吴·骑·5星。招募记录：汉室衰微；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="吴", troop="骑", sourceUrl="https://stzb.163.com/herolist/100450.html", evidence="招募记录：汉室衰微；仅作试玩池依据，开放条件未复刻", nativeSkill="霸王渡江", nativeSkillText="每回合有40.0%的几率对有效距离5以内的敌军单体发动三次猛烈攻击（伤害率150.0%），每次攻击目标独立判定，本场战斗中，自身无法发动主动战法，每次攻击造成伤害后可使霸王渡江发动率提升3.0%，该效果可叠加5次每回合有40.0%的几率对有效距离5以内的敌军单体发动三次猛烈攻击（伤害率150.0%），每次攻击目标独立判定，本场战斗中，自身无法发动主动战法，每次攻击造成伤害后可使霸王渡江发动率提升5.0%，该效果可叠加5次", defense=92, strategy=72, speed=82, cost=3, attackGrowth=2.25, defenseGrowth=1.75, strategyGrowth=0.83, speedGrowth=1.44, siege=6, siegeGrowth=0.53, attackDistance=2, biography="【史】三国时期孙吴的奠基者之一，孙坚长子、吴大帝孙权长兄。其人有智有勇，英姿勃发，其治军严整，军纪严明，被称为“江东小霸王”。初为继承父亲孙坚的遗业而屈事袁术，征战时屡获大胜。袁术僭越称帝后，孙策与袁术决裂，曹操下诏书给孙策，要孙策讨伐袁术。之后孙策统一江东，但在一次狩猎中为刺客所伤，不久后身亡。其弟孙权接掌孙策势力。\n【演】在《三国演义》中，孙策的事迹基本与正史相符。而在描写孙策被刺后，引入了孙策斩道士于吉而受其诅咒，伤重而亡的情节。", advancedTroops="重骑兵、轻骑兵", combination="枭雄父子(成员:孙策(吴)、孙坚(吴)、孙权(吴),加成属性:攻击)、二乔(成员:小乔(吴)、大乔(吴)、孙策(吴)、小乔＆大乔(吴)、周瑜(吴),加成属性:谋略)", policyName="奠定基业", policyText="可担任主城参军，令所属部队吴阵营武将征兵资源消耗降低12.0%，同时征兵时间降低8.0%" };
yield return new GeneralDefinition("s1_100790","袁术",Homeland.Han,5,68,"僭号天子","袁术·群·步·5星。招募记录：天下大乱；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100790.html", evidence="招募记录：天下大乱；仅作试玩池依据，开放条件未复刻", nativeSkill="僭号天子", nativeSkillText="战斗开始后获得玉玺：我军全体受到的所有伤害的32.0%（受防御属性影响）由玉玺承担；第二回合起，每回合开始时玉玺对袁术造成其上一回合承担所有伤害，袁术仅受到来自玉玺伤害的50%，该比例每回合上升10%", defense=98, strategy=50, speed=38, cost=3.5, attackGrowth=1.35, defenseGrowth=2.12, strategyGrowth=0.67, speedGrowth=0.88, siege=16, siegeGrowth=1.42, attackDistance=2, biography="【史】袁逢之嫡次子，袁基、袁绍之弟。初为虎贲中郎将。董卓进京后以袁术为后将军，袁术因畏祸而出奔南阳。初平元年（190年）与袁绍、曹操等同时起兵，共讨董卓。后与袁绍对立，被袁绍、曹操击败，率馀众奔九江，割据扬州。建安二年（197年）称帝，建号仲氏 ，但未受人承认。此后袁术奢侈荒淫，横征暴敛，使江淮地区残破不堪，民多饥死，部众离心，先后为吕布、曹操所破，元气大伤，后于建安四年（199年）呕血而死。\n【演】在《三国演义》中，他的家族四代中有五人位居三公，是当世的大豪族。因董卓祸国，十八路诸侯聚讨董卓，袁术以第一镇诸侯的身份参与。同盟解散后，袁术为了除掉刘备，派遣使者想和吕布结亲，吕布将使者送给曹操斩首。得知吕布送斩他的使者，就发兵攻打他，却反被吕布所破。曹操又会合吕布、刘备、孙策等讨伐袁术，袁术大败。", advancedTroops="重步兵、禁卫", combination="", policyName="奢恣钞掠", policyText="令势力通过贼寇作乱陈情可额外获得6000铜钱，若主城位于扬州或者豫州，则获得预备兵提高600" };
yield return new GeneralDefinition("s1_100671","蒋钦",Homeland.Han,5,89,"怒浪伐敌","蒋钦·吴·弓·5星。招募记录：天下大乱；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100671.html", evidence="招募记录：天下大乱；仅作试玩池依据，开放条件未复刻", nativeSkill="怒浪伐敌", nativeSkillText="普通攻击后，对攻击目标发动一次袭击（伤害率240.0%）。此战法每发动一次，其发动率提高10.0%，可叠加", defense=82, strategy=60, speed=69, cost=3, attackGrowth=1.83, defenseGrowth=1.69, strategyGrowth=0.96, speedGrowth=1.11, siege=9, siegeGrowth=0.63, attackDistance=4, biography="【史】汉末东吴名将，其人贵守约，性豁达。早年随孙策平定丹阳、吴郡、会稽和豫章四郡。平盗贼，迁西部都尉。讨会稽贼吕合、秦狼等，徙讨越中郎将。又与贺齐并力讨平黟贼。从征合肥，因功迁荡寇将军，被陈寿盛赞为“江表之虎臣”。孙权讨伐关羽时，蒋钦率领水军入沔水。回军途中病逝。\n【演】在《三国演义》中，蒋钦是擅长弓术的将领。与周泰原为江贼，孙策下江东自立门户时，和周泰一起率众投靠。孙策攻刘繇，并引出城中麾下的陈横、薛礼、张英三名将领，陈横被蒋钦一箭射死。曾在赤壁之战与周泰，还有擅使长枪的韩当率领水军在三江口踏江破敌。南郡之战请命攻曹仁，但却被曹仁和牛金击退，周瑜打算怒斩蒋钦，众将求情劝免，其后故事与《三国志》基本相同。", advancedTroops="长弓兵 、弩兵", combination="东吴老将(成员:程普(吴)、蒋钦(吴)、黄盖(吴)、韩当(吴),加成属性:攻击、防御)", policyName="从平江东", policyText="可担任军事设施参军，令所属己方部队中，当前总兵力低于其他所有己方部队的部队所属武将征兵时间降低10.0%，同时征兵资源消耗额外降低8.0%" };
yield return new GeneralDefinition("s1_100619","大乔",Homeland.Han,5,44,"巧音唤蝶","大乔·吴·步·5星。招募记录：天下大乱；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100619.html", evidence="招募记录：天下大乱；仅作试玩池依据，开放条件未复刻", nativeSkill="巧音唤蝶", nativeSkillText="对敌军群体发动一次策略攻击（伤害率176.0%，受谋略属性影响）并使其陷入燃烧状态，当目标兵力高于初始兵力50%时受到一次策略伤害（伤害率86.0%，受谋略属性影响），持续1回合；同时使我军群体恢复一定兵力（恢复率161.0%，受谋略属性影响），并使其进入休整状态，当目标兵力低于初始兵力50%时恢复一定兵力（恢复率82.0%，受谋略属性影响），持续1回合", defense=68, strategy=69, speed=46, cost=2.5, attackGrowth=0.59, defenseGrowth=1.86, strategyGrowth=2, speedGrowth=0.68, siege=17, siegeGrowth=1.64, attackDistance=3, biography="【史】吴国乔公长女，孙策之妾、小乔之姊。大乔国色流离、资貌绝伦。建安三年，孙策攻皖，拔之。纳大乔。后人谓英雄美女，天作之合。\n【演】在《三国演义》中，大乔唯一一次登场在二十九回中，孙策去世时，留下遗言命她孝顺吴夫人。孔明智激周瑜时，暗示曹操打仗是为了二乔，并将她们放到铜雀台中，引得小乔之夫周瑜暴怒，最终同意联刘抗曹。", advancedTroops="长枪兵、禁卫", combination="二乔(成员:小乔(吴)、大乔(吴)、孙策(吴)、小乔＆大乔(吴)、周瑜(吴),加成属性:谋略)", policyName="国色流离", policyText="女性武将担任军事设施参军时，令该军事设施耐久上限提高50" };
yield return new GeneralDefinition("s1_100685","乐进",Homeland.Han,5,96,"奋疾先登","乐进·魏·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100685.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="奋疾先登", nativeSkillText="每回合行动时使自身攻击伤害提升8.0%，自身速度每高于一名武将，则有70.0%几率使攻击伤害额外提升8.0%，自身速度每低于或等于一名武将，则有30.0%几率使自身攻击伤害额外提升8.0%。当本战法造成的攻击伤害提升效果达到40%时，将对距离3以内的敌军群体发动一次攻击（伤害率190.0%），发动后攻击伤害提升效果消失，同时使目标速度属性降低20.0，该效果可叠加并持续直到战斗结束", defense=87, strategy=67, speed=46, cost=3, attackGrowth=2.13, defenseGrowth=1.95, strategyGrowth=0.73, speedGrowth=0.64, siege=14, siegeGrowth=1.21, attackDistance=2, biography="【史】曹魏名将。以胆识英烈而从曹操，随军多年，南征北讨，战功无数。从击袁绍于官渡，奋勇力战，斩袁绍部将淳于琼。又从击袁谭、袁尚于黎阳，斩其大将严敬。不久乐进别击黄巾、雍奴、管承，皆大破之。从平荆州，留屯襄阳，进击关羽、苏飞等人，击退其众，南郡诸郡的山谷蛮夷都前往乐进处投降。后世将其与张辽、张郃、于禁、徐晃并称为曹魏“五子良将”。\n【演】在《三国演义》中，乐进是曹操招贤时最早投靠的武将，可惜在小说整体表现并不出色，常与另一魏将李典共同登场。赤壁之战后，曹操留乐进与张辽、李典屯于合肥，以当孙权。其时孙权入寇，双方对阵，乐进忽施突袭，一骑马一口刀，如一道电光，折贾华、宋谦之双戟，几乎擒得孙权。后来与吴将凌统鏖战，得曹休之助，本可取胜，却被吴将甘宁发箭所伤，退入军中调治伤势。", advancedTroops="重步兵、禁卫", combination="五子良将(成员:乐进(魏)、徐晃(魏)、于禁(魏)、张辽(魏),加成属性:攻击)", policyName="每战先登", policyText="可担任主城参军，令所属部队兵力最低武将征兵时间降低12.0%，征兵资源消耗也降低12.0%" };
yield return new GeneralDefinition("s1_100771","沮授",Homeland.Han,5,52,"缓师徐持","沮授·群·步·5星。招募记录：厉兵秣马；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100771.html", evidence="招募记录：厉兵秣马；仅作试玩池依据，开放条件未复刻", nativeSkill="缓师徐持", nativeSkillText="战斗中每回合，已行动的敌军群体受到伤害后，沮授有50.0%几率（受谋略属性影响）令目标的攻击、防御、谋略、速度属性下降20.0点，重复两次，每次概率独立判定，可叠加至战斗结束", defense=80, strategy=95, speed=35, cost=3, attackGrowth=1.01, defenseGrowth=1.6, strategyGrowth=2.33, speedGrowth=0.44, siege=12, siegeGrowth=1.39, attackDistance=2, biography="【史】袁绍帐下谋士。史载他“少有大志，擅于谋略”。袁绍占据冀州后任用沮授为从事。沮授经常对袁绍提出良策，但很多时候袁绍并不听从。官渡之战时袁绍大败，沮授未及逃走，被曹操所获，因拒降被曹操处死。\n【演】在《三国演义》中，沮授生平与正史大体相当。官渡之战，沮授夜观天象，知乌巢屯粮有险，连夜求见，促速遣精兵巡哨，袁绍以其妄言惑众，更人监押。袁军战败，沮授急走不脱，为曹军所获，不降而盗马欲归，曹操怒而斩之。", advancedTroops="重步兵、长枪兵", combination="", policyName="谋定河北", policyText="势力主城位于幽、并、青、冀州时，屯田资源收益增加25.0%，若所属同盟、聚义或国家占领上述任意州府，则令主城税收提升1500" };
yield return new GeneralDefinition("s1_100616","凌统",Homeland.Han,5,85,"国士无双","凌统·吴·弓·5星。招募记录：厉兵秣马；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100616.html", evidence="招募记录：厉兵秣马；仅作试玩池依据，开放条件未复刻", nativeSkill="国士无双", nativeSkillText="战斗开始后前3回合，使自身与友军单体每回合有90.0%的几率进入洞察状态，免疫混乱、犹豫、怯战、暴走和挑衅效果，同时自身攻击造成的伤害提升25.0%（受攻击属性影响）", defense=94, strategy=70, speed=62, cost=3, attackGrowth=1.75, defenseGrowth=2.07, strategyGrowth=0.91, speedGrowth=0.9, siege=12, siegeGrowth=1.05, attackDistance=3, biography="【史】吴国名将。凌操之子，少有名盛，为人有国士之风，多次战役中表现出色，官至偏将军。被陈寿盛赞为“江表之虎臣”\n【演】在《三国演义》中，凌统因父亲凌操被甘宁所害而一直仇视甘宁，但在濡须口与乐进交战时得甘宁所救，从此便尽释前嫌，与甘宁结为生死之交。其他事迹与正史大致相同。", advancedTroops="长弓兵 、弩兵", combination="", policyName="旋略勇进", policyText="可担任斥候营地参军，令该斥候营地可调动部队增加1，但耐久上限降低20.0%，同时己方部队向该斥候营地调动时行军速度提高15.0%" };
yield return new GeneralDefinition("s1_100803","刘备",Homeland.Han,5,73,"知人待士","刘备·汉·步·5星。招募记录：厉兵秣马、开国之才；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="汉", troop="步", sourceUrl="https://stzb.163.com/herolist/100803.html", evidence="招募记录：厉兵秣马、开国之才；仅作试玩池依据，开放条件未复刻", nativeSkill="知人待士", nativeSkillText="每回合行动时，有45.0%几率触发以下两种效果，两者独立判断：可使我军兵力最低单体恢复一定兵力（恢复率120.0%，受谋略属性影响）并使其受到所有伤害减少15.0%（受谋略属性影响），持续1回合；可使自身对敌军兵力最低单体发动一次策略攻击（伤害率120.0%，受谋略属性影响），并使我军攻击属性最高单体对敌军单体发动一次攻击（伤害率100.0%）", defense=76, strategy=70, speed=36, cost=2.5, attackGrowth=1.32, defenseGrowth=1.52, strategyGrowth=1.18, speedGrowth=0.83, siege=16, siegeGrowth=1.48, attackDistance=2, biography="【史】西汉中山靖王刘胜之后，三国时期蜀汉开国皇帝、政治家，史家又称他为先主。刘备早年颠沛流离，备尝艰辛，投靠过多个诸侯。赤壁之战时，与孙权联盟击败曹操，趁势夺取荆州。而后进取益州。于章武元年（221年）在成都称帝，国号汉，史称蜀或蜀汉。《三国志》评刘备的机权干略不及曹操，但其弘毅宽厚，知人待士，百折不挠，终成帝业。刘备也称自己做事“每与操反，事乃成尔”。\n【演】在《三国演义》中，刘备的事迹基本与正史相符。书中将其塑造成一位胸襟开阔的，十足的明主形象。并重点突出其几个性格特点：一是亲贤爱士，善待人才；二是生性善良，爱民如子；三是待人宽厚，不求全责备；四是偶有权谋，颇有心计。", advancedTroops="重步兵、禁卫", combination="桃园结义(成员:刘备(汉)、关羽(蜀)、张飞(蜀)、关羽(魏),加成属性:防御)、不忘初心(成员:孙坚(汉)、曹操(汉)、刘备(汉),加成属性:防御、【举义诛暴】发动率提高)", policyName="豪侠争附", policyText="使势力进行士兵征召任务或贼寇作乱时，可额外获得300预备兵，施政后，每日首次进行士兵征召任务或贼寇作乱时，额外恢复武将所在部队内全部武将20点体力" };
yield return new GeneralDefinition("s1_100449","夏侯惇",Homeland.Han,5,94,"盲侯奋勇","夏侯惇·魏·骑·5星。招募记录：厉兵秣马；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100449.html", evidence="招募记录：厉兵秣马；仅作试玩池依据，开放条件未复刻", nativeSkill="盲侯奋勇", nativeSkillText="战斗中，攻击无视兵种相克，自身受到伤害后有40.0%的几率对有效距离4以内的敌方群体发动一次攻击（伤害率60.0%） ", defense=98, strategy=67, speed=90, cost=3, attackGrowth=2.06, defenseGrowth=2.3, strategyGrowth=0.67, speedGrowth=1.58, siege=3, siegeGrowth=0.24, attackDistance=1, biography="【史】汉末年三国时期曹魏名将，西汉开国元勋夏侯婴的后代。少年时以勇气闻名于乡里。曹操起兵，夏侯惇是其最早的将领之一。与吕布军交战时，曾一度被擒为人质，又被流矢射瞎左眼。多次为曹操镇守后方，曾率军民阻断太寿河水，筑陂塘灌溉农田，使百姓受益，功勋卓著。历任折冲校尉、济阴太守、建武将军，官至大将军，封高安乡侯，追谥忠侯。青龙元年（233年），得以配享太祖（曹操）庙庭。\n【演】在《三国演义》中，夏侯惇在徐州攻防战时迎战吕布部将高顺，高顺败逃，夏侯惇从后追赶，不料遭另一名敌将曹性射箭偷袭。夏侯惇左眼被射中，痛得怒吼一声便匆忙用手拔箭，却不慎连着眼珠子拔了出来。夏侯惇立即大喊：“父精母血，不可弃也！”便把眼睛塞进嘴巴吞咽下去；然后又挺枪纵马，上前斩了曹性报回一箭之仇。", advancedTroops="重骑兵、铁骑兵", combination="魏武强将(成员:夏侯渊(魏)、夏侯惇(魏)、曹洪(魏)、曹仁(魏),加成属性:攻击、速度)", policyName="筑塘灌田", policyText="令势力粮草产量增加7500，屯田时粮草收益增加20.0%" };
yield return new GeneralDefinition("s1_100631","严颜",Homeland.Han,5,83,"断首何怒","严颜·蜀·骑·5星。招募记录：厉兵秣马；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100631.html", evidence="招募记录：厉兵秣马；仅作试玩池依据，开放条件未复刻", nativeSkill="断首何怒", nativeSkillText="战斗中，自身受到伤害后有60.0%的几率使伤害来源的下一次攻击和策略攻击伤害下降42.0%（受防御属性影响）。同时每回合行动时使自身受到的所有伤害降低80.0%，每当受到攻击或策略攻击伤害后，减伤效果将降低1/5", defense=97, strategy=68, speed=84, cost=3, attackGrowth=1.71, defenseGrowth=2.14, strategyGrowth=0.89, speedGrowth=1.47, siege=5, siegeGrowth=0.39, attackDistance=2, biography="【史】东汉末年武将，初为刘璋部下，担任巴郡太守。建安十九年，刘备进攻江州，严颜战败被俘，张飞对严颜说：“大军至，何以不降而敢拒战？”，严颜回答说：“卿等无状，侵夺我州，我州但有断头将军，无降将军也！”，张飞生气，命左右将严颜牵去砍头，严颜表情不变地说：“砍头便砍头，何为怒邪！”张飞敬佩严颜的勇气，遂释放严颜并以严颜为宾客，之后的事迹不在正史中出现。\n【演】在《三国演义》中，严颜在刘备攻取成都，径取汉川中登场。擅使硬弓和大刀，有万夫莫敌之勇。据守巴郡，与张飞交战，后为张飞用计俘虏。张飞质问：“大将在这里，为什么不投降，而敢率军拒敌？”颜宁死不屈，张飞壮而释之，引为上宾，严颜感概张飞的恩义而归降。", advancedTroops="重骑兵、轻骑兵", combination="老当益壮(成员:黄盖(吴)、严颜(蜀)、黄忠(蜀),加成属性:防御、攻城)", policyName="豪杰壮气", policyText="可担任主城参军，所属部队完成贼寇作乱时，可额外恢复大营武将40点体力，同时所属部队中蜀阵营武将所在部队驻守时，体力消耗降低50.0%" };
yield return new GeneralDefinition("s1_100424","小乔＆大乔",Homeland.Han,5,80,"双艳","小乔＆大乔·吴·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100424.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="双艳", nativeSkillText="使敌军群体陷入暴走状态，并有100.0%的几率使其攻击距离-1，持续2回合", defense=50, strategy=88, speed=31, cost=3.5, attackGrowth=1.14, defenseGrowth=0.88, strategyGrowth=1.55, speedGrowth=0.5, siege=30, siegeGrowth=2.88, attackDistance=2, biography="【史】小乔、大乔分别为周瑜、孙策之妾。两人并称为“江东二乔”，是三国时期世人皆知的绝色美女，均受到世人的追捧。\n【演】在《三国演义》中，诸葛亮谎称曹操南下的目的之一就是小乔与大乔，以此激怒周瑜同意联刘抗曹。", advancedTroops="长枪兵、禁卫", combination="二乔(成员:小乔(吴)、大乔(吴)、小乔＆大乔(吴)、孙策(吴)、周瑜(吴),加成属性:谋略)", policyName="玉楼金阙", policyText="令势力木材产量提高3800，石料产量提高3800" };
yield return new GeneralDefinition("s1_100707","卫瓘",Homeland.Han,5,88,"持节镇西","卫瓘·晋·步·5星。招募记录：国士无双、群雄割据；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="晋", troop="步", sourceUrl="https://stzb.163.com/herolist/100707.html", evidence="招募记录：国士无双、群雄割据；仅作试玩池依据，开放条件未复刻", nativeSkill="持节镇西", nativeSkillText="使友军全体在每次造成攻击伤害前，攻击提高22.0（受攻击属性影响），可叠加4次，持续1回合；每次造成策略攻击伤害前，谋略提高22.0（受谋略属性影响），可叠加4次，持续1回合；每次受到伤害前，防御提高22.0（受防御属性影响），可叠加4次，持续1回合", defense=84, strategy=85, speed=52, cost=3, attackGrowth=1.62, defenseGrowth=1.55, strategyGrowth=1.57, speedGrowth=0.78, siege=15, siegeGrowth=1.35, attackDistance=2, biography="【史】魏晋时期重臣、书法家。早年担任曹魏尚书郎，历任散骑常侍、侍中、廷尉。在魏灭蜀之战中，以镇西军司的身份，持节监军，蜀汉灭亡后，受命逮捕邓艾，之后平定钟会、姜维的叛乱，并命令田续杀害邓艾父子，因此被名将杜预批评。以功封镇东将军，都督徐州诸军事，封菑阳侯。西晋时期，进爵为公，累迁征东将军、征东大将军、征北大将军，历任青州刺史、青州牧、幽州刺史，在青州、幽州颇有建树。后徵拜尚书令，加侍中，历任司空、太子少傅、太保，录尚书事，在朝堂有巨大影响力。在贾南风发动的政变中，不肯对抗矫诏的楚王司马玮，满门遇害。卫瓘擅长草书，与索靖并称「一台二妙」，书法影响极为深远。\n【演】在《三国演义》中，卫瓘生平与正史相似，在魏灭蜀之战中以监军身份登场，劝阻钟会斩杀诸葛绪，然后奉司马昭之命，逮捕邓艾，随后在钟会叛乱时，率领众将击败钟会、姜维，并因为害怕邓艾报复，派遣田续谋害了邓艾父子，之后留守成都，再未出场。", advancedTroops="重步兵、长枪兵", combination="", policyName="监抚军眾", policyText="令势力获得监军计略，可消耗2点政令派遣部队前往己方或友方领地进行驻守，在驻守期间令在该领地上驻守的所有己方部队进入战斗时，有80.0%几率使己方全体武将在本场战斗中士气提升5点" };
yield return new GeneralDefinition("s1_100574","陆抗",Homeland.Han,5,82,"西陵克晋","陆抗·吴·步·5星。招募记录：群雄割据；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100574.html", evidence="招募记录：群雄割据；仅作试玩池依据，开放条件未复刻", nativeSkill="西陵克晋", nativeSkillText="战斗中，每回合有50.0%的几率使我军当前攻击属性最高的武将对距离4以内的敌军发动一次攻击（伤害率150.0%），我军当前谋略属性最高的武将对距离4以内的敌军发动一次策略攻击（伤害率150.0%，受谋略属性影响），并各自恢复一定兵力", defense=93, strategy=93, speed=43, cost=3, attackGrowth=1.07, defenseGrowth=1.77, strategyGrowth=2.05, speedGrowth=0.56, siege=16, siegeGrowth=1.4, attackDistance=2, biography="【史】三国时期吴国名将，丞相陆逊次子。陆抗袭父爵为江陵侯，为建武校尉，领其父众五千人。后迁立节中郎将、镇军将军等。孙皓为帝，任镇军大将军、都督西陵、信陵、夷道、乐乡、公安诸军事，驻乐乡。凤凰元年，击退晋将羊祜进攻，并击败叛将西陵督步阐。与陆逊皆是吴国的中流砥柱，并称“逊抗”，被誉为吴国最后的名将。\n【演】陆抗足智多谋，率众平定了西陵步阐的叛乱。又奉命屯兵江口，以图襄阳。晋派羊祜镇守襄阳，陆抗与羊祜英雄相惜，自守疆界，不动干戈。又上疏说：“晋不可伐，劝君主实施仁德，修养生息。”来回复君主孙皓攻打襄阳的计划。孙皓大怒，以为陆抗与敌人私通，削去了他的兵权，令孙冀代替他。这时羊祜上表劝晋主伐吴，几年后陆抗死去。", advancedTroops="重步兵、长枪兵", combination="", policyName="清白忠勤", policyText="增强瞭望塔政策，令瞭望塔视野增加2，但耐久上限降低40.0%，同时己方部队驻守己方瞭望塔时行军速度提高40.0%" };
yield return new GeneralDefinition("s1_100811","司马徽",Homeland.Han,5,55,"徽言龙凤","司马徽·群·步·5星。招募记录：群雄割据；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100811.html", evidence="招募记录：群雄割据；仅作试玩池依据，开放条件未复刻", nativeSkill="徽言龙凤", nativeSkillText="友军全体共计造成6次伤害后，使友军全体获得以下效果：士气提升10.0（受谋略属性影响）；每回合行动时造成的所有伤害提升7.0%（受谋略属性影响），可叠加；每回合行动时有60.0%的几率对随机敌军单体造成1次攻击伤害（伤害率150.0%）或策略攻击伤害（伤害率120.0%，受谋略属性影响），由攻击或谋略属性中较高的属性决定", defense=83, strategy=93, speed=45, cost=3, attackGrowth=0.64, defenseGrowth=1.7, strategyGrowth=2.25, speedGrowth=0.6, siege=16, siegeGrowth=0.9, attackDistance=2, biography="【史】东汉末年名士，精通道学、奇门、兵法、经学。有“水镜先生”之称。司马徽为人清雅，学识广博，有知人之明，并向刘备推荐了诸葛亮、庞统等人，受到世人的敬重。\n【演】刘备马跃檀溪后，偶然相遇司马徽。司马徽向刘备举荐诸葛亮和庞统，并称诸葛亮为“卧龙”，庞统为“凤雏”，刘备随后夜宿庄院。次日，司马徽自称“山野闲散之人”，谢绝了刘备请求他出山辅佐的好意。不久，赵云率军寻找到庄前，刘备便随赵云离开。其后，刘备准备拜访诸葛亮，司马徽想要探访徐庶，但徐庶已经中曹操的计策前往许昌，刘备向司马徽提起徐庶举荐诸葛亮的事情，司马徽再次力荐诸葛亮。", advancedTroops="重步兵、长枪兵", combination="", policyName="躬耕乐道", policyText="可担任主城或分城参军，令该城池补给范围内的采垦场产量提升效果额外提升20.0%" };
yield return new GeneralDefinition("s1_100630","皇甫嵩",Homeland.Han,5,92,"京观垒冢","皇甫嵩·汉·步·5星。招募记录：群雄割据；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="汉", troop="步", sourceUrl="https://stzb.163.com/herolist/100630.html", evidence="招募记录：群雄割据；仅作试玩池依据，开放条件未复刻", nativeSkill="京观垒冢", nativeSkillText="自身造成伤害时，有70.0%几率对目标额外发动一次攻击（伤害率200.0%）或策略攻击（伤害率200.0%）", defense=75, strategy=88, speed=47, cost=3, attackGrowth=1.83, defenseGrowth=1.19, strategyGrowth=1.75, speedGrowth=0.62, siege=16, siegeGrowth=1.39, attackDistance=3, biography="【史】为人仁爱谨慎，尽忠职守，有谋略，有胆识。于黄巾起义时，以中郎将身份讨伐黄巾，用火攻大破张梁、张宝，拜左车骑将军。后因拒绝贿赂宦官而被免职。董卓掌权时，征皇甫嵩入朝为城门校尉，因私怨被其陷害下狱，经其子皇甫坚寿求情才得以保全。\n【演】在《三国演义》中，皇甫嵩形象与正史相似。于黄巾起义时，大破张梁、张宝。后接替董卓进攻张梁，连胜七阵。掘张角墓，拜左车骑将军、冀州牧，因拒绝贿赂宦官而被免职。董卓死，王允命其与吕布等共至郿坞抄籍董卓家产、人口，皇甫嵩将坞中所藏良家子女，尽行释放。", advancedTroops="长枪兵、禁卫", combination="末路尽忠(成员:卢植(汉)、皇甫嵩(汉)、朱儁(汉)、张奂(汉),加成属性:防御、速度、镇静)、汉朝官军(成员:皇甫嵩(汉)、何进(汉)、朱儁(汉),加成属性:攻击)", policyName="将门孝廉", policyText="执行巡察时，多生成1个战法演练事件，可获得400战法经验；完成战法演练时，额外获得80战法经验" };
yield return new GeneralDefinition("s1_100702","司马昭",Homeland.Han,5,82,"怀德畏威","司马昭·晋·骑·5星。招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="晋", troop="骑", sourceUrl="https://stzb.163.com/herolist/100702.html", evidence="招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻", nativeSkill="怀德畏威", nativeSkillText="令谋略最低的友军单体对敌军随机单体发动一次攻击（伤害率160.0%）；自身对敌军群体2目标发动一次策略攻击（伤害率160.0%，受谋略属性影响）。若2次目标均为同一武将，则使其陷入混乱状态，持续1回合", defense=83, strategy=91, speed=92, cost=3, attackGrowth=1.23, defenseGrowth=1.68, strategyGrowth=1.99, speedGrowth=1.54, siege=5, siegeGrowth=0.45, attackDistance=2, biography="【史】司马师之弟，司马炎之父。三国时期曹魏权臣，西晋王朝的奠基人之一。司马昭早年随父亲司马懿抗击蜀汉，嘉平四年进为都督，与吴国大战于东关。司马师病逝后司马昭继其兄位，大权独揽，并率军镇压诸葛诞的反叛。魏甘露五年，魏帝曹髦愤而言左右称“司马昭之心，路人皆知也”，亲率宫人迎战司马昭。弑帝后的司马昭掌握实权，立曹奂为魏元帝后成功灭蜀。\n【演】在《三国演义》中，司马昭随司马懿、司马师共同参与讨伐孟达、防守诸葛亮北伐、火烧上方谷等事件。因为觉得曹髦不甘成为傀儡，司马昭担心不早处理会生变故，故授意贾充将其杀害。", advancedTroops="重骑兵、轻骑兵", combination="司马氏霸府(成员:司马昭(晋)、司马师(晋)、司马懿(魏)、司马炎(晋)、司马攸(晋)、司马懿(晋),加成属性:防御、谋略)", policyName="慑贼以威", policyText="令势力获得劝降计略，消耗1点政令派遣部队出征目标地块，本次出征中发生战斗时，有60.0%几率使敌军全体武将在本场战斗中士气降低10点" };
yield return new GeneralDefinition("s1_100706","王元姬",Homeland.Han,5,69,"明慧通透","王元姬·晋·弓·5星。招募记录：乱世英雄、募将强军；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="晋", troop="弓", sourceUrl="https://stzb.163.com/herolist/100706.html", evidence="招募记录：乱世英雄、募将强军；仅作试玩池依据，开放条件未复刻", nativeSkill="明慧通透", nativeSkillText="移除友军单体有害效果，恢复其大量兵力（恢复率168.0%，受谋略属性影响），并使其在下回合有50.0%概率进入洞察状态", defense=67, strategy=89, speed=66, cost=2.5, attackGrowth=0.84, defenseGrowth=1.03, strategyGrowth=1.65, speedGrowth=0.91, siege=11, siegeGrowth=1.12, attackDistance=3, biography="【史】文明王皇后，讳元姬。西晋时期皇后，是曹魏司徒王朗的孙女、中领军王肃的女儿。\n嫁给洛阳中郎将司马昭，生下司马炎与司马攸。其人颇有远见，预言钟会谋反之事。\n晋武帝司马炎即位后，尊为皇太后，居住于崇化宫。身处太后之位，提倡节俭，身体力行，作为后宫表率。\n泰始四年（268年），王元姬崩逝，终年五十二岁，谥号文明，与晋文帝司马昭合葬于崇阳陵。\n【演】在《三国演义》中，王元姬仅作为为王肃之女、司马昭之妻、司马炎和司马攸之母出场一次，没有任何事迹。", advancedTroops="长弓兵 、死士", combination="", policyName="崇俭抑奢", policyText="施政后，每日首次屯田消耗政令-2，且该次屯田结束时根据佣工所在地块资源种类获得额外80.0%各项资源，并额外获得8000铜钱，24点刷新" };
yield return new GeneralDefinition("s1_100615","马岱",Homeland.Han,5,92,"奉令护蜀","马岱·蜀·骑·5星。招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100615.html", evidence="招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻", nativeSkill="奉令护蜀", nativeSkillText="战斗中，任意友军发动普通攻击、主动战法、追击战法后，马岱的下1次普通攻击造成的伤害提升35.0%（受攻击属性影响），下1次受到的所有伤害降低20.0%（受防御属性影响），以上效果可叠加5次战斗中，任意友军发动普通攻击、主动战法、追击战法后，马岱的下1次攻击造成的伤害提升35.0%（受攻击属性影响），下1次受到的所有伤害降低20.0%（受防御属性影响），以上效果可叠加5次", defense=86, strategy=72, speed=88, cost=3, attackGrowth=2.03, defenseGrowth=1.77, strategyGrowth=0.94, speedGrowth=1.41, siege=6, siegeGrowth=0.47, attackDistance=3, biography="【史】三国时期蜀汉将领，马超的从弟。早年追随马超大战曹操，反攻陇上，围攻成都，汉中之战等。后在诸葛亮病逝后受杨仪派遣斩了蜀将魏延。曾率领军队出师北伐，被魏将牛金击败而退还。官至平北将军，陈仓侯。\n【演】在《三国演义》中，马岱初次登场随马腾入许昌。后来马腾和其余诸子尽皆被害，马岱乔装逃出。马超起兵，马岱随之周旋。曾在潼关前打败钟繇。建安十九年，马岱随马超救援刘璋，曾与张飞大战十余合败北，旋即随马超归降刘备。刘禅登基后，跟随丞相诸葛亮南征孟获和北伐曹魏。马岱久经沙场、多负辛劳，作战冷静而勇猛，深得诸葛亮信任。诸葛亮临终授命于马岱，袭斩魏延。", advancedTroops="轻骑兵、铁骑兵", combination="驰马西凉(成员:马岱(蜀)、马腾(群)、马超(群)、马云禄(蜀)、马超(蜀),加成属性:速度、攻心)", policyName="平北将军", policyText="可担任军事设施参军，令所属部队中骑兵武将征兵铁矿消耗降低30.0%，弓兵武将征兵木材消耗降低30.0%，步兵武将征兵粮草消耗降低30.0%" };
yield return new GeneralDefinition("s1_100585","曹仁",Homeland.Han,5,88,"平壑拒吴","曹仁·魏·步·5星。招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100585.html", evidence="招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻", nativeSkill="平壑拒吴", nativeSkillText="对敌军防御属性最低及兵力最低的单体分别发动一次攻击（伤害率210.0%），同时使敌军群体陷入怯战状态，无法进行普通攻击，持续2回合", defense=96, strategy=74, speed=57, cost=3, attackGrowth=1.81, defenseGrowth=2.26, strategyGrowth=0.74, speedGrowth=0.83, siege=13, siegeGrowth=1.02, attackDistance=2, biography="【史】曹操从弟。三国曹魏名将。从曹操多年，为魏朝立下汗马功劳。破袁术，曹仁所斩获颇多，大破陶谦军及陶谦部将吕由，攻克句阳，生擒吕布的部将刘何，官渡之战中，在隐强打败刘备军、鸡落山之战又战胜袁绍军。\n【演】在《三国演义》中，曹仁于曹操起兵时与曹洪一同前来投奔，并随曹操一同参与讨董战役。后从征袁术、吕布、张绣，参加官渡之战，多立功勋。曹操平定北方后决意南征，曹仁率军先攻刘备，并列八门金锁阵以敌刘备，但阵法却被徐庶所破。赤壁之战后，周瑜乘胜进取荆州，与镇守南郡的曹仁大战，曹仁用曹操遗计诈败引周瑜入城，随命放箭，周瑜中箭败退。然此后反中东吴军士诈降之计，被周瑜击败。", advancedTroops="重步兵、禁卫", combination="魏武强将(成员:夏侯渊(魏)、曹仁(魏)、夏侯惇(魏)、曹洪(魏),加成属性:攻击、速度)", policyName="据守樊城", policyText="可担任主城参军，以该主城耐久恢复速度降低20.0%为代价，令城区耐久上限提高500，如果曹操也在施政，魏阵营武将征兵时间额外降低3.0%" };
yield return new GeneralDefinition("s1_100670","袁绍",Homeland.Han,5,88,"威震河朔","袁绍·群·弓·5星。招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100670.html", evidence="招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻", nativeSkill="威震河朔", nativeSkillText="对敌军群体发动一次攻击（伤害率200.0%），使自身与友军单体的主动战法伤害提升20.0%（受攻击属性影响），持续2回合。此战法每发动一次，其发动率降低10.0%对敌军群体发动一次策略攻击（伤害率240.0%，受谋略属性影响），使自身与友军单体的主动战法伤害提升24.0%（受谋略属性影响），持续2回合。此战法每发动一次，其发动率降低10.0%", defense=79, strategy=83, speed=67, cost=3.5, attackGrowth=1.79, defenseGrowth=1.15, strategyGrowth=1.53, speedGrowth=1.23, siege=11, siegeGrowth=0.97, attackDistance=3, biography="【史】东汉末年军阀，汉末群雄之一。在汉末群雄割据的过程中，袁绍先占据冀州，又先后夺青、并二州，并于建安四年（199年）的易京之战中击败了割据幽州的军阀公孙瓒，统一河北，势力达到顶点。但在建安五年（200年）的官渡之战中大败于曹操。建安七年（202年），袁绍在平定冀州叛乱之后病逝。\n【演】在《三国演义》中，袁绍初为何进党羽。何进被害后，与袁术等共同诛灭宦官。董卓夺权之后，残暴不仁，涂炭生灵。袁绍奔冀州组成十七路诸侯反董卓联合。董卓迁都长安后，袁绍便引诱公孙瓒进攻冀州，并胁迫韩馥控制冀州。随后袁绍为扩大势力范围而相继占领青州、并州。\n袁绍歼灭公孙瓒，平定幽州之后，在河北建立起庞大的势力。为了与曹操一决雌雄，袁绍遣七十万兵越过黄河，却于官渡之战中被火烧乌巢，惨遭落败。最终，袁绍与曹操在仓亭决战，败归后不久病死。", advancedTroops="长弓兵 、弩兵", combination="", policyName="政宽德民", policyText="势力位于冀州、并州的部队，征兵资源消耗降低10.0%，同时在外征兵消耗铜钱降低30.0%，势力位于冀州、并州的5级及以下土地与采垦场，产量额外增加100" };
yield return new GeneralDefinition("s1_100620","张绣",Homeland.Han,5,90,"宣威再战","张绣·群·骑·5星。招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100620.html", evidence="招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻", nativeSkill="宣威再战", nativeSkillText="战斗开始后前3回合，普通攻击后对攻击目标发动一次攻击（伤害率150.0%）；第4回合起，普通攻击后对敌军单体随机发动1-3次攻击（伤害率150.0%），每次目标独立判定", defense=85, strategy=68, speed=85, cost=3, attackGrowth=2.13, defenseGrowth=1.72, strategyGrowth=0.79, speedGrowth=1.42, siege=2, siegeGrowth=0.23, attackDistance=1, biography="【史】骠骑将军张济的从子。东汉末年割据宛城的军阀，汉末群雄之一。初随张济征伐，张济死后与刘表联合。后降曹操，因不满其言行而突袭曹操，复与刘表联合。官渡之战前夕，听从贾诩的建议再次投降曹操，参加官渡之战，官至破羌将军，封宣威侯。在北征乌桓（207年）途中去世（一说为曹丕逼死），谥定侯。\n【演】在《三国演义》中，张绣是骠骑将军张济的侄子。建安元年，张济因军中缺粮，自关中引兵入荆州界，与刘表交战，攻穰城，中流矢而死。建安二年，曹操南征，部队到达淯水，张绣率众投降。曹操纳了张济的遗孀邹夫人，张绣因此怀恨曹操。后来，张绣偷袭曹操，曹操战败，长子曹昂，侄子曹安民被害，猛将典韦战死。\n张绣引兵追击，被曹操击退，于是张绣退回防守穰城，再次与刘表联盟。建安四年，张绣听从贾诩的建议，再次向曹操投降。张绣到达后，曹操牵着张绣的手，一起参加宴会，为自己的儿子曹均娶了张绣的女儿，并封张绣为扬武将军。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="乱世军阀", policyText="可担任军事设施参军，令所属己方部队攻打山寨胜利后额外获得1500铜钱" };
yield return new GeneralDefinition("s1_100451","关羽",Homeland.Han,5,102,"樊渊泅囚","关羽·蜀·骑·5星。招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100451.html", evidence="招募记录：乱世英雄；仅作试玩池依据，开放条件未复刻", nativeSkill="樊渊泅囚", nativeSkillText="1回合准备，对敌军全体发动一次猛攻（伤害率190.0%），并使其陷入犹豫状态，持续1回合", defense=90, strategy=83, speed=95, cost=3, attackGrowth=2.54, defenseGrowth=1.58, strategyGrowth=1.08, speedGrowth=1.81, siege=5, siegeGrowth=0.44, attackDistance=2, biography="【史】蜀汉名将，是刘备、张飞的结义兄弟。早期跟随刘备辗转各地，曾被曹操生擒，于白马坡斩袁绍大将颜良，与张飞一同被称为万人敌。赤壁之战后，刘备助东吴周瑜攻打南郡曹仁，别遣关羽绝北道，阻挡曹操援军，曹仁退走后，关羽被刘备任命为襄阳太守。刘备入益州，关羽留守荆州。建安二十四年，关羽围襄樊，擒于禁，斩庞德，威震华夏，曹操曾想迁都以避其锐。后曹操派徐晃前来增援，东吴吕蒙又偷袭荆州，关羽腹背受敌，兵败身亡。\n【演】与刘备、张飞桃园结义，羽居其次。使八十二斤青龙偃月刀随刘备东征西讨。汜水关温酒斩华雄，屯土山降汉不降曹。为报恩斩颜良、诛文丑，解曹操白马之围。后得知刘备音信，过五关斩六将，千里寻兄。刘备平定益州后，封关羽为五虎大将之首，督荆州事。羽起军攻曹，放水淹七军，威震华夏。围樊城右臂中箭，幸得华佗医治，刮骨疗伤。但未曾提防东吴袭荆州，关羽父子败走麦城，突围中被捕，不屈遭害。", advancedTroops="轻骑兵、铁骑兵", combination="五虎上将(成员:赵云(蜀)、关羽(蜀)、黄忠(蜀)、马超(蜀)、张飞(蜀),加成属性:攻击)、桃园结义(成员:关羽(蜀)、张飞(蜀)、刘备(蜀)、刘备(汉),加成属性:防御)", policyName="功业垂史", policyText="势力所属部队在己方军事设施内出征且在单场战斗获得2000及以上武勋后，该军事设施所属己方部队出征作战时士气提升10.0，持续30分钟，重复触发刷新持续时间" };
yield return new GeneralDefinition("s1_100452","木鹿大王",Homeland.Han,5,82,"夔吼象踏","木鹿大王·群·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100452.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="夔吼象踏", nativeSkillText="战斗中，使自身进入分兵状态（伤害率60.0%），同时每回合对有效距离4以内的敌军单体发动一次策略攻击（伤害率70.2%，受谋略属性影响）战斗中，使自身进入分兵状态（伤害率60.0%，受谋略属性影响），同时每回合对有效距离4以内的敌军单体发动一次策略攻击（伤害率70.2%，受谋略属性影响）", defense=85, strategy=83, speed=75, cost=3, attackGrowth=1.8, defenseGrowth=1.86, strategyGrowth=1.82, speedGrowth=1.64, siege=16, siegeGrowth=1.44, attackDistance=3, biography="【演】《三国演义》中的虚构人物，八纳洞主，孟获盟友。擅魔法，能改变天气，控制动物并指挥它们作战。在法术帮助下最初对蜀军取得一些胜利，但在诸葛亮的喷火木兽将他的动物吓跑后战败，最后死于乱军之中。", advancedTroops="蛮兵、象兵", combination="", policyName="驭虎驱兽", policyText="令势力所有部队中，象兵、蛮兵、藤甲兵武将体力上限增加30" };
yield return new GeneralDefinition("s1_100704","文鸯",Homeland.Han,5,105,"盛气横凌","文鸯·晋·骑·5星。招募记录：南蛮入侵；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="晋", troop="骑", sourceUrl="https://stzb.163.com/herolist/100704.html", evidence="招募记录：南蛮入侵；仅作试玩池依据，开放条件未复刻", nativeSkill="盛气横凌", nativeSkillText="普通攻击后，对攻击目标再次发动猛攻（伤害率260.0%）。若攻击目标士气高昂，则使其陷入混乱状态，持续1回合；若攻击目标士气一般或低落，则额外对其发动一次攻击（伤害率80.0%-160.0%）", defense=85, strategy=25, speed=99, cost=3.5, attackGrowth=2.48, defenseGrowth=2.05, strategyGrowth=0.38, speedGrowth=2, siege=3, siegeGrowth=0.27, attackDistance=3, biography="【史】本名文俶，小名阿鸯，以文鸯之名流传于世。文钦之子，文虎之兄，是魏晋时期的名将。\n文鸯武艺非凡，在司马师行废立之事后，随父亲文钦与毌丘俭一同在淮南起兵反叛司马氏。曾以少量兵力冲击司马师大营，引发司马师病情加重，间接加速了司马师死亡。\n兵败后逃往吴国，随父亲文钦率军支援诸葛诞的反叛。因诸葛诞杀害文钦，文鸯与文虎重新归顺司马昭。\n西晋时期，任平虏护军，曾督凉秦雍三州军事，大破鲜卑首领秃发树机能，名闻天下。\n后迁东夷校尉，假节，上任前被晋武帝司马炎借口免官。又因诸葛诞外孙东安公司马繇诬陷文鸯谋反，被夷三族，年仅五十四岁。\n【演】在《三国演义》中，文鸯本名为文淑。文鸯在毌丘俭、文钦叛乱和诸葛诞叛乱中登场，具体事迹与正史相似。", advancedTroops="轻骑兵、铁骑兵", combination="一门虎将(成员:文虎(晋)、文鸯(晋)、文钦(魏),加成属性:攻击)", policyName="奇袭敌营", policyText="可担任军事设施参军，令所属己方部队向距离10以内敌方建筑出征时行军速度提升20.0点" };
yield return new GeneralDefinition("s1_100705","杜预",Homeland.Han,5,84,"三军夺帅","杜预·晋·弓·5星。招募记录：南蛮入侵；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="晋", troop="弓", sourceUrl="https://stzb.163.com/herolist/100705.html", evidence="招募记录：南蛮入侵；仅作试玩池依据，开放条件未复刻", nativeSkill="三军夺帅", nativeSkillText="自身每成功发动普通攻击、主动及追击战法后，自身对距离5以内敌军单体发动一次攻击（伤害率180.0%）并使自身攻击属性提高10.0，或对敌军群体2目标发动一次策略攻击（伤害率100.0%，受谋略属性影响）并使目标谋略属性降低5.0，属性变化可叠加，持续到战斗结束", defense=86, strategy=95, speed=50, cost=3.5, attackGrowth=1.55, defenseGrowth=1.58, strategyGrowth=2.29, speedGrowth=0.92, siege=6, siegeGrowth=0.53, attackDistance=3, biography="【史】三国魏晋时期军事家、经学家、律学家。\n曹魏尚书仆射杜畿之孙、散骑常侍杜恕之子，因杜恕与司马懿不和，故而杜预久未得用。司马昭掌权期间，娶高陆公主，拜尚书郎，袭祖爵丰乐亭侯。\n后转参相府军事，历任镇西长史、河南尹、安西军司、秦州刺史、东羌校尉、轻车将军等职，假节，之后又担任度支尚书。\n积极支持司马炎的灭吴战略，羊祜去世前推荐杜预接替，于是杜预又担任镇南大将军、都督荆州诸军事，是灭吴之战的统帅之一，以功封当阳县侯。又任司隶校尉，加位特进，卒于任上。\n杜预博学多才，与贾充一起修《晋律》，并进行注解；所撰《春秋左氏经传集解》流传至今；兴修水利，勤于讲武，被称为“杜父”。又因精通多才，被誉为“杜武库”。同时也因最喜欢左传，自称“左传癖”。\n是明朝之前唯一一位同时进入文庙和武庙之人。\n【演】在《三国演义》中，杜预登场于最后一回，受羊祜病危之时的举荐，担任镇南大将军参与伐吴，击败孙歆、陆景、伍延，并上表司马炎劝其继续进军，使司马炎下定决心，下令征进。最终吴主孙皓投降，三分归一统。", advancedTroops="长弓兵 、弩兵", combination="", policyName="武库尚书", policyText="每天$12$点会获得上谏陈情，可采纳任一谏言：\n·储备物资：完成后获得木材、铁矿、粮草资源各60000\n·筹措军饷：完成后获得15000铜钱\n·部队操演：派遣部队操演后可获得60000武将经验\n·战法演练：完成后可获得350战法经验" };
yield return new GeneralDefinition("s1_100524","沙摩柯",Homeland.Han,5,95,"落首箭","沙摩柯·蜀·弓·5星。招募记录：南蛮入侵；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="蜀", troop="弓", sourceUrl="https://stzb.163.com/herolist/100524.html", evidence="招募记录：南蛮入侵；仅作试玩池依据，开放条件未复刻", nativeSkill="落首箭", nativeSkillText="1回合准备，对敌军单体发动一次猛攻（伤害率300.0%），并对敌军大营再度发动一次攻击（伤害率180.0%），同时使敌军大营陷入混乱状态，持续1回合-2回合1回合准备，对敌军单体发动一次猛攻（伤害率300.0%），并对敌军大营再度发动一次攻击（伤害率180.0%），同时使敌军大营陷入混乱状态并且受到所有伤害增加20.0%（受攻击属性影响），持续1回合-2回合", defense=90, strategy=36, speed=71, cost=3.5, attackGrowth=2.61, defenseGrowth=1.89, strategyGrowth=0.4, speedGrowth=1.37, siege=9, siegeGrowth=0.78, attackDistance=3, biography="【史】三国时期五溪蛮首领。为报关羽被东吴所害之仇，刘备亲自领兵攻孙权，以金锦爵赏诱沙摩柯助战。沙摩柯率一万余人响应蜀军，表现活跃。章武二年（222年），吴大都督陆逊以火攻破刘备，率诸军齐击，蜀军四十多个营寨被攻破，沙摩柯在大乱中匹马奔逃，死于乱军。\n【演】为刘备伐吴的援军。生得面如噀血，碧眼突出，使一个铁蒺藜骨朵，腰带两张弓，威风抖擞。伐吴期间，曾一箭射死东吴猛将甘宁。后刘备兵败，沙摩柯被东吴大将周泰所害。", advancedTroops="死士、蛮兵", combination="", policyName="五溪蛮夷", policyText="可担任军事设施参军，令所属己方武将处于疲劳状态时，每900秒钟额外恢复1点体力，同时使所属己方部队向5级以下土地出征时，行军速度额外增加5.0%" };
yield return new GeneralDefinition("s1_100007","卢植",Homeland.Han,5,108,"将倾之柱","卢植·汉·骑·5星。招募记录：蜀汉名将；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100007.html", evidence="招募记录：蜀汉名将；仅作试玩池依据，开放条件未复刻", nativeSkill="将倾之柱", nativeSkillText="对敌军群体发动一次策略攻击（伤害率85.0%，受谋略属性影响），使自身受到攻击与策略攻击的伤害下降49.0%（受防御属性影响）持续2回合", defense=132, strategy=123, speed=89, cost=3, attackGrowth=0.75, defenseGrowth=1.32, strategyGrowth=0.82, speedGrowth=1.53, siege=7, siegeGrowth=0.67, attackDistance=1, biography="【史】东汉名臣，刘备和公孙瓒之师。黄巾起义时为北中郎将，率军与张角交战，后被诬陷下狱，皇甫嵩平定黄巾后力救卢植，于是复任为尚书。后因上谏激怒董卓被免官，隐居在上谷军都山，被袁绍请为军师。\n【演】在《三国演义》中，卢植为汉末大儒，名望远闻于时。刘备曾经从师于他。黄巾起义，卢植奉命镇压，以三万精锐，包围了广宗城张角的十五万人马，未见胜负，因拒绝黄门左丰索要贿赂，而被诬陷罢职问罪。何进招董卓进京诛宦臣。卢植力谏，何进不听。于是辞官而去。董卓得政后，卢植又复职，谏阻董卓废少帝立陈留王。", advancedTroops="禁卫、重骑兵", combination="末路尽忠(成员:朱儁(汉)、皇甫嵩(汉)、卢植(汉)、张奂(汉),加成属性:防御、速度、镇静)", policyName="国之桢干", policyText="可担任戍城参军，令所属部队与补给范围内领地守军战斗时获得经验提高20.0%，汉阵营武将额外获得4000经验" };
yield return new GeneralDefinition("s1_100486","潘凤",Homeland.Han,5,89,"上将潘凤","潘凤·汉·骑·5星。招募记录：蜀汉名将；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100486.html", evidence="招募记录：蜀汉名将；仅作试玩池依据，开放条件未复刻", nativeSkill="上将潘凤", nativeSkillText="对敌军单体发动一次猛攻（伤害率355.0%），下一回合内，自身将会陷入混乱", defense=80, strategy=42, speed=85, cost=3, attackGrowth=1.41, defenseGrowth=1.15, strategyGrowth=0.44, speedGrowth=1.34, siege=3, siegeGrowth=0.24, attackDistance=2, biography="【演】《三国演义》中的虚构人物，冀州牧韩馥属下，善使大斧，于诸侯讨董之汜水关战中，遭华雄击败而被斩。韩馥经典语曰：吾有上将潘凤，可斩华雄。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="斧失三合", policyText="可担任军事设施参军，令所属己方部队与其他势力战斗在前三回合内失败时可回复10点体力，但该军事设施所属己方部队武将重伤时间延长1800秒" };
yield return new GeneralDefinition("s1_100570","何进",Homeland.Han,4,81,"龙骧虎步","何进·汉·骑·4星。招募记录：蜀汉名将；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100098.html", evidence="招募记录：蜀汉名将；仅作试玩池依据，开放条件未复刻", nativeSkill="龙骧虎步", nativeSkillText="准备1回合，对敌军群体发动一次猛击（伤害率200.0%），并使自身攻击、防御属性提升20.0，持续2回合。", defense=73, strategy=42, speed=83, cost=2, attackGrowth=1.14, defenseGrowth=0.95, strategyGrowth=0.4, speedGrowth=1.08, siege=5, siegeGrowth=0.28, attackDistance=2, biography="【史】东汉灵帝时外戚，何进的异母妹有宠于灵帝并被立为皇后，他也随之升迁。黄巾起义时，为大将军。灵帝驾崩后，何进从袁绍之言，博征智谋之士为己所用。自此独揽大权。然而何进不纳陈琳之谏，多结外镇军阀，翘首京师，与袁绍等谋诛宦竖。终于事泄，被张让等先下手为强，遇刺身亡。\n【演】在《三国演义》中，何进本为屠夫，因为其妹入宫为皇后，以外戚身份入仕。对于是否诛灭当权宦官，犹豫不决。在袁绍建议下，决定除去十常侍，但不听众人劝告，召董卓带兵入京。宦官们知道外兵入京要对付自己，十常侍之首张让设计让何太后召何进入宫，并埋伏了刀斧手五十人于长乐宫嘉德门内，何进中了埋伏，被斩。", advancedTroops="重骑兵、轻骑兵", combination="宦官斗外戚(成员:何进(汉)、何太后(汉)、十常侍(汉),加成属性:攻击距离提高)、汉朝官军(成员:皇甫嵩(汉)、何进(汉)、朱儁(汉),加成属性:攻击)", policyName="召师入朝", policyText="令势力所有部队向主城行军时，行军速度提升20.0" };
yield return new GeneralDefinition("s1_100772","许攸",Homeland.Han,4,55,"计焚乌巢","许攸·群·骑·4星。招募记录：群雄名将；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100772.html", evidence="招募记录：群雄名将；仅作试玩池依据，开放条件未复刻", nativeSkill="计焚乌巢", nativeSkillText="1回合准备，对敌军单体发动一次策略攻击（伤害率160.0%,受谋略属性影响），使有效距离内最远的敌军受到主动战法伤害提升15.0%（受谋略属性影响），并有50.0%几率使其陷入燃烧状态（伤害率120.0%，受谋略属性影响），持续2回合。", defense=65, strategy=91, speed=75, cost=2.5, attackGrowth=0.45, defenseGrowth=0.85, strategyGrowth=1.51, speedGrowth=1.01, siege=5, siegeGrowth=0.25, attackDistance=3, biography="【史】本为袁绍帐下谋士，官渡之战时其家人因犯法而被收捕，许攸因此背袁投曹，并为曹操设下偷袭袁绍军屯粮之所乌巢的计策，袁绍因此而大败于官渡。后许攸随曹操平定冀州，因自恃其功而屡屡口出狂言，终因触怒曹操而被害。\n【演】在《三国演义》中，许攸年轻时与曹操相友善，后来成为袁绍的谋士，多次为袁绍出谋划策，力主攻打曹操都城许昌。官渡之战之际，许攸因家人犯法被收治而投奔曹操，提供了重要情报，建议曹操偷袭乌巢，结果大获全胜。官渡之战后，许攸跟随曹操到达邺城，口出狂言，辱骂曹操，轻视曹军将士，被许褚一怒之下所斩，曹操见后深责许褚，下令厚葬许攸。", advancedTroops="重骑兵、轻骑兵", combination="勾心斗角(成员:许攸(群)、郭图(群)、审配(群),加成属性:谋略、攻击距离提高)", policyName="假公济私", policyText="可担任分城参军，以所属部队的维持消耗增加50.0%、城内设施建造与升级资源消耗提升30.0%为代价，使该分城的税收提升800" };
yield return new GeneralDefinition("s1_100310","邓艾",Homeland.Han,5,92,"险途暗渡","邓艾·魏·步·5星。招募记录：魏晋名将；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100310.html", evidence="招募记录：魏晋名将；仅作试玩池依据，开放条件未复刻", nativeSkill="险途暗渡", nativeSkillText="对敌军群体发动一次攻击（伤害率160.0%），并使其陷入动摇状态，每回合产生逃兵（伤害率80.0%），持续1回合，同时使其士气降低10.0对敌军群体发动一次攻击（伤害率160.0%），并使其陷入动摇状态，每回合产生逃兵（伤害率80.0%），持续1回合，同时使其士气降低10.0。敌军全体每有一个士气一般的武将，使我军单体士气提升5.0，每有一个士气低落的武将，使我军单体士气提升10.0", defense=87, strategy=89, speed=60, cost=3, attackGrowth=1.61, defenseGrowth=1.53, strategyGrowth=1.15, speedGrowth=0.87, siege=24, siegeGrowth=1.88, attackDistance=2, biography="【史】魏国名将。其人文武全才，深谙兵法，对内政也颇有建树。被推崇为古今六十四名将之一。邓艾多年在曹魏西边战线防备蜀汉姜维。公元263年他与钟会分别率军攻打蜀汉，最后他率先进入成都，使得蜀汉灭亡。后因遭到钟会的污蔑和陷害，被司马昭猜忌而被收押，最后与其子邓忠一起被卫瓘派遣的武将田续所害。\n【演】在《三国演义》中，邓艾资性敏捷、善识地理，司马懿以为奇才。其生平基本与正史相同。", advancedTroops="重步兵、长枪兵", combination="", policyName="积粮垦荒", policyText="令势力屯田资源收益提高30.0%，在城邑补给范围内屯田时收益额外提高15.0%" };
yield return new GeneralDefinition("s1_100074","姜维",Homeland.Han,5,92,"列营守险","姜维·蜀·步·5星。招募记录：蜀汉名将；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100074.html", evidence="招募记录：蜀汉名将；仅作试玩池依据，开放条件未复刻", nativeSkill="列营守险", nativeSkillText="使我军全体攻击、防御、速度、谋略属性提高29.2（受谋略属性影响），持续2回合，同时友军全体受到下3次伤害时有50.0%几率进入规避状态，免疫该次伤害。若自身士气高昂时，规避状态的目标变为我军全体使我军全体攻击、防御、速度、谋略属性提高29.2（受谋略属性影响），持续2回合，同时我军全体受到下3次伤害时有50.0%几率进入规避状态，免疫该次伤害", defense=89, strategy=91, speed=29, cost=2.5, attackGrowth=1.61, defenseGrowth=1.68, strategyGrowth=1.21, speedGrowth=0.39, siege=19, siegeGrowth=1.36, attackDistance=2, biography="【史】三国时蜀汉名将，官至大将军。曾为魏中郎将，诸葛亮北伐时，姜维被怀疑有异心，姜维不得已投降蜀汉。因他忠勤时事、思虑精密、敏于军事、既有胆义，又兼心存汉室，故深得诸葛亮器重。诸葛亮去世后姜维在蜀汉开始崭露头角，费祎死后姜维开始独掌军权，继续率领蜀汉军队北伐曹魏。\n后因蜀中大臣多反对北伐，而宦官黄皓弄权，姜维只得在沓中屯田避祸。后司马昭五道伐蜀，姜维据守剑阁，阻挡钟会大军，却被邓艾从阴平偷袭成都，刘禅投降。后姜维假意投降魏将钟会，打算利用钟会反叛曹魏以实现恢复汉室的愿望，但最终反叛失败，与钟会一同被魏军所害。\n【演】在《三国演义》中，姜维生平与正史相似。在描写姜维降蜀时，在天水中识破设伏的赵云，并劫了诸葛亮的寨。诸葛亮视其为接班人，用计令夏侯楙和马遵误以姜维降蜀，最终使得姜维走投无路而降蜀。", advancedTroops="重步兵、禁卫", combination="", policyName="武侯遗志", policyText="可担任主城、分城或戍城参军，令该城邑视野增加2，同时预警时间增加600秒，城区耐久上限提高300" };
yield return new GeneralDefinition("s1_100522","诸葛恪",Homeland.Han,5,58,"计定山越","诸葛恪·吴·弓·5星。招募记录：东吴名将；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100522.html", evidence="招募记录：东吴名将；仅作试玩池依据，开放条件未复刻", nativeSkill="计定山越", nativeSkillText="1回合准备，使敌军群体陷入恐慌状态，每回合失去一定兵力（伤害率134.0%，受谋略属性影响），若敌军群体士气一般或低落，则额外使其陷入围困状态，无法恢复兵力，持续2回合。使自身和友军单体恢复一定兵力（恢复率98.0%，受谋略属性影响）。", defense=88, strategy=90, speed=50, cost=3, attackGrowth=1.02, defenseGrowth=1.94, strategyGrowth=1.71, speedGrowth=0.73, siege=10, siegeGrowth=0.87, attackDistance=3, biography="【史】诸葛瑾的长子，从小就以才思敏捷、善于应对著称，曾任丹杨太守，为吴国征得大量兵源。孙亮继位后，诸葛恪掌握了吴国大权，率军抵挡了魏国三路进攻，在东兴大胜魏军。此后，诸葛恪开始轻敌，率大军伐魏，围攻新城不下，士卒因疾病死伤惨重，回军后为掩饰过失，更加独断专权。不久，诸葛恪被孙峻联合吴主孙亮设计所诛，被夷灭三族。\n【演】在《三国演义》中，诸葛恪曾为吴太子孙登的太子左辅。孙亮继位后，诸葛恪掌握了吴国大权，率军抵挡了魏国三路进攻，在东兴大胜魏军。此后，诸葛恪开始轻敌，率军二十万伐魏，围攻新城不下，被魏国援军大败，回军后为掩饰过失，更加独断专权。不久，诸葛恪被孙峻联合吴主孙亮设计所诛，被满门抄斩。", advancedTroops="长弓兵 、死士", combination="", policyName="受诏辅政", policyText="使势力执行资源获取（伐木、冶铁、屯粮）事件或任务时，额外获得20.0%资源产量" };
yield return new GeneralDefinition("s1_100696","孔融",Homeland.Han,4,77,"名士在朝","孔融·汉·弓·4星。招募记录：募将强军；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100696.html", evidence="招募记录：募将强军；仅作试玩池依据，开放条件未复刻", nativeSkill="名士在朝", nativeSkillText="使自身和友军单体进入规避状态，免疫接下来受到的1次伤害", defense=80, strategy=83, speed=56, cost=2, attackGrowth=0.64, defenseGrowth=0.7, strategyGrowth=0.92, speedGrowth=0.63, siege=11, siegeGrowth=0.67, attackDistance=3, biography="【史】东汉末年文学家，“建安七子”之一，家学渊源，为孔子的二十世孙。其人少有异才，勤奋好学，性好宾客，喜抨议时政，言辞激烈，后因触怒曹操而为其所害。\n【演】在《三国演义》中，孔融形象与正史相似。十八路诸侯起兵讨董卓，孔融为第十镇。后黄巾将领管亥率兵数万围北海，孔融与之战不利，幸得太史慈求救于刘备。后召还为太中大夫，曹操征荆州时，孔融劝阻，被曹操叱退。孔融口出怨言，为郗虑宾客所听闻。郗虑素来与孔融不睦，于是将此事告诉曹操，孔融被下狱弃市。", advancedTroops="长弓兵 、弩兵", combination="", policyName="为相一方", policyText="令主城所在县内己方土地所有资源产量提高100" };
yield return new GeneralDefinition("s1_100697","陶谦",Homeland.Han,4,69,"三让徐州","陶谦·汉·弓·4星。招募记录：募将强军；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100697.html", evidence="招募记录：募将强军；仅作试玩池依据，开放条件未复刻", nativeSkill="三让徐州", nativeSkillText="第2、3、4回合自身行动时，恢复友军兵力最低单体大量兵力（恢复率168.0%，受谋略属性影响），并使其攻击、谋略与防御属性提升25.0，持续至战斗结束，可叠加", defense=82, strategy=84, speed=45, cost=2.5, attackGrowth=0.64, defenseGrowth=0.83, strategyGrowth=0.9, speedGrowth=0.43, siege=13, siegeGrowth=0.72, attackDistance=3, biography="【史】汉末群雄之一。最初为诸生，在州郡任职，被举茂才，历任舒、卢二县令、幽州刺史、议郎，性格刚直，有大志。后随左车骑将军皇甫嵩对抗北宫伯玉，任扬武校尉，之后又随张温征韩遂、边章。\n【演】在《三国演义》中，陶谦被描述成一副和蔼可亲的老实善人形象，是为参与讨伐董卓的诸侯之一。由于曹操来犯，请求孔融、刘备救援。后来病倒，恳求刘备治理徐州。", advancedTroops="弩兵、死士", combination="", policyName="巡土凿溉", policyText="每天$12$点、$18$点获得耕种陈情，完成后获得48000粮草" };
yield return new GeneralDefinition("s1_100698","简雍",Homeland.Han,4,65,"游议定益","简雍·蜀·步·4星。招募记录：募将强军；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100698.html", evidence="招募记录：募将强军；仅作试玩池依据，开放条件未复刻", nativeSkill="游议定益", nativeSkillText="1回合准备，使敌军群体陷入恐慌状态，每回合损失一定兵力（伤害率98.0%，受谋略属性影响），当其每次进行普通攻击后，将额外受到一次策略伤害（伤害率112.0%，受谋略属性影响），持续2回合", defense=77, strategy=87, speed=40, cost=2.5, attackGrowth=0.7, defenseGrowth=0.72, strategyGrowth=1.26, speedGrowth=0.42, siege=18, siegeGrowth=1.19, attackDistance=2, biography="【史】简雍擅于辩论、议事，官拜昭德将军，地位次于麋竺。其人性情简单直接、不拘小节。年少时便与刘备相识，后跟随刘备奔走。常作为谈客，往来使命，刘备围成都时，简雍劝说刘璋投降。\n【演】在《三国演义》中，简雍形象与正史相似。与刘备同乡。随其周旋，任幕宾。刘备投袁绍，后想要离去，简雍为其设计脱身。刘璋投降时，以简雍为使，简雍坐于车中，有意的傲睨自若，为秦宓所斥责。不久，拜简雍为昭德将军。", advancedTroops="重步兵、长枪兵", combination="", policyName="久旱行议", policyText="令势力屯田时粮草收益增加8.0%；粮草仓储少于上限50%时，粮草产量提升3000" };
yield return new GeneralDefinition("s1_100699","华歆",Homeland.Han,4,62,"登坛相仪","华歆·魏·弓·4星。招募记录：募将强军；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="魏", troop="弓", sourceUrl="https://stzb.163.com/herolist/100699.html", evidence="招募记录：募将强军；仅作试玩池依据，开放条件未复刻", nativeSkill="登坛相仪", nativeSkillText="对敌军群体发动一次策略攻击（伤害率120.0%，受谋略属性影响），并使其每次受到普通攻击时额外引发一次恐慌效果（伤害率43.0%，受谋略属性影响），持续1回合", defense=80, strategy=85, speed=42, cost=2.5, attackGrowth=0.62, defenseGrowth=0.84, strategyGrowth=1.32, speedGrowth=0.44, siege=10, siegeGrowth=0.63, attackDistance=3, biography="【史】华歆，汉末曹魏名臣，官至司徒、太尉。华歆年轻时便名闻山东，曾被时为大将军的何进征召担任尚书郎。因董卓作乱，华歆自请为县令，在上任途中被袁术所留。后因袁术不愿出兵伐董，华歆遂离开袁术担任豫章太守，担任太守期间深得百姓爱戴。华歆欣赏孙策之能，成为了孙策上宾。华歆后被曹操以天子名义征召担任议郎，是迫使汉献帝禅让帝位的主要参与者之一。\n【演】在《三国演义》中，华歆被描写成一个趋炎附势、助纣为虐的政客。演义中华歆为豫章太守，在孙策崛起江东之际降于孙策麾下，但直到孙权时皆未获重用。后作为吴使臣觐见曹操，随即被曹操任命为大理寺卿，留在朝廷。曹丕欲篡汉自立时，华歆自行草诏，并威逼汉献帝承认，成为曹魏开国功臣。", advancedTroops="长弓兵 、弩兵", combination="", policyName="深虑国计", policyText="令势力所有等级低于30级的武将与系统守军战斗时获得的武将经验提升10.0%" };
yield return new GeneralDefinition("s1_100700","朱治",Homeland.Han,4,75,"忧勤王事","朱治·吴·弓·4星。招募记录：募将强军；仅作试玩池依据，开放条件未复刻。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=true, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100700.html", evidence="招募记录：募将强军；仅作试玩池依据，开放条件未复刻", nativeSkill="忧勤王事", nativeSkillText="使自身受到的普通攻击伤害和追击战法伤害降低15.0%，每回合自身行动时额外叠加一次，此效果最多叠加3次，持续至战斗结束；当自身处于前锋时，第3、4、5回合每回合援护友军兵力最低武将", defense=88, strategy=70, speed=42, cost=2.5, attackGrowth=0.8, defenseGrowth=1.44, strategyGrowth=0.72, speedGrowth=0.57, siege=13, siegeGrowth=0.72, attackDistance=2, biography="【史】三国时期吴国武将，东吴名将朱然之嗣父。早年随从孙坚、孙策征伐，又辅助孙权，稳定江东，功勋卓著。此后长期居住在吴郡，孙权为吴王，拜其为安国将军，配金印紫绶，徙封毗陵侯。每次进见，孙权都亲自迎接。黄武三年（224年）卒，年六十九。\n【演】在《三国演义》中，朱治生平与正史大体相当，为孙坚旧将，孙坚阵亡后，孙策附袁术，朱治、吕范为之定计，用玉玺向袁术借兵夺取江东。孙策平定东路后，任命朱治为吴郡太守，收军返回江东。后来赤壁之战，大都督周瑜令朱治、吕范为四方巡警使，催督六郡官军。", advancedTroops="弩兵、死士", combination="", policyName="安国练军", policyText="每日$12$点获得部队操演陈情，派遣部队操演后可获得10000武将经验" };
yield return new GeneralDefinition("s1_100009","董卓",Homeland.Han,5,88,"逆谋","董卓·群·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100009.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="逆谋", nativeSkillText="使自身受到攻击与策略攻击的伤害降低30.0%（受攻击属性影响），在战斗中造成攻击伤害时，能够借此恢复相当于伤害值50.0%的兵力", defense=91, strategy=68, speed=81, cost=3, attackGrowth=2.07, defenseGrowth=2.3, strategyGrowth=0.79, speedGrowth=1.64, siege=10, siegeGrowth=1.01, attackDistance=3, biography="【史】中平六年（189年），受大将军何进、司隶校尉袁绍所召，率军进京讨伐十常侍，却借何进被害之机，得以掌握朝政。他随后废除汉少帝，改立献帝。关东诸侯联盟讨伐董卓，董卓放弃洛阳，移都长安。董卓生性残虐，当权后横征暴敛，激起了民愤，最后被王允和吕布所诛。\n【演】原为汉河东太守，征讨黄巾不利，却因贿赂十常侍官至西凉刺史。董卓借何进被害之机，得以掌握朝政，又赠赤兔马给吕布，诱其投降并谋害丁原，从此不可一世。董卓废汉少帝，立汉献帝，朝臣敢怒不敢言；董卓生性残暴，经常纵兵掠民，百姓皆恨。后来，司徒王允利用貂蝉巧使连环计，使董卓为吕布所诛。", advancedTroops="重骑兵、铁骑兵", combination="行刺太师(成员:王允(汉)、曹操(汉)、董卓(群)、貂蝉(汉),加成属性:攻击、谋略、攻击距离提高)", policyName="横征暴敛", policyText="令势力通过贼寇作乱获得资源提高20000，获得预备兵提高300" };
yield return new GeneralDefinition("s1_100024","荀彧",Homeland.Han,5,47,"驱虎吞狼","荀彧·魏·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100024.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="驱虎吞狼", nativeSkillText="对敌军全体发动策略攻击（伤害率153.0%，受谋略属性影响），并使其陷入围困状态，持续2回合对敌军全体发动策略攻击（伤害率153.0%，受谋略属性影响），并使其陷入围困状态，持续2回合。若有目标已处于围困状态，则使敌军单体陷入暴走状态，持续1回合", defense=89, strategy=96, speed=85, cost=3, attackGrowth=0.55, defenseGrowth=1.56, strategyGrowth=2.25, speedGrowth=1.49, siege=5, siegeGrowth=0.44, attackDistance=2, biography="【史】东汉末年著名政治家、战略家，曹操统一北方的首席谋臣和功臣。荀彧早年被称为“王佐之才”，初举孝廉，任守宫令。后弃官归乡，又率宗族避难冀州，被袁绍待为上宾。其后投奔曹操。官至侍中，守尚书令，封万岁亭侯。因其任尚书令，居中持重达十数年，处理军国事务，被人敬称为“荀令君”。后因反对曹操称魏公而受曹操所忌，调离中枢，在寿春忧郁成病而亡，年五十。获谥敬侯，后追赠太尉。\n【演】在《三国演义》中，荀彧旧从袁绍，因知袁绍终不能成大事遂与其侄荀攸投奔曹操。荀彧为曹操出过很多重要的战略谋划，如以兖州为基地、二虎竞食和驱虎吞狼、迎汉献帝往许都、开玄武湖练水军等等，立有大功。荀彧后为汉侍中、尚书令，参与国家大事並经常留守许都。后来董昭劝曹操称魏公，荀彧表示反对，曹操深感不满，遂将其招入军中，从征孙权。荀彧因病留于寿春，不久在曹操的暗示下服毒自尽。", advancedTroops="重骑兵、轻骑兵", combination="魏之智(成员:贾诩(魏)、程昱(魏)、荀彧(魏)、荀攸(魏)、郭嘉(魏),加成属性:谋略)", policyName="腹心谋臣", policyText="令势力主城所在州己方领地（不含战场与守军城区）耐久上限提高40，由魏阵营武将担任参军的己方要塞及大型要塞补给范围提高1格" };
yield return new GeneralDefinition("s1_100031","周瑜",Homeland.Han,5,70,"玄武洰流","周瑜·吴·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100031.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="玄武洰流", nativeSkillText="1回合准备，对敌军全体发动策略攻击（伤害率150.0%，受谋略属性影响），并使其陷入怯战状态，无法进行普通攻击，持续2回合", defense=92, strategy=98, speed=53, cost=3, attackGrowth=1.23, defenseGrowth=1.34, strategyGrowth=2.3, speedGrowth=0.93, siege=12, siegeGrowth=1.05, attackDistance=4, biography="【史】东汉末年名将。洛阳令周异之子，堂祖父周景、堂叔周忠，都官至太尉。长壮有姿貌、精音律，江东有“曲有误，周郎顾”之语。周瑜少与孙策交好，21岁起随孙策奔赴战场平定江东，后孙策遇刺身亡，孙权继任，周瑜将兵赴丧，以中护军的身份与长史张昭共掌众事。\n建安十三年 （208年），周瑜率军与刘备联合，于赤壁之战中大败曹军，由此奠定了“三分天下”的基础。建安十四年（209年），拜偏将军领南郡太守。建安十五年（210年）病逝于巴丘，年仅36岁。\n【演】在《三国演义》中，为了凸显诸葛亮的智慧，对历史上的周瑜形象做了较大的改动，并虚构了较多的情节，如赤壁之战，周瑜的主张不太明确，是战是和踌躇不定，诸葛亮借曹操修筑铜雀台欲夺小乔之事，智激周瑜，坚定周瑜抗曹的决心。\n曹操命周瑜同窗好友蒋干劝降周瑜，周瑜设下计策，假装友善，伪造了曹操水军都督蔡瑁、张允写给周瑜的降书让蒋干发现，上演了一出“蒋干盗书”的好戏，为赤壁之战的成功奠定了基础。", advancedTroops="长弓兵 、弩兵", combination="苦肉计(成员:黄盖(吴)、甘宁(吴)、周瑜(吴),加成属性:攻击、防御)、东吴大都督(成员:陆逊(吴)、鲁肃(吴)、周瑜(吴)、吕蒙(吴),加成属性:谋略、速度)、二乔(成员:小乔(吴)、大乔(吴)、周瑜(吴)、孙策(吴)、小乔＆大乔(吴),加成属性:谋略)", policyName="雄略安邦", policyText="令势力主城税收提高50.0%，由吴阵营武将担任参军的分城资源产量提高10.0%，担任参军的戍城预备兵恢复速度提高10.0%" };
yield return new GeneralDefinition("s1_100017","诸葛亮",Homeland.Han,5,49,"诸葛锦囊","诸葛亮·蜀·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100017.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="诸葛锦囊", nativeSkillText="使我军全体受到策略攻击时的伤害降低35.0%（受谋略属性影响），并使其进行攻击和策略攻击时的伤害提高14.0%（受谋略属性影响），且自身获得先手，持续2回合。若发动时目标已有诸葛锦囊效果，则额外恢复目标一定兵力（恢复率150.0%）使我军全体受到攻击和策略攻击时的伤害降低35.0%（受谋略属性影响），并使其进行攻击和策略攻击时的伤害提高14.0%（受谋略属性影响），且自身获得先手，持续2回合。若发动时目标已有诸葛锦囊效果，则额外恢复目标一定兵力（恢复率150.0%）", defense=95, strategy=108, speed=22, cost=3, attackGrowth=0.79, defenseGrowth=1.67, strategyGrowth=2.86, speedGrowth=0.39, siege=21, siegeGrowth=2.01, attackDistance=2, biography="【史】政治家、军事家，被誉为“千古良相”的典范。策动孙、刘联盟，于赤壁之战中大破曹操，奠定三国鼎立的基础。蜀汉建立，拜为丞相。刘备伐吴失败，受托孤于永安，辅佐幼主，外联东吴，内修政理，南征平叛，北抗强魏。为完成统一中原，兴复汉室的大业，先后五次进攻魏国。在治国、治军等方面发挥了非凡的才能。最后一次北伐时采取分兵屯田之策，与司马懿大军相持百余日，但不幸因积劳成疾而逝世，享年五十四岁，谥曰忠武侯。\n【演】在《三国演义》中，人称卧龙先生，有经天纬地之才，鬼神不测之机。刘皇叔三顾茅庐，遂允出山相助。曾舌战群儒、借东风、智算华容、三气周瑜，辅佐刘备于赤壁之战大败曹操，更取得荆州为基本。后奉命率军入川，于定军山智激老黄忠，斩夏侯渊，败走曹操，夺取汉中。刘备伐吴失败，受遗诏托孤，安居平五路，七纵平蛮，六出祁山，鞠躬尽瘁，死而后已。其手摇羽扇，运筹帷幄的潇洒形象，千百年来已成为人们心中“智慧”的代名词。", advancedTroops="弩兵、重步兵", combination="蜀之智(成员:徐庶(蜀)、庞统(蜀)、诸葛亮(蜀)、法正(蜀),加成属性:谋略)", policyName="隆中对策", policyText="势力占领的益州、荆州土地所有资源产量提高150" };
yield return new GeneralDefinition("s1_100812","冯嫽",Homeland.Han,5,50,"锦车持节","冯嫽·汉·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100812.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="锦车持节", nativeSkillText="每回合开始前有50.0%几率（受谋略属性影响）使敌军单体本回合内陷入以下两种状态之一：造成所有伤害大幅降低；陷入暴走状态，且攻击距离与主动战法距离-2。以上效果触发后，在回合结束时额外恢复我军兵力最低单体一定兵力（恢复率150.0%，受谋略属性影响）", defense=86, strategy=82, speed=86, cost=3, attackGrowth=0.73, defenseGrowth=1.46, strategyGrowth=1.72, speedGrowth=1.52, siege=12, siegeGrowth=0.79, attackDistance=2, biography="【史】西汉女政治家、外交家。因西汉派去与乌孙国联姻的公主刘细君去世，汉武帝以刘解忧为公主继续与乌孙国联姻，冯嫽作为解忧公主的侍女，共同前往乌孙国。冯嫽懂史书，熟悉事务，曾经作为公主的使者前往西域各国赏赐西域贵族，得到了西域各国的信任和尊敬，号称“冯夫人”，后嫁给乌孙国右大将为妻。\n乌孙国王病逝后，乌孙国贵族未按约定立解忧公主的儿子为王，反而立上一任国王有匈奴血统的儿子为王，史称狂王。解忧公主与汉朝使者设宴刺杀狂王使其受伤逃跑，乌孙国贵族乌就屠趁机袭杀狂王，自立为昆弥（乌孙之王）。冯嫽的丈夫右大将与乌就屠交好，因此西域都护派遣冯夫人前去劝降乌就屠。汉宣帝征召冯夫人亲自过问此事，并正式派遣冯夫人锦车持节，前往乌孙国宣读诏书，最终解忧公主之子担任大昆弥，乌就屠担任小昆弥，共同治理乌孙国。后来解忧公主的儿子去世，冯嫽陪同公主返回长安，但公主之孙、新任大昆弥星靡年幼，冯夫人上书宣帝，希望出使乌孙辅佐星靡。宣帝派一百余人送冯夫人，再次出使乌孙国。\n冯嫽是中国历史上第一位有史料记载的女外交官。", advancedTroops="禁卫、轻骑兵", combination="", policyName="西域珍宝", policyText="市井内新增一个固定商品，可用500铜钱购买一件|西域珍宝|，每日可购买3次，购买后可获得包括四项资源、宝物材料、预备兵、战法经验、政令等商品之一，随着政策等级的提升，获得的商品数量也将随之增加" };
yield return new GeneralDefinition("s1_100337","貂蝉",Homeland.Han,5,75,"白楼独舞","貂蝉·群·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100337.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="白楼独舞", nativeSkillText="战斗开始后前3回合，使敌军群体进行攻击和策略攻击时的伤害降低26.0%（受谋略属性影响），此效果结束后，敌军将陷入暴走状态，进行无差别攻击，持续2回合", defense=72, strategy=88, speed=58, cost=2.5, attackGrowth=1.27, defenseGrowth=1.33, strategyGrowth=1.63, speedGrowth=0.71, siege=17, siegeGrowth=1.73, attackDistance=2, biography="【演】中国古代四大美女之一。其善歌舞，色伎俱佳，凭借自己的美貌智慧在诸侯争霸的战乱年代，辗转于各诸侯之间。她通过王允的安排成为了吕布的妾室，巧施连环计成功诱使吕布诛灭了董卓。", advancedTroops="重步兵、禁卫", combination="温侯无双(成员:陈宫(群)、貂蝉(群)、吕姬(群)、高顺(群)、张辽(群)、吕布(汉)、吕布(群),加成属性:攻击)", policyName="互通有无", policyText="市井中增加一个固定商品,可用{0}铜钱兑换资源包,资源包内包含木材、铁矿、石料、粮草各{1}" };
yield return new GeneralDefinition("s1_100131","赵云",Homeland.Han,4,95,"固军备战","赵云·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100131.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="固军备战", nativeSkillText="受到攻击或策略攻击时，都有50.0%的几率使本次受到的伤害降低60.0%", defense=78, strategy=64, speed=89, cost=3, attackGrowth=1.58, defenseGrowth=1.3, strategyGrowth=0.77, speedGrowth=1.2, siege=3, siegeGrowth=0.22, attackDistance=2, biography="【史】三国时期蜀汉名将。赵云跟随刘备将近三十年，先后参加过博望坡之战、长坂坡之战、江南平定战，独自指挥过入川之战、汉水之战、箕谷之战，都取得了非常好的战果。除了四处征战，赵云还先后以偏将军任桂阳太守，以留营司马留守公安，以翊军将军督江州。除此之外，赵云于平定益州时引霍去病故事劝谏刘备将田宅归还百姓，又于关羽张飞被害之后劝谏刘备不要伐吴，被后世赞为有大臣局量的儒将，甚至被认为是三国时期的完美人物。\n【演】在《三国演义》中，赵云一登场即和河北名将文丑大战，救了公孙瓒。曾和多名三国名将对战，冲锋陷阵罕见败绩。长坂坡救阿斗时，连续阵斩曹营名将五十余员。智取桂阳时，更是展现了他过人的机智和出众的谋略。随诸葛亮吊祭周瑜时，因赵云带剑相随，吴将无人敢动诸葛亮。汉水救黄忠时，让魏国名将张郃、徐晃心惊胆战，不敢迎敌。\n刘备去世之后，曹魏五路犯蜀，赵云把守阳平关，一将当关，万夫莫开。七十几岁时仍为蜀汉先锋，阵前力斩被作者称为“有万夫不当之勇”的西凉大将韩德一门五将。", advancedTroops="轻骑兵、铁骑兵", combination="", policyName="忠上厚下", policyText="可担任戍城参军，令所属部队练兵经验增加9000" };
yield return new GeneralDefinition("s1_100115","高顺",Homeland.Han,4,88,"陷阵营","高顺·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100115.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="陷阵营", nativeSkillText="战斗中使自身处于洞察状态，免疫混乱、犹豫、怯战、暴走和挑衅效果，攻城属性提高40.0", defense=89, strategy=43, speed=91, cost=3, attackGrowth=1.46, defenseGrowth=1.48, strategyGrowth=0.52, speedGrowth=1.37, siege=13, siegeGrowth=1.3, attackDistance=2, biography="【史】吕布帐下中郎将。高顺为人清白有威严，不好饮酒，所统率的部队精锐非常，号称“陷阵营”。屡进忠言于吕布，吕布虽知其忠而不能用。曹操击破吕布后，高顺被曹操所害。\n【演】在《三国演义》的第十八章提到，高顺军在下邳城外与夏侯惇军交战时曾与其单挑。双方大战了四五十个回合夏侯惇击败了高顺，高顺欲退回城内，夏侯惇则令其战马追赶。夏侯惇在追赶高顺途中，被高顺的部下曹性用弓箭射中眼睛，最后，高顺部队反攻夏侯惇的部队而获胜。", advancedTroops="重骑兵、轻骑兵", combination="温侯无双(成员:高顺(群)、吕姬(群)、张辽(群)、貂蝉(汉)、吕布(汉)、陈宫(群)、貂蝉(群)、吕布(群),加成属性:攻击)", policyName="迅析斩乱", policyText="可担任军事设施参军，令所属己方部队出征补给范围内地图建筑时攻城值提高20.0" };
yield return new GeneralDefinition("s1_100050","张辽",Homeland.Han,4,92,"神速奔袭","张辽·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100050.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="神速奔袭", nativeSkillText="对敌军群体发动一次攻击（伤害率200.0%），并使其速度属性降低40.0，持续2回合", defense=88, strategy=63, speed=98, cost=3, attackGrowth=1.24, defenseGrowth=1.33, strategyGrowth=0.75, speedGrowth=1.32, siege=4, siegeGrowth=0.29, attackDistance=1, biography="【史】汉末三国时期曹魏名将。曾从属丁原、董卓、吕布。吕布下邳败亡后，归顺曹操。此后随曹操四处征讨，战功累累。张辽为历代推崇，并成为古今六十四名将之一。曹丕登基后，仍令张辽守御孙权。黄初二年（221年），张辽屯驻雍丘，染病。张辽大病期间，孙权依旧对其非常忌惮。黄初三年（222年），张辽不负众望，抱病击破吴将吕范。同年在江都病逝，谥刚侯，享年五十四岁。\n【演】在《三国演义》中，他先为吕布部将，多番令曹军陷于苦战，其武勇连关羽亦甚称道。后来吕布战败遭擒，曹操下令绞死吕布后，刘备、关羽为张辽求情，曹操便待张辽以上宾之礼。张辽感其恩情，于是投降，自此成为曹操将领。后来，张辽随曹丕以大船征伐江东，军队被徐盛所击败。曹丕登岸逃亡时，吴将丁奉从岸边袭来，张辽为保护曹丕上前迎敌，却被丁奉以箭射其腰，回营后不治身亡，曹丕厚葬之。", advancedTroops="轻骑兵、铁骑兵", combination="温侯无双(成员:高顺(群)、吕姬(群)、张辽(群)、貂蝉(汉)、吕布(汉)、陈宫(群)、貂蝉(群)、吕布(群),加成属性:攻击)", policyName="勇者得前", policyText="可担任戍城参军，令所属部队调动速度提高10.0%" };
yield return new GeneralDefinition("s1_100085","曹仁",Homeland.Han,4,82,"八门金锁","曹仁·魏·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100085.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="八门金锁", nativeSkillText="使敌军群体陷入怯战状态，无法进行普通攻击，持续2回合", defense=88, strategy=70, speed=87, cost=3, attackGrowth=0.96, defenseGrowth=1.63, strategyGrowth=0.73, speedGrowth=1.13, siege=2, siegeGrowth=0.13, attackDistance=2, biography="【史】曹操从弟。三国曹魏名将。从曹操多年，为魏朝立下汗马功劳。破袁术，曹仁所斩获颇多，大破陶谦军及陶谦部将吕由，攻克句阳，生擒吕布的部将刘何，官渡之战中，在隐强打败刘备军、鸡落山之战又战胜袁绍军。\n【演】在《三国演义》中，曹仁于曹操起兵时与曹洪一同前来投奔，并随曹操一同参与讨董战役。后从征袁术、吕布、张绣，参加官渡之战，多立功勋。曹操平定北方后决意南征，曹仁率军先攻刘备，并列八门金锁阵以敌刘备，但阵法却被徐庶所破。赤壁之战后，周瑜乘胜进取荆州，与镇守南郡的曹仁大战，曹仁用曹操遗计诈败引周瑜入城，随命放箭，周瑜中箭败退。然此后反中东吴军士诈降之计，被周瑜击败。", advancedTroops="重骑兵、轻骑兵", combination="魏武强将(成员:夏侯渊(魏)、曹仁(魏)、夏侯惇(魏)、曹洪(魏),加成属性:攻击、速度)", policyName="贲育弗加", policyText="可担任分城参军，令该分城城墙常驻守军武将兵力提高200" };
yield return new GeneralDefinition("s1_100068","张飞",Homeland.Han,4,99,"锐矛贯体","张飞·蜀·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100068.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="锐矛贯体", nativeSkillText="对敌军群体发动一次攻击（伤害率180.0%），并有80.0%的几率使其陷入犹豫或怯战状态，无法进行普通攻击或发动主动战法，持续2回合", defense=78, strategy=35, speed=28, cost=3, attackGrowth=1.56, defenseGrowth=1.02, strategyGrowth=0.32, speedGrowth=0.33, siege=17, siegeGrowth=1.2, attackDistance=1, biography="【史】三国时期蜀汉名将。刘备长坂坡败退，张飞仅率二十骑断后，据水断桥，曹军没人敢逼近；与诸葛亮、赵云扫荡西川时，于江州义释严颜；汉中之战时又于宕渠击败张郃，对蜀汉贡献极大，官至车骑将军、领司隶校尉，封西乡侯，后被范强、张达所刺。后主时代追谥为“桓侯”。\n【演】在《三国演义》中，张飞是位重情重义嫉恶如仇，肤色黝黑的壮汉，同时又武力过人，曾多次主动挑战号称天下第一的吕布，吕布竟曾一度忌惮张飞，嗓门大更是人物一大亮点，是蜀汉大臣中少有的个性鲜明的武将。", advancedTroops="重步兵、禁卫", combination="五虎上将(成员:黄忠(蜀)、马超(蜀)、张飞(蜀)、赵云(蜀)、关羽(蜀),加成属性:攻击)、桃园结义(成员:关羽(蜀)、张飞(蜀)、刘备(蜀)、刘备(汉)、关羽(魏),加成属性:防御)", policyName="长坂风威", policyText="可担任军事设施参军，令该军事设施内己方待命部队武将体力恢复速度提高20.0%，但耐久上限降低20.0%" };
yield return new GeneralDefinition("s1_100065","关羽",Homeland.Han,4,97,"迎险御侮","关羽·蜀·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100065.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="迎险御侮", nativeSkillText="对敌军单体发动2次攻击（伤害率120.0%），并使自身与友军单体受到的下1次攻击伤害大幅降低。", defense=90, strategy=70, speed=37, cost=3, attackGrowth=1.27, defenseGrowth=1.3, strategyGrowth=0.73, speedGrowth=0.44, siege=16, siegeGrowth=1.13, attackDistance=2, biography="【史】蜀汉名将，是刘备、张飞的结义兄弟。早期跟随刘备辗转各地，曾被曹操生擒，于白马坡阵斩袁绍大将颜良，与张飞一同被称为万人敌。赤壁之战后，刘备助东吴周瑜攻打南郡曹仁，别遣关羽绝北道，阻挡曹操援军，曹仁退走后，关羽被刘备任命为襄阳太守。刘备入益州，关羽留守荆州。建安二十四年，关羽围襄樊，擒获于禁，阵斩庞德，威震华夏，曹操曾想迁都以避其锐。后曹操派徐晃前来增援，东吴吕蒙又偷袭荆州，关羽腹背受敌，兵败身亡。\n【演】与刘备、张飞桃园结义，羽居其次。使八十二斤青龙偃月刀随刘备东征西讨。汜水关关温酒斩华雄，屯土山降汉不降曹。为报恩斩颜良、诛文丑，解曹操白马之围。后得知刘备音信，过五关斩六将，千里寻兄。刘备平定益州后，封关羽为五虎大将之首，督荆州事。羽起军攻曹，放水淹七军，威震华夏。围樊城右臂中箭，幸得华佗医治，刮骨疗伤。但未曾提防东吴袭荆州，关羽父子败走麦城，突围中被捕，不屈遭害。", advancedTroops="重步兵、长枪兵", combination="五虎上将(成员:黄忠(蜀)、马超(蜀)、关羽(蜀)、张飞(蜀)、赵云(蜀),加成属性:攻击)、桃园结义(成员:关羽(蜀)、张飞(蜀)、刘备(蜀)、刘备(汉),加成属性:防御)", policyName="忠肝义胆", policyText="可担任主城参军，令主城预备兵每小时恢复数量提升60.0" };
yield return new GeneralDefinition("s1_100140","马超",Homeland.Han,4,97,"锦马慑敌","马超·蜀·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100140.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="锦马慑敌", nativeSkillText="对敌军单体发动攻击使其动摇，每回合损失一定兵力（伤害率140.0%），同时每回合有50.0%的几率陷入混乱，持续2回合", defense=92, strategy=42, speed=85, cost=3, attackGrowth=1.27, defenseGrowth=1.33, strategyGrowth=0.38, speedGrowth=1.46, siege=2, siegeGrowth=0.13, attackDistance=2, biography="【史】马腾之子，少年成名，曹操曾多次征召马超入京为官，但都被马超拒绝。建安十六年（211年），曹操治兵关中，马超联合关中诸侯韩遂等抵抗曹操，曾一度对曹操造成了极大的威胁，但被曹操用离间计击败退走，而后聚拢部队再次攻取陇上诸郡，失败后依附汉中张鲁。刘备攻打刘璋时，马超投降刘备，与刘备军合围成都，汉中之战后联名上书尊刘备为汉中王。蜀汉建立后，马超官至骠骑将军、斄乡侯。\n【演】在《三国演义》中，马超被称为“锦马超”，蜀国“五虎上将”之一。羌人将其奉为“神威天将军”。出场时十七岁，在长安连斩之前逐走吕布的董卓部将王方、李蒙。曹操害死马腾后，马超为报父仇，起兵反曹，在潼关击败大将张郃，数合枪挑李通，逼得曹操割须弃袍。而后大战虎痴许褚，被贾诩用离间计击败，败走凉州。\n不久马超卷土重来，占领冀城，虽然非常勇猛，战场上将杨阜七位兄弟阵斩，但仍被夏侯渊、杨阜等人联合击退。投奔汉中张鲁后，在葭萌关前大战张飞，被劝降归附刘备，随即引兵迫降刘璋，并活跃于汉中之战。蜀汉建立后马超镇守西平关，令伐蜀五路兵的羌兵不战自退。", advancedTroops="重骑兵、轻骑兵", combination="驰马西凉(成员:马岱(蜀)、马超(蜀)、马腾(群)、马云禄(蜀),加成属性:速度、攻心)、五虎上将(成员:黄忠(蜀)、马超(蜀)、张飞(蜀)、赵云(蜀)、关羽(蜀),加成属性:攻击)", policyName="英骑奋起", policyText="可担任主城参军，令所属部队征兵粮草消耗降低10.0%，蜀阵营武将征兵时间额外降低4.0%" };
yield return new GeneralDefinition("s1_100067","徐庶",Homeland.Han,4,80,"沙场破阵","徐庶·蜀·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100067.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="沙场破阵", nativeSkillText="普通攻击后，对攻击目标再次发动策略攻击（伤害率119.0%，受谋略属性影响），并有40.0%的几率使其陷入暴走状态，进行无差别攻击，持续1回合", defense=82, strategy=97, speed=88, cost=3, attackGrowth=1.05, defenseGrowth=1.08, strategyGrowth=1.53, speedGrowth=1.14, siege=4, siegeGrowth=0.25, attackDistance=1, biography="【史】东汉末年刘备帐下谋士，后归曹操，并仕于曹魏。徐庶本名徐福，为寒门子弟。早年为人报仇，获救后改名徐庶，求学于儒舍。后与同郡石广元避难于荆州，与司马徽、诸葛亮、崔州平等道友来往密切。刘备屯驻新野时，徐庶前往投奔，并向刘备推荐诸葛亮。徐庶南下时因母亲被曹操所掳获，徐庶不得已辞别刘备，进入曹营。魏文帝时，徐庶官至右中郎将、御史中丞。\n【演】在《三国演义》中，徐庶化名单福。刘备在新野时，投效于刘备，被拜为军师。徐庶为刘备出谋划策，击败曹将吕旷、吕翔，斗阵胜曹仁，并计取樊城。不久曹操手下谋士程昱识破了徐庶的身份，称徐庶之才十倍于己。曹操欲拉拢徐庶，于是程昱取来徐庶老母，用伪书赚徐庶来降。徐庶临走前向刘备“走马荐诸葛”，并立誓在曹营“终身不设一谋”。后徐庶跟随曹操参加赤壁之战，在庞统建议下，主动请命去散关防守马腾、韩遂，逃过赤壁大火。", advancedTroops="长枪兵、轻骑兵", combination="蜀之智(成员:庞统(蜀)、徐庶(蜀)、诸葛亮(蜀)、法正(蜀),加成属性:谋略)", policyName="举贤荐能", policyText="完成武将寻访事件时，额外获得木材粮食和铁矿各5000" };
yield return new GeneralDefinition("s1_100157","甘宁",Homeland.Han,4,96,"轻侠妄为","甘宁·吴·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100157.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="轻侠妄为", nativeSkillText="战斗开始后前3回合，使自身进入洞察状态，免疫混乱、犹豫、怯战、暴走和挑衅效果，攻击所造成的伤害提高40.0%", defense=75, strategy=71, speed=47, cost=3, attackGrowth=1.26, defenseGrowth=0.98, strategyGrowth=0.74, speedGrowth=0.62, siege=11, siegeGrowth=0.78, attackDistance=3, biography="【史】吴国猛将。性格粗暴，年轻时经常为非作歹，行为举止旁若无人。后来熟读诸子而被感化，投靠刘表和黄祖，但均未被重用。于是甘宁率部众投奔孙权，破黄祖据楚关，攻曹仁取夷陵，镇益阳拒关羽，守西陵获朱光，率骑袭曹营，战功赫赫。孙权曾说：“孟德有张辽，孤有甘兴霸，足相敌也。”他为人仗义疏财，深得士卒拥戴，被陈寿盛赞为“江表之虎臣”。\n【演】在《三国演义》中，描写的甘宁事迹与史书记载基本相同。小说中甘宁参与了夷陵之战，被蜀国蛮将沙摩柯一箭射中额头，此后逃到一棵大树下坐着死去。", advancedTroops="弩兵、重步兵", combination="苦肉计(成员:黄盖(吴)、甘宁(吴)、周瑜(吴),加成属性:攻击、防御)、纵横江海(成员:甘宁(吴)、徐盛(吴)、周泰(吴),加成属性:速度、防御)", policyName="斗将粗豪", policyText="可担任军事设施参军，令所属己方部队中吴阵营武将所在部队深夜期间行军速度提高80.0，但无法恢复体力" };
yield return new GeneralDefinition("s1_100439","黄盖",Homeland.Han,4,84,"苦肉计","黄盖·吴·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100439.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="苦肉计", nativeSkillText="以一定兵力为代价，普通攻击后使目标陷入混乱状态，持续1回合", defense=87, strategy=68, speed=29, cost=3, attackGrowth=0.99, defenseGrowth=1.49, strategyGrowth=0.71, speedGrowth=0.31, siege=17, siegeGrowth=1.2, attackDistance=2, biography="【史】孙吴名将。历仕孙坚、孙策、孙权三任君主。为人严肃，善于训练士卒，每每征讨，他的部队皆勇猛善战。赤壁之战时，黄盖前往曹营诈降，并趁机以火攻大破曹操的军队，是赤壁之战主要功臣之一。\n【演】在《三国演义》中，黄盖以铁鞭为兵器。曹操军来犯之际，黄盖向周瑜提议火攻破敌，周瑜要他行苦肉计，黄盖一口答应。黄盖故意提出投降曹操，周瑜假意下令斩首，后改为杖打五十，打得皮开肉绽。黄盖向曹操献降书，曹操起初识破诈降，但有两细作回报黄盖遭刑的事，曹操才相信。但苦肉计并无正史记载，赤壁之战时候黄盖只是“建策火攻”而已。", advancedTroops="长弓兵 、重步兵", combination="苦肉计(成员:黄盖(吴)、甘宁(吴)、周瑜(吴),加成属性:攻击、防御)、东吴老将(成员:程普(吴)、蒋钦(吴)、黄盖(吴)、韩当(吴),加成属性:攻击、防御)、老当益壮(成员:黄忠(蜀)、黄盖(吴)、严颜(蜀),加成属性:防御、攻城)", policyName="火计献策", policyText="令势力所有地图建筑的耐久上限增加20，扬州的地图建筑耐久上限额外提高10" };
yield return new GeneralDefinition("s1_100086","周泰",Homeland.Han,4,87,"战伤无畏","周泰·吴·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100086.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="战伤无畏", nativeSkillText="使自身受到普通攻击时能进行反击（伤害率70.0%），并在受到攻击时有30.0%的几率使本次伤害降低50.0%", defense=90, strategy=61, speed=28, cost=3, attackGrowth=0.91, defenseGrowth=1.67, strategyGrowth=0.55, speedGrowth=0.33, siege=15, siegeGrowth=1.06, attackDistance=1, biography="【史】三国时期吴国武将。孙策平定江东时与同郡蒋钦一起加入孙策军，随孙策左右，后孙权爱其为人，向孙策请求让周泰跟随自己。周泰多次于战乱当中保护孙权的安危，身上受的伤多达几十处，就像在皮肤上雕画一样，吴将朱然、徐盛等因此对其拜服。后来孙权为了表彰周泰为了东吴出生入死的功绩，而赐给他青罗伞盖。官至汉中太守、奋威将军，封陵阳侯。死于黄武中年，有子周邵，亦数有战功，死于黄龙二年，周邵的弟弟周承继承了兵权和爵位。\n【演】在《三国演义》中，跟正史差不多，最初和蒋钦一同在江中劫掠为生，后归顺孙策，并助孙策攻刘繇营寨。孙策攻取吴郡之时，周泰与孙权镇守宣城，期间山贼前来攻城，周泰为保护孙权而被刺12枪，身受重伤，幸得名医华佗救治才得以保全一命。", advancedTroops="重步兵、禁卫", combination="纵横江海(成员:甘宁(吴)、徐盛(吴)、周泰(吴),加成属性:速度、防御)", policyName="奋威救主", policyText="可担任主城参军，令所属部队吴阵营武将体力恢复速度增加15.0%，疲劳状态下每900秒额外恢复1点体力" };
yield return new GeneralDefinition("s1_100089","孙策",Homeland.Han,4,95,"小霸王","孙策·吴·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="骑", sourceUrl="https://stzb.163.com/herolist/100089.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="小霸王", nativeSkillText="以一定兵力为代价，对敌军群体发动一次攻击（伤害率135.0%），并有40.0%的几率再次发动猛攻（伤害率200.0%）", defense=71, strategy=71, speed=76, cost=3, attackGrowth=1.37, defenseGrowth=0.93, strategyGrowth=0.64, speedGrowth=1, siege=2, siegeGrowth=0.13, attackDistance=2, biography="【史】三国时期孙吴的奠基者之一，孙坚长子、吴大帝孙权长兄。其人有智有勇，英姿勃发，其治军严整，军纪严明，被称为“江东小霸王”。初为继承父亲孙坚的遗业而屈事袁术，征战时屡获大胜。袁术僭越称帝后，孙策与袁术决裂，曹操下诏书给孙策，要孙策讨伐袁术。之后孙策统一江东，但在一次狩猎中为刺客所伤，不久后身亡。其弟孙权接掌孙策势力。\n【演】在《三国演义》中，孙策的事迹基本与正史相符。而在描写孙策被刺后，引入了孙策斩道士于吉而受其诅咒，伤重而亡的情节。", advancedTroops="重骑兵、轻骑兵", combination="枭雄父子(成员:孙权(吴)、孙策(吴)、孙坚(吴),加成属性:攻击)、二乔(成员:小乔(吴)、大乔(吴)、孙策(吴)、小乔＆大乔(吴)、周瑜(吴),加成属性:谋略)", policyName="隽才大志", policyText="可担任戍城参军，令所属部队吴阵营武将练兵经验增加7500" };
yield return new GeneralDefinition("s1_100123","张郃",Homeland.Han,4,89,"悍将","张郃·群·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100123.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="悍将", nativeSkillText="使自身攻击属性、防御属性、谋略属性提高45.0", defense=80, strategy=70, speed=32, cost=2.5, attackGrowth=1.23, defenseGrowth=1.11, strategyGrowth=0.67, speedGrowth=0.4, siege=18, siegeGrowth=1.18, attackDistance=3, biography="【史】征西车骑将军。先从韩馥，后投袁绍，在与公孙瓒的交战中多有功劳。官渡之战时，张郃受郭图陷害，率众投降于曹操，得以重用，随曹操平定北方，远征乌桓，平马超，斩宋建，灭张鲁，多有战功。后来，张郃随夏侯渊驻守汉中，在夏侯渊被害后暂代主帅，维持败兵。\n魏明帝时诸葛亮第一次北伐，张郃奉命救援陇右，在街亭大败蜀将马谡，导致诸葛亮撤兵；诸葛亮第四次时，张郃随司马懿前往相拒。后诸葛亮粮尽退兵，张郃追至木门，与诸葛亮军交战，被飞矢射中右膝而亡。\n【演】在《三国演义》中，张郃原为袁绍手下名将，官渡之战时，受郭图陷害，无奈投降于曹操，从此被曹操重用，跟随曹操南征北战，平马超，灭张鲁，多有战功。诸葛亮一出祁山时，张郃任司马懿先锋，跟随司马懿在街亭击败蜀将马谡，使诸葛亮撤兵。此后，在诸葛亮的多次北伐中，张郃先后随曹真、司马懿前往对抗，多有表现，连诸葛亮也叹其勇猛。诸葛亮五出祁山撤退时，于在剑阁设计埋伏，张郃前往追击，中埋伏被乱箭射死。", advancedTroops="重步兵、长枪兵", combination="河北四庭柱(成员:张郃(群)、高览(群)、文丑(群)、颜良(群)、颜良＆文丑(群),加成属性:攻击、防御)", policyName="料战识变", policyText="可担任主城参军，令所属部队步兵武将征兵粮草消耗降低12.0%" };
yield return new GeneralDefinition("s1_100053","徐荣",Homeland.Han,4,80,"坚盾阵","徐荣·群·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100053.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="坚盾阵", nativeSkillText="1回合准备，援护友军全体，为其抵挡普通攻击，并使自身受到攻击时的伤害降低50.0%，持续2回合", defense=85, strategy=66, speed=32, cost=2.5, attackGrowth=1.11, defenseGrowth=1.17, strategyGrowth=0.63, speedGrowth=0.4, siege=16, siegeGrowth=1.05, attackDistance=2, biography="【史】东汉末年将领。本为中郎将，曾向董卓推举同郡出身的公孙度出任辽东太守。于汴水之战中击败曹操的独立追击军，以及在梁东之战中击败孙坚的部队。在董卓死后，受司徒王允的命令与李傕、郭汜交战，因部将胡轸投降，寡不敌众，于新丰之战被击败，战死在乱军之中。\n【演】在《三国演义》中，徐荣是一个被夏侯惇交马数回，斩于马下的三流将领，但演义和历史往往是有出入的。历史上的徐荣，可谓是一位名动一时的猛人。他的战绩足以令人瞠目结舌。 他的记载虽然很少，却足以令他跻身三国一线大将行列。", advancedTroops="重步兵、重骑兵", combination="", policyName="战功赫赫", policyText="可担任主城参军，令所属部队步兵武将征兵铁矿消耗降低10.0%" };
yield return new GeneralDefinition("s1_100268","张绣",Homeland.Han,4,85,"北地枪王","张绣·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100268.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="北地枪王", nativeSkillText="普通攻击后，对攻击目标再次发动攻击（伤害率60.0%），并有30.0%的几率使其陷入动摇状态，每回合产生逃兵（伤害率60.0%），持续2回合", defense=78, strategy=62, speed=90, cost=2.5, attackGrowth=1.3, defenseGrowth=0.97, strategyGrowth=0.59, speedGrowth=1.24, siege=3, siegeGrowth=0.2, attackDistance=1, biography="【史】骠骑将军张济的从子。东汉末年割据宛城的军阀，汉末群雄之一。初随张济征伐，张济死后与刘表联合。后降曹操，因不满其言行而突袭曹操，复与刘表联合。官渡之战前夕，听从贾诩的建议再次投降曹操，参加官渡之战，官至破羌将军，封宣威侯。在北征乌桓（207年）途中去世（一说为曹丕逼死），谥定侯。\n【演】在《三国演义》中，张绣是骠骑将军张济的侄子。建安元年，张济因军中缺粮，自关中引兵入荆州界，与刘表交战，攻穰城，中流矢而死。建安二年，曹操南征，部队到达淯水，张绣率众投降。曹操纳了张济的遗孀邹夫人，张绣因此怀恨曹操。后来，张绣偷袭曹操，曹操战败，长子曹昂，侄子曹安民被斩，猛将典韦战死。\n张绣引兵追击，被曹操击退，于是张绣退回防守穰城，再次与刘表联盟。建安四年，张绣听从贾诩的建议，再次向曹操投降。张绣到达后，曹操牵着张绣的手，一起参加宴会，为自己的儿子曹均娶了张绣的女儿，并封张绣为扬武将军。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="割据军阀", policyText="可担任军事设施参军，令所属部队群阵营武将征兵时间降低5.0%，征兵资源消耗降低5.0%" };
yield return new GeneralDefinition("s1_100062","马腾",Homeland.Han,4,91,"铁骑突击","马腾·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100062.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="铁骑突击", nativeSkillText="1回合准备，对敌军群体发动一次攻击（伤害率130.0%），并使其陷入动摇状态，每回合产生逃兵（伤害率50.0%），持续2回合，并有50.0%的几率使其在2回合后再额外产生大量逃兵（伤害率140.0%）", defense=76, strategy=62, speed=93, cost=2.5, attackGrowth=1.13, defenseGrowth=1.05, strategyGrowth=0.59, speedGrowth=1.28, siege=4, siegeGrowth=0.27, attackDistance=3, biography="【史】东汉末年割据凉州一带的军阀，马超、马休、马铁之父。马腾身长八尺余，身体洪大，面鼻雄异，性格贤良忠厚，受众人尊敬。兴平元年（194年），马腾企图连结种邵等诛灭权臣李傕、郭汜，但为其所败，只得回到凉州。后与韩遂不和，互相攻击。\n之后，马腾听从张既的建议，入朝担任卫尉。建安十六年（211年），其子马超起兵抗拒曹操。次年，马腾与其二子皆为曹操所害，夷灭三族。\n【演】在《三国演义》中，马腾被写成对汉室十分忠诚的忠臣。董卓乱政时，马腾为西凉太守，起兵应诏，为十八路诸侯之一。董卓败亡后，其余党李傕、郭汜秉政，马腾受献帝诏，同韩遂讨伐李傕、郭汜，因缺粮为其所败，退还西凉。曹操将汉献帝迁往许都后，马腾入朝，参与刘备和董承等人欲刺专权的曹操的计划，因事情败露而逃回凉州。\n后曹操用荀攸计，假诏召马腾入京，他为了达成多年心愿，和黄奎欲讨伐曹操，但事情还是败露了，马腾和儿子马休、马铁全部被害。马腾的死讯传出后，马超和韩遂为了替他报仇，于是在西凉起兵反叛。", advancedTroops="轻骑兵、铁骑兵", combination="驰马西凉(成员:马岱(蜀)、马腾(群)、马超(群)、马超(蜀)、马云禄(蜀),加成属性:速度、攻心)", policyName="勇冠西州", policyText="可担任主城参军，令所属部队群阵营武将征兵时间降低5.0%，征兵铁矿消耗降低5.0%" };
yield return new GeneralDefinition("s1_100150","荀攸",Homeland.Han,4,23,"十二奇策","荀攸·魏·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100150.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="十二奇策", nativeSkillText="移除友军单体的有害效果，并使每回合都有50.0%的几率随机获得洞察、规避、先手状态，持续3回合，每个效果独立判定", defense=71, strategy=95, speed=28, cost=2.5, attackGrowth=0.25, defenseGrowth=0.68, strategyGrowth=1.85, speedGrowth=0.31, siege=15, siegeGrowth=1.08, attackDistance=2, biography="【史】荀彧之侄，东汉末年谋士。曹操迎天子入许都之后，荀攸成为曹操的军师。 曹操征伐吕布时荀攸劝阻了曹操退兵，并献奇计水淹下邳城，活捉吕布。官渡之战荀攸献计声东击西，斩颜良和文丑。又策奇兵，派徐晃烧袁绍粮草，同时力主曹操接纳许攸，画策乌巢，立下大功。\n平定河北期间，荀攸力排众议，主张曹操消灭袁绍诸子，被曹操上奏朝廷封为陵树亭侯。荀攸行事周密低调，计谋百出，深受曹操称赞。建安十九年（214年），荀攸在曹操伐吴途中去世。\n【演】在《三国演义》中，荀攸初仕大将军何进，后弃官还乡。曹操在兖州，攸同从叔彧共来投之，为曹操重用。曹操迎天子都许，拜为军师。荀攸随讨吕布，定河北，及官渡、赤壁之战，屡出奇谋。及魏国建立，以荀攸为尚书令。曹操进爵魏王，荀攸认为曹操叛汉，曹操大怒，荀攸忧愤成疾，旋即去世。", advancedTroops="重步兵、长枪兵", combination="魏之智(成员:贾诩(魏)、荀攸(魏)、程昱(魏)、郭嘉(魏)、荀彧(魏),加成属性:谋略)", policyName="勇过贲育", policyText="可担任军事设施参军，令该军事设施补给范围提高1格，所属部队征兵消耗资源降低2.0%" };
yield return new GeneralDefinition("s1_100148","曹彰",Homeland.Han,4,89,"黄须虎子","曹彰·魏·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100148.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="黄须虎子", nativeSkillText="使自身发动攻击时的伤害提高45.0%，并进入分兵状态，普通攻击后同时对附近的敌军造成伤害（伤害率100.0%），持续2回合", defense=75, strategy=48, speed=86, cost=2.5, attackGrowth=1.29, defenseGrowth=0.9, strategyGrowth=0.4, speedGrowth=1.25, siege=3, siegeGrowth=0.22, attackDistance=2, biography="【史】曹操之子。其胡须黄色，被曹操称为“黄须儿”。弱冠前喜搏猛虎，臂力过人、不善文章。代北乌桓无（能）臣氐等造反，曹彰引军往讨，大捷而归。后又降服辽东鲜卑大人轲比能。曹丕即位后，曹彰与诸侯就国。\n【演】在《三国演义》中，曹彰的生平与正史大体相同。在阳平为曹操助战，曹彰使一条长戟，大败刘封，斩蜀将吴兰。后来曹操逝世，世子曹丕继位；曹彰得知父亲病逝，便自长安引十万大军到洛阳；然而却被贾逵以片言折服，入宫交割军马后，便回鄢陵自守。", advancedTroops="重骑兵、轻骑兵", combination="孟德之子(成员:曹植(魏)、曹彰(魏)、曹丕(魏)、曹昂(魏),加成属性:攻击、谋略)", policyName="威震塞外", policyText="可担任军事设施参军，令所属部队骑兵武将征兵时间降低4.0%，征兵粮草消耗降低10.0%" };
yield return new GeneralDefinition("s1_100078","郭嘉",Homeland.Han,4,50,"鬼谋","郭嘉·魏·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100078.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="鬼谋", nativeSkillText="使敌军单体陷入围困状态，并使其每回合有40.0%的几率随机陷入混乱、暴走、怯战、犹豫等状态中，持续3回合，每个效果独立判定", defense=65, strategy=100, speed=85, cost=2.5, attackGrowth=0.48, defenseGrowth=0.7, strategyGrowth=1.57, speedGrowth=1.02, siege=6, siegeGrowth=0.35, attackDistance=3, biography="【史】曹操帐下著名谋士。原为袁绍部下，后转投曹操，为曹操统一中国北方立下了功勋，官至军师祭酒，封洧阳亭侯。在曹操征伐乌丸时病逝，年仅三十八岁。史书上称他“才策谋略，世之奇士”。曹操称赞他见识过人，是自己的“奇佐”。\n【演】在《三国演义》中，郭嘉生平与三国志基本相同，前期由荀彧推荐给曹操，再让程昱加以肯定与推举；是曹操麾下洞察力敏锐的谋士，深得信赖，自身也曾经推举过参谋刘晔。增加遗计定辽东的剧情，成功让公孙康诛灭二袁并降曹，使曹操不费一兵一卒兼领辽东（史书未载定辽东之策为郭嘉所出）。", advancedTroops="长弓兵 、轻骑兵", combination="魏之智(成员:贾诩(魏)、程昱(魏)、郭嘉(魏)、荀攸(魏)、荀彧(魏),加成属性:谋略)", policyName="君臣相知", policyText="可担任戍城参军，令所属部队征兵时间降低5.0%，魏阵营武将征兵资源消耗额外降低15.0%" };
yield return new GeneralDefinition("s1_100129","关平",Homeland.Han,4,88,"竭忠","关平·蜀·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="弓", sourceUrl="https://stzb.163.com/herolist/100129.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="竭忠", nativeSkillText="战斗中以自身受到的伤害提高9.0%为代价，使友军全体发动攻击的伤害提高18.0%", defense=81, strategy=64, speed=41, cost=2.5, attackGrowth=1.17, defenseGrowth=0.97, strategyGrowth=0.53, speedGrowth=0.5, siege=10, siegeGrowth=0.65, attackDistance=2, biography="【史】关羽之子，关羽率军攻打樊城时，孙权借机征讨荆州。关平与其父一同被擒，最后被斩于临沮县。此外，民间通常认为他是关羽收养的义子而非亲子。\n【演】原为冀州关家庄庄主关定之子，关羽过五关时被收为义子，从此作为关羽副将，随关羽南征北战，屡立功劳，多与刘封搭档。之后逐渐成长为一员大将，曾与庞德大战三十合，不分胜负。关羽败走麦城之际，关平跟随，一同被捕，遭孙权所害。", advancedTroops="长弓兵 、重步兵", combination="", policyName="随亲义淳", policyText="可担任戍城参军，令所属部队蜀阵营武将练兵经验增加7500" };
yield return new GeneralDefinition("s1_100156","韩当",Homeland.Han,4,82,"经久善战","韩当·吴·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100156.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="经久善战", nativeSkillText="使我军全体防御属性提高35.0，持续2回合", defense=76, strategy=73, speed=46, cost=2.5, attackGrowth=0.99, defenseGrowth=0.91, strategyGrowth=0.79, speedGrowth=0.5, siege=11, siegeGrowth=0.79, attackDistance=3, biography="【史】吴国将领。韩当因为长于弓箭、骑术并且膂力过人。历仕孙坚、孙策、孙权三代，随从其征伐四方，功勋卓著，对江东基业的逐渐稳固和吴国的建立有着重要影响。官至昭武将军、冠军太守，加都督称号，封爵石城侯。被陈寿盛赞为“江表之虎臣”。\n【演】在《三国演义》中，韩当的生平与正史相似，是东吴的开国老将，随孙坚攻打刘表时三十回合斩张虎。孙坚攻襄阳之时韩当劝其班师，孙坚不听，导致大败并且丢掉性命。后从孙策平定江东。扶佐孙权。赤壁之战，韩当为前部先锋，三江口之战，韩当大破蔡瑁，后斩焦触，与周泰合力败文聘，大战中又救黄盖。\n濡须口之战，韩当与周泰合力三十回合战平许褚。后随吕蒙奇袭荆州与蒋钦、周泰、丁奉、徐盛以伏兵之策战败关羽。夷陵之战，韩当为正将与陆逊、朱然等拒刘备。", advancedTroops="长弓兵 、弩兵", combination="东吴老将(成员:程普(吴)、蒋钦(吴)、韩当(吴)、黄盖(吴),加成属性:攻击、防御)", policyName="旋即敌寇", policyText="可担任戍城参军，令所属部队弓兵武将体力上限增加10" };
yield return new GeneralDefinition("s1_100245","董袭",Homeland.Han,4,88,"殉战","董袭·吴·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100245.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="殉战", nativeSkillText="使自身攻击属性提高25.0，防御属性提高35.0，但受到攻击时的伤害提高10.0%", defense=85, strategy=50, speed=39, cost=2.5, attackGrowth=0.95, defenseGrowth=1.13, strategyGrowth=0.48, speedGrowth=0.42, siege=16, siegeGrowth=1.03, attackDistance=1, biography="【史】孙吴部将，身高八尺，武力过人。孙策见他甚为奇伟，十分欣赏。在讨伐山阴贼，平定江东叛乱，征战黄祖的战役中屡立功绩。曹操攻濡须时，孙权派董袭率领五艘楼船到濡须口。至夜深时，暴风狂袭，五艘楼船都要倾覆，董袭死守在船上，最终溺死。被陈寿盛赞为“江表之虎臣”。\n【演】在《三国演义》中，董袭生平与正史大体相当，孙策征战江东时，董袭献上严白虎的人头来降孙策。赤壁之战，董袭受周瑜命，分兵去汉阳，合肥会战时接应太史慈，逍遥津支援孙权。濡须口之战时，董袭在船上督战，船覆董袭坚守殉职。", advancedTroops="重步兵、长枪兵", combination="", policyName="志节慷慨", policyText="可担任主城参军，令所属部队步兵武将征兵时间降低4.0%" };
yield return new GeneralDefinition("s1_100162","程普",Homeland.Han,4,82,"吴之副督","程普·吴·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="骑", sourceUrl="https://stzb.163.com/herolist/100162.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="吴之副督", nativeSkillText="战斗开始后前3回合，以降低自身攻击20.0为代价，使友军全体防御属性提高50.0", defense=89, strategy=77, speed=80, cost=2.5, attackGrowth=0.99, defenseGrowth=1.18, strategyGrowth=0.74, speedGrowth=0.86, siege=7, siegeGrowth=0.46, attackDistance=2, biography="【史】历仕孙坚、孙策、孙权三任君主。是吴国最年长的将军，人们都敬称其为“程公”。他曾跟随孙坚讨伐过黄巾、董卓，又助孙策平定江东。孙策死后，他与张昭等人共同辅佐孙权，并讨伐江东境内的山贼，功勋卓著。\n【演】在《三国演义》中，使用武器为铁脊蛇矛，为孙坚最早的部下。斩华雄手下胡轸，也是为孙坚提出计谋的将领。孙坚发现玉玺后，提议孙坚回家的计策。当孙坚和袁绍对立时，与黄盖，韩当一起和袁绍手下大将颜良、文丑对峙 。", advancedTroops="重骑兵、轻骑兵", combination="东吴老将(成员:黄盖(吴)、程普(吴)、韩当(吴)、蒋钦(吴),加成属性:攻击、防御)", policyName="江表虎臣", policyText="令势力通过贼寇作乱获得资源提高20000" };
yield return new GeneralDefinition("s1_100043","孙坚",Homeland.Han,4,90,"藏玉在怀","孙坚·汉·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100043.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="藏玉在怀", nativeSkillText="普通攻击后，对攻击目标再次发动猛攻（伤害率150.0%）", defense=82, strategy=62, speed=92, cost=2.5, attackGrowth=1.07, defenseGrowth=0.89, strategyGrowth=0.47, speedGrowth=1, siege=6, siegeGrowth=0.31, attackDistance=2, biography="【史】县吏出身，因勇敢又有谋略被官府赏识，提拔为军官。曾参与讨伐黄巾军的战役以及讨伐董卓的战役。后与刘表作战时阵亡。孙坚的儿子孙策、孙权后来创建了东吴政权。\n【演】在《三国演义》中，孙坚由于征讨黄巾有功，被封为长沙太守。在董卓乱政期间，孙坚作为诸侯联军的先锋，表现得十分活跃，但因袁术存在私心，拒不发粮，而被董卓将华雄击败。后来董卓迁都长安，孙坚进驻洛阳，意外发现传国玉玺，并藏匿返回。不料事情泄漏，与袁绍、刘表结仇。不久，孙坚在与刘表手下黄祖的交战中，中埋伏而死。", advancedTroops="重骑兵、轻骑兵", combination="潜龙在渊(成员:刘备(汉)、孙坚(汉)、曹操(汉),加成属性:攻击)", policyName="征伐建功", policyText="可担任主城、戍城参军，令所属部队练兵经验增加7500，练兵时行军速度提高15.0%" };
yield return new GeneralDefinition("s1_100042","曹操",Homeland.Han,4,85,"献刀七星","曹操·汉·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100042.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="献刀七星", nativeSkillText="对敌军单体发动一次猛攻（伤害率275.0%），并使其速度属性降低28.0，持续2回合", defense=88, strategy=85, speed=93, cost=2.5, attackGrowth=0.85, defenseGrowth=0.95, strategyGrowth=0.83, speedGrowth=0.9, siege=2, siegeGrowth=0.11, attackDistance=2, biography="【史】三国中曹魏政权的奠基人。其人文武精通，可谓非常之人，超世之杰。以汉天子的名义征讨四方，对内消灭二袁、吕布、刘表、马超、韩遂等割据势力，对外降服南匈奴、乌桓、鲜卑等，统一了中国北方，并实行一系列政策恢复经济生产和社会秩序，奠定了曹魏立国的基础。\n【演】在《三国演义》中主要将曹操塑造成一个“奸雄”形象，并且更突出“奸”的一面。", advancedTroops="重骑兵、轻骑兵", combination="潜龙在渊(成员:刘备(汉)、孙坚(汉)、曹操(汉),加成属性:攻击)、行刺太师(成员:王允(汉)、董卓(汉)、曹操(汉)、董卓(群)、貂蝉(汉),加成属性:攻击、谋略、攻击距离提高)", policyName="阡陌相属", policyText="担任主城或分城参军时，屯田时可获得的各项资源增加5000" };
yield return new GeneralDefinition("s1_100163","鲁肃",Homeland.Han,4,51,"王佐之才","鲁肃·吴·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100163.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="王佐之才", nativeSkillText="战斗开始后前4回合，使我军群体受到攻击与策略攻击时的伤害降低15.0%（受谋略属性影响）", defense=67, strategy=91, speed=48, cost=2, attackGrowth=0.45, defenseGrowth=0.75, strategyGrowth=1.33, speedGrowth=0.54, siege=11, siegeGrowth=0.66, attackDistance=2, biography="【史】东吴名臣。曾为其提出鼎足江东的战略规划，因此得到孙权的赏识。建安十三年，曹操率大军南下。孙权部下多主降，而鲁肃与周瑜力排众议，坚决主战。结果，孙、刘联军大败曹军于赤壁，从此，奠定了三国鼎立格局。\n【演】在《三国演义》中，鲁肃是以一个老实人的形象出现，孙权继位后为周瑜推荐，仕于孙权，为孙权谋划战略，深受器重。赤壁之战时，鲁肃力主抗曹，出使联合刘备，并协助诸葛亮、周瑜说服孙权。鲁肃为人忠厚老实，不忍周瑜陷害诸葛亮，多次协助诸葛亮脱险。赤壁战后，鲁肃在诸葛亮的设计下，成为保人，将荆州“借”予刘备，此后多次讨要不成，处于两难的境地。周瑜去世后，鲁肃代周瑜成为水军都督。", advancedTroops="长弓兵 、弩兵", combination="东吴大都督(成员:周瑜(吴)、陆逊(吴)、鲁肃(吴)、吕蒙(吴),加成属性:谋略、速度)、吴之智(成员:陆逊(吴)、张昭(吴)、鲁肃(吴),加成属性:谋略)、三国智将(成员:程昱(魏)、法正(蜀)、鲁肃(吴),加成属性:谋略)", policyName="高瞻远瞩", policyText="令势力城外建筑的升级时间降低10.0%" };
yield return new GeneralDefinition("s1_100095","大乔",Homeland.Han,4,57,"蝶舞红莲","大乔·吴·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100095.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="蝶舞红莲", nativeSkillText="对敌军群体发动策略攻击（伤害率119.0%，受谋略属性影响），并恢复友军全体一定兵力（恢复率109.0%，受谋略属性影响）", defense=75, strategy=82, speed=54, cost=2, attackGrowth=0.64, defenseGrowth=0.84, strategyGrowth=1.01, speedGrowth=0.6, siege=11, siegeGrowth=0.66, attackDistance=3, biography="【史】吴国乔公长女，孙策之妾、小乔之姊。大乔国色流离、资貌绝伦。建安三年，孙策攻皖，拔之。纳大乔。后人谓英雄美女，天作之合。\n【演】在《三国演义》中，大乔唯一一次登场在二十九回中，孙策去世时，留下遗言命她孝顺吴夫人。孔明智激周瑜时，暗示曹操打仗是为了二乔，并将她们放到铜雀台中，引得小乔之夫周瑜暴怒，最终同意联刘抗曹。", advancedTroops="长弓兵 、弩兵", combination="二乔(成员:小乔(吴)、孙策(吴)、大乔(吴)、小乔＆大乔(吴)、周瑜(吴),加成属性:谋略)", policyName="铜雀春深", policyText="可担任分城参军，令该分城铁矿产量增加50.0%" };
yield return new GeneralDefinition("s1_100094","小乔",Homeland.Han,4,77,"幻花乱影","小乔·吴·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100094.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="幻花乱影", nativeSkillText="1回合准备，以一定兵力为代价，使敌军群体的攻击属性、防御属性、谋略属性、速度全部降低26.0（受谋略属性影响），并使其陷入暴走状态，进行无差别攻击，持续3回合", defense=53, strategy=81, speed=61, cost=2, attackGrowth=0.86, defenseGrowth=0.59, strategyGrowth=1, speedGrowth=0.68, siege=10, siegeGrowth=0.6, attackDistance=2, biography="【史】东汉末年时期的美女，庐江皖县（今安徽潜山）人。乔公的次女，汉末名将周瑜之妾。\n【演】在《三国演义》中，她是庐江皖县乔国老次女，秀美绝伦，貌压群芳，又琴棋书画无所不通。周瑜攻取皖城，迎娶小乔为妻。周郎小乔英雄美女、郎才女貌 ，被流传为千古佳话。", advancedTroops="长弓兵 、弩兵", combination="二乔(成员:孙策(吴)、小乔(吴)、周瑜(吴)、大乔(吴)、小乔＆大乔(吴),加成属性:谋略)", policyName="移筝秋水", policyText="可担任分城参军，令该分城木材产量增加50.0%" };
yield return new GeneralDefinition("s1_100045","鲍信",Homeland.Han,4,64,"尽忠迎驾","鲍信·汉·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100045.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="尽忠迎驾", nativeSkillText="挑衅敌军单体使其攻击属性降低29.2（受谋略属性影响），持续2回合，同时自身进入规避状态，免疫接下来受到的1次伤害", defense=83, strategy=87, speed=61, cost=2, attackGrowth=0.57, defenseGrowth=1.01, strategyGrowth=0.69, speedGrowth=0.61, siege=11, siegeGrowth=0.6, attackDistance=3, biography="【史】受何进征召在外募兵，回洛阳时适逢董卓进京，鲍信劝袁绍除掉董卓，袁绍不同意。后袁绍、曹操等人起兵对抗董卓，鲍信也起兵响应。后联盟破裂，鲍信劝戒曹操静观其变。兖州爆发农民起义，刺史刘岱不听鲍信所劝冒然出战，兵败战死。鲍信把曹操迎为兖州牧。在镇压农民起义期间，鲍信为救曹操不幸战死，曹操后来追记功绩，赐封其子。\n【演】在《三国演义》中，后军校尉鲍信求见袁绍，说董卓有异心，劝袁绍除之，袁绍不同意，鲍信又找王允商量，王允也不同意，鲍信于是引本部军兵投泰山。后以济北相身份参加讨伐董卓的义军，鲍信因为怕孙坚抢头功，暗中令其弟鲍忠出战。结果鲍忠为华雄所斩。李傕等人控制朝廷后，以献帝名义命曹操与鲍信镇压青州黄巾起义，于是两人在寿张迎击黄巾军，鲍信深入重地，为敌所害。", advancedTroops="长弓兵 、弩兵", combination="", policyName="沈毅有谋", policyText="可担任戍城参军，令所属部队汉阵营武将体力上限增加15" };
yield return new GeneralDefinition("s1_100354","司马徽",Homeland.Han,4,10,"名士在野","司马徽·汉·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="步", sourceUrl="https://stzb.163.com/herolist/100354.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="名士在野", nativeSkillText="战斗中，使友军全体谋略属性提高35.0，每回合有50.0%的几率使其受到攻击的伤害下降22.0%（受谋略属性影响），持续1回合", defense=36, strategy=92, speed=29, cost=2, attackGrowth=0.06, defenseGrowth=0.25, strategyGrowth=1.02, speedGrowth=0.26, siege=16, siegeGrowth=0.67, attackDistance=2, biography="【史】东汉末年名士，精通道学、奇门、兵法、经学。有“水镜先生”之称。司马徽为人清雅，学识广博，有知人之明，并向刘备推荐了诸葛亮、庞统等人，受到世人的敬重。\n【演】刘备马跃檀溪后，偶然相遇司马徽。司马徽向刘备举荐诸葛亮和庞统，并称诸葛亮为“卧龙”，庞统为“凤雏”，刘备随后夜宿庄院。次日，司马徽自称“山野闲散之人”，谢绝了刘备请求他出山辅佐的好意。不久，赵云率军寻找到庄前，刘备便随赵云离开。其后，刘备准备拜访诸葛亮，司马徽想要探访徐庶，但徐庶已经中曹操的计策前往许昌，刘备向司马徽提起徐庶举荐诸葛亮的事情，司马徽再次力荐诸葛亮。", advancedTroops="重步兵、长枪兵", combination="", policyName="清雅知人", policyText="令势力城外建造和升级木材消耗降低25.0%" };
yield return new GeneralDefinition("s1_100044","刘备",Homeland.Han,4,75,"义勇军","刘备·汉·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="步", sourceUrl="https://stzb.163.com/herolist/100044.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="义勇军", nativeSkillText="恢复我军群体一定兵力（恢复率115.0%，受谋略属性影响），并使其防御属性提高23.0（受谋略属性影响），持续1回合", defense=81, strategy=72, speed=56, cost=2, attackGrowth=0.73, defenseGrowth=0.79, strategyGrowth=0.62, speedGrowth=0.39, siege=15, siegeGrowth=0.97, attackDistance=3, biography="【史】西汉中山靖王刘胜之后，三国时期蜀汉开国皇帝、政治家，史家又称他为先主。刘备早年颠沛流离，备尝艰辛，投靠过多个诸侯。赤壁之战时，与孙权联盟击败曹操，趁势夺取荆州。而后进取益州。于章武元年（221年）在成都称帝，国号汉，史称蜀或蜀汉。《三国志》评刘备的机权干略不及曹操，但其弘毅宽厚，知人待士，百折不挠，终成帝业。刘备也称自己做事“每与操反，事乃成尔”。\n【演】在《三国演义》中，刘备的事迹基本与正史相符。书中将其塑造成一位胸襟开阔的，十足的明主形象。并重点突出其几个性格特点：一是亲贤爱士，善待人才；二是生性善良，爱民如子；三是待人宽厚，不求全责备；四是偶有权谋，颇有心计。", advancedTroops="重步兵、长枪兵", combination="桃园结义(成员:关羽(蜀)、张飞(蜀)、刘备(汉)、关羽(魏),加成属性:防御)、潜龙在渊(成员:刘备(汉)、孙坚(汉)、曹操(汉),加成属性:攻击)", policyName="仁得众心", policyText="令势力通过贼寇作乱获得预备兵数量提高300" };
yield return new GeneralDefinition("s1_100695","刘岱",Homeland.Han,4,82,"勇追穷寇","刘岱·汉·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100695.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="勇追穷寇", nativeSkillText="普通攻击后，使攻击目标陷入动摇状态，每回合产生逃兵（伤害率75.0%），并使自身攻击属性提升20.0，持续2回合", defense=78, strategy=52, speed=89, cost=2, attackGrowth=0.83, defenseGrowth=0.77, strategyGrowth=0.54, speedGrowth=0.94, siege=2, siegeGrowth=0.09, attackDistance=2, biography="【史】汉东汉末年兖州刺史，家世显赫，素负盛名。董卓倒行逆施后各地群雄起兵，兖州刺史刘岱与张邈等屯兵酸枣，以袁绍为首打出讨董旗号。后袁绍与公孙瓒不和，谋士程昱建议刘岱帮助袁绍，后公孙瓒果然大败。初平三年青州黄巾军攻打兖州，刘岱不顾济北相鲍信劝阻，坚持出战，结果兵败被杀。\n【演】在《三国演义》中，刘岱初登场时为讨董联军第四镇诸侯。青州黄巾军大举进犯兖州，于曹操取兖州时降曹操。后刘岱引兵攻打刘备所在的徐州，被张飞生擒。返回许都后，曹操黜罢其爵禄。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="征守汉稷", policyText="部队在所属城邑补给范围内行军速度提升20.0%" };
yield return new GeneralDefinition("s1_100694","张邈",Homeland.Han,4,68,"赈穷救急","张邈·汉·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100694.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="赈穷救急", nativeSkillText="恢复友军单体一定兵力（恢复率160.0%，受谋略属性影响），并使其下1次攻击造成的伤害提高20.0%", defense=72, strategy=70, speed=88, cost=1.5, attackGrowth=0.7, defenseGrowth=0.66, strategyGrowth=0.6, speedGrowth=0.92, siege=3, siegeGrowth=0.1, attackDistance=3, biography="【史】东汉末年陈留太守。张邈年少侠义，常接济贫困，故被称为“八厨”之一。董卓废少立献后，张邈与曹操率先举兵讨董，参加汴水之战，后归附于曹操。吕布背叛袁绍后，张邈与之私交，引袁绍愤而要求曹操诛杀张邈，虽然曹操拒绝了，但是张邈仍惴惴不安。于是在兴平元年（194年），曹操讨伐陶谦时，张邈联合陈宫等人发动叛乱，兵败，投奔徐州牧刘备。兴平二年（195年）张邈在向袁术借兵途中被部下所杀。\n【演】在《三国演义》中，张邈的形象与正史基本相符。作为陈留太守，张邈是讨伐董卓的第六镇诸侯。后经陈宫劝说背叛曹操，与曹操作战失败后，投奔袁术。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="侠名远播", policyText="每天$12$点获得义商相助陈情，在24小时内领取可获得5000铜钱" };
yield return new GeneralDefinition("s1_100038","王美人",Homeland.Han,4,60,"饮鸩之怨","王美人·汉·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100038.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="饮鸩之怨", nativeSkillText="对敌军单体发动策略攻击（伤害率177.0%，受谋略属性影响），并阻止其恢复兵力，持续2回合", defense=78, strategy=83, speed=86, cost=1.5, attackGrowth=0.67, defenseGrowth=0.7, strategyGrowth=1.01, speedGrowth=0.86, siege=3, siegeGrowth=0.15, attackDistance=2, biography="【史】灵怀皇后王荣，生汉献帝。祖父王苞为五官中郎将。王美人姿色秀丽，聪敏有才明，能书会计，以良家子的身份选入掖庭。当时灵帝的皇后何氏“性强忌，后宫莫不震慑”。王美人怀孕后，畏惧何皇后，服药欲堕胎，而胎安不动，又数次梦到负日而行。\n光和四年（公元181年），王美人生下皇子刘协，何皇后遂毒鸩王美人。永汉元年（公元189年），其子刘协为董卓立为皇帝，是为汉献帝。兴平元年（公元194年），有司乃奏追尊王美人为灵怀皇后，改葬文昭陵。 \n【演】在《三国演义》中，王美人是汉献帝的生母。帝宠幸王美人，生皇子协。何后嫉妒，毒鸩王美人。", advancedTroops="禁卫、轻骑兵", combination="献帝父子(成员:献帝(汉)、灵帝(汉)、王美人(汉),加成属性:防御)", policyName="得子遇忌", policyText="可担任分城参军，令该分城城内设施的建造和升级石料消耗降低20.0%" };
yield return new GeneralDefinition("s1_100023","曹操",Homeland.Han,5,80,"魏武之世","曹操·魏·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100023.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="魏武之世", nativeSkillText="在本场战斗中，使敌军全体攻击属性、防御属性、谋略属性、速度属性下降15.0%（受谋略属性影响），并使我军全体攻击距离+1在本场战斗中，使敌军全体攻击属性、防御属性、谋略属性、速度属性下降15.0%（受谋略属性影响），并使我军全体主动战法距离+1", defense=107, strategy=90, speed=88, cost=3.5, attackGrowth=1.28, defenseGrowth=2.95, strategyGrowth=1.59, speedGrowth=1.26, siege=6, siegeGrowth=0.4, attackDistance=2, biography="【史】三国中曹魏政权的奠基人。其人文武精通，可谓非常之人，超世之杰。以汉天子的名义征讨四方，对内消灭二袁、吕布、刘表、马超、韩遂等割据势力，对外降服南匈奴、乌桓、鲜卑等，统一了中国北方，并实行一系列政策恢复经济生产和社会秩序，奠定了曹魏立国的基础。\n【演】在《三国演义》中，曹操的事迹基本与正史相符。主要将其塑造成一个“奸雄”形象，并且更突出“奸”的一面。", advancedTroops="重骑兵、铁骑兵", combination="三足鼎立(成员:孙权(吴)、曹操(魏)、刘备(蜀),加成属性:攻击、防御、谋略、速度、攻城)", policyName="奉天征下", policyText="令势力所有军事设施中的部队每次与土地守军战斗胜利并占领土地后，可获得该土地单支守军兵力5.0%作为部队预备兵，在军事设施中或其补给范围内停留时可进行立即征兵。单支部队预备兵上限为10000。 部队撤退回城邑后预备兵清空。" };
yield return new GeneralDefinition("s1_100021","赵云",Homeland.Han,5,101,"银龙冲阵","赵云·蜀·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100021.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="银龙冲阵", nativeSkillText="随机对敌军单体发动2次攻击（伤害率150.0%），每次目标独立判断，并使首次受到攻击的敌军单体受到攻击和策略攻击时的伤害提高20.0%（受攻击属性影响），持续至战斗结束，最多可叠加3次", defense=92, strategy=78, speed=65, cost=3.5, attackGrowth=2.27, defenseGrowth=2.23, strategyGrowth=1.12, speedGrowth=1.14, siege=13, siegeGrowth=1.38, attackDistance=3, biography="【史】三国时期蜀汉名将。赵云跟随刘备将近三十年，先后参加过博望坡之战、长坂坡之战、江南平定战，独自指挥过入川之战、汉水之战、箕谷之战，都取得了非常好的战果。除了四处征战，赵云还先后以偏将军任桂阳太守，以留营司马留守公安，以翊军将军督江州。除此之外，赵云于平定益州时引霍去病故事劝谏刘备将田宅归还百姓，又于关羽张飞被害之后劝谏刘备不要伐吴，被后世赞为有大臣局量的儒将，甚至被认为是三国时期的完美人物。\n【演】在《三国演义》中，赵云一登场即和河北名将文丑大战，救了公孙瓒。曾和多名三国名将对战，冲锋陷阵罕见败绩。长坂坡救阿斗时，连续阵斩曹营名将五十余员。智取桂阳时，更是展现了他过人的机智和出众的谋略。随诸葛亮吊祭周瑜时，因赵云带剑相随，吴将无人敢动诸葛亮。汉水救黄忠时，让魏国名将张郃、徐晃心惊胆战，不敢迎敌。\n刘备去世之后，曹魏五路犯蜀，赵云把守阳平关，一将当关，万夫莫开。七十几岁时仍为蜀汉先锋，阵前力斩被作者称为“有万夫不当之勇”的西凉大将韩德一门五将。", advancedTroops="长枪兵、禁卫", combination="五虎上将(成员:黄忠(蜀)、马超(蜀)、赵云(蜀)、张飞(蜀)、关羽(蜀),加成属性:攻击)", policyName="治军严整", policyText="可担任戍城参军，对该城邑所有待命的40级以下武将进行操演，令其每5分钟共获得3000点武将经验，所获得的武将经验平均分配，每有1个蜀阵营待命武将，则总经验额外增加600点" };
yield return new GeneralDefinition("s1_100016","刘备",Homeland.Han,5,80,"皇裔流离","刘备·蜀·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100016.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="皇裔流离", nativeSkillText="本场战斗中，使我军全体受到伤害时，有50.0%的几率能恢复一定兵力（恢复率68.0%，受谋略属性影响），该效果每生效3次后，生效几率提升5.0%，可叠加", defense=81, strategy=80, speed=38, cost=3.5, attackGrowth=1.54, defenseGrowth=1.83, strategyGrowth=1.28, speedGrowth=0.92, siege=18, siegeGrowth=1.73, attackDistance=3, biography="【史】西汉中山靖王刘胜之后，三国时期蜀汉开国皇帝、政治家，史家又称他为先主。刘备早年颠沛流离，备尝艰辛，投靠过多个诸侯。赤壁之战时，与孙权联盟击败曹操，趁势夺取荆州。而后进取益州。于章武元年（221年）在成都称帝，国号汉，史称蜀或蜀汉。《三国志》评刘备的机权干略不及曹操，但其弘毅宽厚，知人待士，百折不挠，终成帝业。刘备也称自己做事“每与操反，事乃成尔”。\n【演】在《三国演义》中，刘备的事迹基本与正史相符。书中将其塑造成一位胸襟开阔的，十足的明主形象。并重点突出其几个性格特点：一是亲贤爱士，善待人才；二是生性善良，爱民如子；三是待人宽厚，不求全责备；四是偶有权谋，颇有心计。", advancedTroops="重步兵、禁卫", combination="桃园结义(成员:关羽(魏)、张飞(蜀)、刘备(蜀)、关羽(蜀),加成属性:防御)、三足鼎立(成员:孙权(吴)、曹操(魏)、刘备(蜀),加成属性:攻击、防御、谋略、速度、攻城)", policyName="民心所向", policyText="每天$12$、$18$点获得士兵征召陈情，可为任一武将立即征召1500(+{0})预备兵，势力每屯田完成一次，后续民心所向获得的预备兵数量永久提升60，可叠加25次；对于委任蜀、汉阵营参军的城池或军事设施，其所属部队在军事设施待命时也可使用士兵征召任务" };
yield return new GeneralDefinition("s1_100101","灵帝",Homeland.Han,5,85,"帝临回光","灵帝·汉·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100101.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="帝临回光", nativeSkillText="战斗开始后第3回合起，以无法恢复兵力为代价，使自身攻击距离+1，并进入分兵状态（伤害率50.0%，受谋略属性影响），同时令敌军群体处于恐慌中，每回合损失一定兵力（伤害率69.0%，受谋略属性影响），持续直到战斗结束，恐慌效果造成的伤害无视规避", defense=91, strategy=84, speed=65, cost=3.5, attackGrowth=1.48, defenseGrowth=1.85, strategyGrowth=1.59, speedGrowth=0.94, siege=13, siegeGrowth=1.12, attackDistance=4, biography="【史】汉灵帝，刘宏。在位期间，大部分时间施行党锢及宦官政治，又设置西园，巧立名目搜刮钱财，甚至卖官鬻爵以用于自己享乐，在位晚期爆发了黄巾起义，而凉州等地也陷入持续动乱之中。\n【演】在《三国演义》中，刘宏的生平与正史基本相同。为人昏庸无能，对政治毫不关心，实权全部掌握在十常侍的手里。刘宏死后，由于其生前没有选定继承人，故而使得刘辩和刘协之间争夺皇位。", advancedTroops="弩兵、死士", combination="汉朝皇族(成员:献帝(汉)、少帝(汉)、灵帝(汉),加成属性:防御)、献帝父子(成员:献帝(汉)、灵帝(汉)、王美人(汉),加成属性:防御)、少帝父子(成员:少帝(汉)、灵帝(汉)、何太后(汉),加成属性:防御)", policyName="卖官鬻爵", policyText="令势力税收提高6000" };
yield return new GeneralDefinition("s1_100003","吕布",Homeland.Han,5,99,"金吾飞将","吕布·汉·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100003.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="金吾飞将", nativeSkillText="对处于混乱或暴走状态的敌军单体发动一次猛攻（伤害率275.0%）；对随机敌军单体发动一次猛攻（伤害率275.0%），并使其陷入混乱状态，持续2回合", defense=100, strategy=30, speed=100, cost=3.5, attackGrowth=2.3, defenseGrowth=1.89, strategyGrowth=0.3, speedGrowth=2.02, siege=3, siegeGrowth=0.26, attackDistance=3, biography="【史】吕布以勇武闻名，号称“飞将”，时有“人中吕布，马中赤兔”之说。原为丁原部将，被唆使谋害丁原归附董卓，与董卓誓为父子，后又被司徒王允唆使诛灭董卓。旋即被董卓旧部李傕等击败，依附袁绍，又被袁绍猜忌，依附张杨。兴平元年（194年），吕布趁曹操攻打陶谦时与陈宫等叛乱，占据濮阳，但两年间被曹操击败转而去依附徐州刘备，又趁刘备与袁术作战时袭取了徐州，与刘备和好一阵又相互攻伐。\n期间，以辕门射戟化解刘备与纪灵的争斗。建安三年（198年），吕布先后击败刘备与夏侯惇后，曹操亲自出马征讨吕布，水淹下邳，吕布被部下叛变，城破被俘，被处死。\n【演】吕布是骁勇善战的汉末诸侯，先后跟随丁原、董卓作战，并最终谋害了丁原和董卓。成为独立势力后，吕布与曹操为敌，和刘备、袁术等诸侯时敌时友，最终不敌曹操和刘备的联军，兵败人亡。吕布虽然勇猛，但是少有计策，为人反复无常，唯利是图。在演义中，吕布是天下无双的超一流武将，曾在虎牢关大战刘备、关羽、张飞，曾一人独斗曹操军六员大将，武艺可谓公认的演义第一。", advancedTroops="轻骑兵、弓骑兵", combination="温侯无双(成员:高顺(群)、吕姬(群)、吕布(汉)、张辽(群)、貂蝉(汉)、陈宫(群)、貂蝉(群),加成属性:攻击)", policyName="飞将无前", policyText="部队行军速度中的武将速度取部队所有武将速度平均值的100.0%" };
yield return new GeneralDefinition("s1_100703","司马炎",Homeland.Han,5,69,"谋议宏图","司马炎·晋·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="步", sourceUrl="https://stzb.163.com/herolist/100703.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="谋议宏图", nativeSkillText="战斗开始后首回合，我军全体受到伤害降低30.0%（受谋略属性影响），该效果每回合开始时减少1/8；我军全体每回合开始时士气提升8.0", defense=89, strategy=88, speed=42, cost=3.5, attackGrowth=1.01, defenseGrowth=1.98, strategyGrowth=2.12, speedGrowth=0.86, siege=15, siegeGrowth=1.31, attackDistance=3, biography="【史】司马懿之孙，司马昭与王元姬的嫡长子，晋朝开国皇帝，成功统一三国，谥号武皇帝。\n最初以父勋入仕，封为北平亭侯。后担任中抚军，封新昌乡侯，又拜为抚军大将军、晋世子。后来逼迫魏元帝曹奂禅让，即位为帝，定国号为晋，史称西晋。即位之后，司马炎推行无为而治的宽容政治方略，使饱受战乱以及曹魏苛政的百姓得以休养生息，社会得以繁荣发展，史称“太康之治”。\n【演】在《三国演义》中，司马炎继承父亲司马昭的政治遗产后逼迫曹奂禅位，并发兵讨吴，一统三国，其余事迹与正史相似。", advancedTroops="重步兵、禁卫", combination="司马氏霸府(成员:司马炎(晋)、司马昭(晋)、司马师(晋)、司马懿(魏)、司马攸(晋)、司马懿(晋),加成属性:防御、谋略)", policyName="绥静四方", policyText="令势力拥有参军的军事设施补给范围提高1格，其下属己方部队在该军事设施补给范围内作战时士气提升10点" };
yield return new GeneralDefinition("s1_100618","贾诩",Homeland.Han,5,48,"谋谟帷幄","贾诩·魏·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="弓", sourceUrl="https://stzb.163.com/herolist/100618.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="谋谟帷幄", nativeSkillText="自身及友军单体每回合首次试图发动主动战法时，有60.0%几率对敌军单体发动一次策略攻击（伤害率171.0%，受谋略属性影响）；同时当我军全体各自低于初始兵力的60%时，其每回合首次试图发动主动战法时会额外对敌军单体发动一次策略攻击（伤害率76.0%，受谋略属性影响）", defense=93, strategy=101, speed=40, cost=3, attackGrowth=0.77, defenseGrowth=1.77, strategyGrowth=2.38, speedGrowth=0.7, siege=12, siegeGrowth=1.05, attackDistance=4, biography="【史】东汉末年至三国初年著名谋士、军事战略家，曹魏开国功臣。原为董卓部将，董卓死后，献计李傕、郭汜反攻长安。李傕等人失败后，辗转成为张绣的谋士。张绣曾用他的计策两次打败曹操，官渡之战前他劝张绣归降曹操。曹操与关中联军相持渭南时，贾诩献离间计瓦解马超、韩遂，使得曹操一举平定关中。\n【演】在《三国演义》中，贾诩的生平大体与正史相符。其形象突出，计无不中，甚至曾令善于用兵的曹操几度败绩。其所从属势力颇多，先随李傕，再随张绣，最后事曹操曹丕两代。加上他曾助曹丕篡汉，其形象不算十分正面。可是即使贾诩曾助李傕、曹魏这些在《三国演义》形象比较负面的势力，他的才能仍备受肯定。而且不论是李傕、张绣，还是曹操、曹丕，都将贾诩视为心腹。可见其人善于交际，亦深晓乱世自保之术。", advancedTroops="长弓兵 、弩兵", combination="魏之智(成员:贾诩(魏)、荀攸(魏)、程昱(魏)、郭嘉(魏)、荀彧(魏),加成属性:谋略)", policyName="审时度势", policyText="势力当前任一资源产量低于其他所有时，该资源额外增加5400产量，部队当前兵力低于上限50%时，征兵时间额外降低6.0%" };
yield return new GeneralDefinition("s1_100472","司马懿",Homeland.Han,5,72,"破凰","司马懿·魏·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100472.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="破凰", nativeSkillText="立即引发敌军全体由破凰带来的剩余妖术效果，同时对敌军单体发动一次策略攻击（伤害率155.0%，受谋略属性影响），并使其每受到伤害时，额外引发一次妖术伤害（伤害率130.0%，受谋略属性影响），最多生效3次，持续3回合立即引发敌军全体由破凰带来的剩余妖术效果，同时对敌军兵力最低的单体发动一次策略攻击（伤害率155.0%，受谋略属性影响），并使其每受到伤害时，额外引发一次妖术伤害（伤害率130.0%，受谋略属性影响），最多生效3次，持续3回合", defense=97, strategy=98, speed=30, cost=3, attackGrowth=0.94, defenseGrowth=1.85, strategyGrowth=2.3, speedGrowth=0.39, siege=18, siegeGrowth=1.41, attackDistance=3, biography="【史】三国时期魏国杰出的政治家、军事家、战略家，西晋王朝的奠基人。是辅佐了魏国三代的托孤辅政之重臣，后期成为掌控魏国朝政的权臣。善谋奇策，多次征伐有功，其中最显著的功绩是两次率大军成功抵御诸葛亮北伐和远征平定辽东。对屯田、水利等农耕经济发展有重要贡献。\n【演】在《三国演义》中，司马懿的生平基本与正史相符。而在小说中，则将其塑造成“奸诈”的负面形象。", advancedTroops="重步兵、禁卫", combination="司马氏霸府(成员:司马昭(晋)、司马师(晋)、司马懿(魏)、司马炎(晋)、司马攸(晋),加成属性:防御、谋略)", policyName="关陇抗蜀", policyText="令势力所有部队驻守时，战斗后可恢复40.0%伤兵，如果为平局，战斗后伤兵恢复提升至50.0%" };
yield return new GeneralDefinition("s1_100026","关羽",Homeland.Han,5,102,"千里单骑","关羽·魏·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100026.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="千里单骑", nativeSkillText="普通攻击后，对攻击目标再次发动攻击（伤害率200.0%），并借此恢复一定兵力", defense=86, strategy=62, speed=90, cost=3, attackGrowth=2.4, defenseGrowth=1.77, strategyGrowth=0.62, speedGrowth=1.31, siege=3, siegeGrowth=0.27, attackDistance=1, biography="【史】蜀汉名将，是刘备、张飞的结义兄弟。早期跟随刘备辗转各地，曾被曹操生擒，于白马坡阵斩袁绍大将颜良，与张飞一同被称为万人敌。赤壁之战后，刘备助东吴周瑜攻打南郡曹仁，别遣关羽绝北道，阻挡曹操援军，曹仁退走后，关羽被刘备任命为襄阳太守。刘备入益州，关羽留守荆州。建安二十四年，关羽围襄樊，擒获于禁，阵斩庞德，威震华夏，曹操曾想迁都以避其锐。后曹操派徐晃前来增援，东吴吕蒙又偷袭荆州，关羽腹背受敌，兵败身亡。\n【演】与刘备、张飞桃园结义，羽居其次。使八十二斤青龙偃月刀随刘备东征西讨。汜水关温酒斩华雄，屯土山降汉不降曹。为报恩斩颜良、诛文丑，解曹操白马之围。后得知刘备音信，过五关斩六将，千里寻兄。刘备平定益州后，封关羽为五虎大将之首，督荆州事。羽起军攻曹，放水淹七军，威震华夏。围樊城右臂中箭，幸得华佗医治，刮骨疗伤。但未曾提防东吴袭荆州，关羽父子败走麦城，突围中被捕，不屈遭害。", advancedTroops="重骑兵、轻骑兵", combination="桃园结义(成员:关羽(魏)、张飞(蜀)、刘备(蜀)、刘备(汉),加成属性:防御)", policyName="过关斩将", policyText="可担任主城或戍城参军，令所属部队调动速度提高30.0点" };
yield return new GeneralDefinition("s1_100022","张飞",Homeland.Han,5,103,"长坂之吼","张飞·蜀·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100022.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="长坂之吼", nativeSkillText="2回合准备，对敌军群体2-3目标发动一次无视兵种相克的猛烈攻击（伤害率450.0%）2回合准备，对敌军单体发动三次无视兵种相克的猛烈攻击（伤害率333.0%），每次攻击的目标独立选择", defense=87, strategy=45, speed=71, cost=3, attackGrowth=2.67, defenseGrowth=1.68, strategyGrowth=0.5, speedGrowth=1.13, siege=10, siegeGrowth=0.96, attackDistance=2, biography="【史】三国时期蜀汉名将。刘备长坂坡败退，张飞仅率二十骑断后，据水断桥，曹军没人敢逼近；与诸葛亮、赵云扫荡西川时，于江州义释严颜；汉中之战时又于宕渠击败张郃，对蜀汉贡献极大，官至车骑将军、领司隶校尉，封西乡侯，后被范强、张达所刺。后主时代追谥为“桓侯”。\n【演】在《三国演义》中，张飞是位重情重义嫉恶如仇，肤色黝黑的壮汉，同时又武力过人，曾多次主动挑战号称天下第一的吕布，吕布竟曾一度忌惮张飞，嗓门大更是人物一大亮点，是蜀汉大臣中少有的个性鲜明的武将。", advancedTroops="重骑兵、轻骑兵", combination="桃园结义(成员:关羽(魏)、张飞(蜀)、刘备(蜀)、关羽(蜀)、刘备(汉),加成属性:防御)、五虎上将(成员:黄忠(蜀)、马超(蜀)、张飞(蜀)、赵云(蜀)、关羽(蜀),加成属性:攻击)", policyName="横矛敌万", policyText="可担任戍城参军，令所属部队蜀阵营武将体力恢复速度提高25.0%，但蜀阵营武将所在部队行军速度降低10.0" };
yield return new GeneralDefinition("s1_100030","孙权",Homeland.Han,5,76,"九锡黄龙","孙权·吴·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100030.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="九锡黄龙", nativeSkillText="移除我军全体有害效果，并使其进入规避状态，免疫接下来受到的2次伤害", defense=88, strategy=85, speed=58, cost=3, attackGrowth=1.22, defenseGrowth=1.28, strategyGrowth=1.62, speedGrowth=1.11, siege=10, siegeGrowth=1.13, attackDistance=4, biography="【史】孙坚之子，孙策之弟。东汉建安五年，兄孙策遇刺身亡，孙权继位吴侯、讨逆将军，领会稽太守，开始统领江东。他击败了黄祖。后东吴联合刘备，于赤壁击溃了曹操军。东吴后来又和曹操军在合肥附近鏖战，并从刘备手中夺回荆州、擒关羽、大破刘备的讨伐军。曹丕称帝后孙权先向北方称臣，后自己建吴称帝，迁都建业。孙权病逝后谥号大皇帝，史称东吴大帝。\n【演】在《三国演义》中，孙权19岁就继承了其兄孙策之位，力据江东，击败了黄祖。后东吴联合刘备，在赤壁大战击溃了曹操军。东吴后来又和曹操军在合肥附近鏖战，并从刘备手中夺回荆州、擒关羽、大破刘备的讨伐军。曹丕称帝后孙权先向北方称臣，后自己建吴称帝，迁都建业。", advancedTroops="长弓兵 、死士", combination="枭雄父子(成员:孙策(吴)、孙坚(吴)、孙权(吴),加成属性:攻击)、三足鼎立(成员:孙权(吴)、曹操(魏)、刘备(蜀),加成属性:攻击、防御、谋略、速度、攻城)", policyName="鼎峙江东", policyText="每有一个吴阵营的内政武将施政，则税收增加1200" };
yield return new GeneralDefinition("s1_100589","周泰",Homeland.Han,5,90,"疮痍累身","周泰·吴·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100589.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="疮痍累身", nativeSkillText="战斗开始后，使自身受到的所有伤害降低84.0%，每当受到攻击或策略攻击的伤害后，对此类型伤害的减伤效果将降低1/12，位于前锋及中军时前2回合援护友军全体；同时每次受到伤害后有50.0%几率使攻击属性、防御属性、谋略属性提高20.0，该效果可叠加，持续直到战斗结束。首次受到伤害时，该效果必定触发且额外触发1次", defense=102, strategy=61, speed=35, cost=3, attackGrowth=1.71, defenseGrowth=2.25, strategyGrowth=0.61, speedGrowth=0.51, siege=15, siegeGrowth=1.31, attackDistance=2, biography="【史】三国时期吴国武将。孙策平定江东时与同郡蒋钦一起加入孙策军，随孙策左右，后孙权爱其为人，向孙策请求让周泰跟随自己。周泰多次于战乱当中保护孙权的安危，身上受的伤多达几十处，就像在皮肤上雕画一样，吴将朱然、徐盛等因此对其拜服。后来孙权为了表彰周泰为了东吴出生入死的功绩，而赐给他青罗伞盖。官至汉中太守、奋威将军，封陵阳侯。死于黄武中年，有子周邵，亦数有战功，死于黄龙二年，周邵的弟弟周承继承了兵权和爵位。\n【演】在《三国演义》中，跟正史差不多，最初和蒋钦一同在江中劫掠为生，后归顺孙策，并助孙策攻刘繇营寨。孙策攻取吴郡之时，周泰与孙权镇守宣城，期间山贼前来攻城，周泰为保护孙权而被刺12枪，身受重伤，幸得名医华佗救治才得以保全一命。", advancedTroops="重步兵、长枪兵", combination="纵横江海(成员:周泰(吴)、甘宁(吴)、徐盛(吴),加成属性:速度、防御)", policyName="卷土重来", policyText="可担任军事设施参军，令所属己方部队武将重伤后恢复10点体力" };
yield return new GeneralDefinition("s1_100006","袁绍",Homeland.Han,5,82,"四世三公","袁绍·汉·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="步", sourceUrl="https://stzb.163.com/herolist/100006.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="四世三公", nativeSkillText="使我军全体分别对距离5以内的敌军单体发动一次攻击（伤害率150.0%），每次目标独立判定使我军全体分别对距离5以内的敌军单体发动一次攻击（伤害率150.0%），每次目标独立判定，额外使我军攻击属性最高单体，对敌军防御最低单体发动一次攻击（伤害率160.0%）", defense=88, strategy=80, speed=36, cost=3, attackGrowth=1.3, defenseGrowth=1.63, strategyGrowth=1.05, speedGrowth=0.57, siege=25, siegeGrowth=1.96, attackDistance=2, biography="【史】东汉末年军阀，汉末群雄之一。在汉末群雄割据的过程中，袁绍先占据冀州，又先后夺青、并二州，并于建安四年（199年）的易京之战中击败了割据幽州的军阀公孙瓒，统一河北，势力达到顶点。但在建安五年（200年）的官渡之战中大败于曹操。建安七年（202年），袁绍在平定冀州叛乱之后病逝。\n【演】在《三国演义》中，袁绍初为何进党羽。何进被害后，与袁术等共同诛灭宦官。董卓夺权之后，残暴不仁，涂炭生灵。袁绍奔冀州组成十七路诸侯反董卓联合。董卓迁都长安后，袁绍便引诱公孙瓒进攻冀州，并胁迫韩馥控制冀州。随后袁绍为扩大势力范围而相继占领青州、并州。\n袁绍歼灭公孙瓒，平定幽州之后，在河北建立起庞大的势力。为了与曹操一决雌雄，袁绍遣七十万兵越过黄河，却于官渡之战中被火烧乌巢，惨遭落败。最终，袁绍与曹操在仓亭决战，败归后不久病死。", advancedTroops="重步兵、禁卫", combination="", policyName="名门望族", policyText="增加2400名望上限" };
yield return new GeneralDefinition("s1_100701","司马师",Homeland.Han,5,78,"运筹决胜","司马师·晋·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="骑", sourceUrl="https://stzb.163.com/herolist/100701.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="运筹决胜", nativeSkillText="自身每次试图发动主动战法时，有30.0%几率令敌军单体陷入暴走状态，持续1回合，有50.0%几率对敌军全体处于混乱、暴走状态的目标发动一次策略攻击（伤害率220.0%，受谋略属性影响)", defense=90, strategy=94, speed=85, cost=3, attackGrowth=1.17, defenseGrowth=1.66, strategyGrowth=2.22, speedGrowth=1.42, siege=5, siegeGrowth=0.45, attackDistance=2, biography="【史】司马懿和张春华之长子，司马昭之兄，司马炎之伯父。文雅风度，雄才大略，遇事沉着冷静。\n曹芳时期，担任散骑常侍、中护军，严格选拔官员。在高平陵之变中，司马师阴养三千死士，为司马懿战胜曹爽立下大功。司马懿死后，任大将军，都督中外诸军、录尚书事，独揽军政大权，成为曹魏最大权臣。\n在朝堂行废立之事，立高贵乡公曹髦为帝。平定毌丘俭、文钦叛乱，返回途中病故。是西晋王朝的奠基人，死时年仅四十八岁，谥号忠武。后被追尊为晋景王。西晋时被追尊为晋景帝，庙号世宗。\n【演】在《三国演义》中，司马师多次随司马懿共同参与讨伐孟达、防守诸葛亮北伐、火烧上方谷等事件。其余事迹与正史相似。", advancedTroops="重骑兵、轻骑兵", combination="司马氏霸府(成员:司马昭(晋)、司马师(晋)、司马懿(魏)、司马炎(晋)、司马攸(晋)、司马懿(晋),加成属性:防御、谋略)", policyName="浮淮隐略", policyText="可担任军事设施参军，令军事设施可使用预备兵征兵，且预备兵存储上限提升5000；并令该军事设施每30秒回复1名预备兵" };
yield return new GeneralDefinition("s1_100008","张角",Homeland.Han,5,21,"黄天当立","张角·群·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100008.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="黄天当立", nativeSkillText="1回合准备，使敌军全体陷入妖术诅咒，每回合损失一定兵力（伤害率180.0%，受谋略属性影响），持续2回合；敌军受到该战法的妖术伤害时，张角恢复一定兵力（恢复率60.0%，受谋略属性影响）", defense=67, strategy=93, speed=85, cost=2.5, attackGrowth=0.29, defenseGrowth=0.92, strategyGrowth=2.15, speedGrowth=1.57, siege=3, siegeGrowth=0.25, attackDistance=2, biography="【史】东汉末农民起义领袖。汉灵帝时期在各地传播“太平道”，发展部众至几十万，遍及青、徐、幽、冀、荆、扬、兖、豫八州。184年二月，张角发动起义，打出了“苍天已死，黄天当立”的口号，矛头直指东汉政府，史称“黄巾起义”，影响遍及全国，极大地动摇了东汉政府的统治。同年十月，张角病死，不久其直接领导的黄巾军被镇压，但其后各地起义不断，最终导致东汉灭亡。\n【演】在《三国演义》中，张角原是个不第的秀才，在山中采药时遇南华老仙，得天书三卷，名为《太平要术》。张角依此书所传道术，开始散施符水，为人治病，徒众发展到数十万。张角遂起了夺取天下的野心，与兄弟张宝、张梁一起发兵起义，声势浩大，但最终被朝廷和各路豪杰镇压。张角病死，黄巾军主力随即覆灭，但仍有很多残党在各地活动。", advancedTroops="死士、轻骑兵", combination="苍天已死(成员:张梁(群)、张宝(群)、张角(群),加成属性:谋略、【黄天当立】发动率提高)", policyName="太平要术", policyText="令势力群阵营武将征兵时间降低7.5%，处于灾害范围内时额外降低7.5%" };
yield return new GeneralDefinition("s1_100025","曹丕",Homeland.Han,5,83,"魏武之泽","曹丕·魏·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="弓", sourceUrl="https://stzb.163.com/herolist/100025.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="魏武之泽", nativeSkillText="使我军群体免疫怯战，普通攻击和追击战法造成的伤害提高15.0%（受谋略属性影响），同时有100.0%几率使其每回合可以进行两次普通攻击，持续2回合", defense=78, strategy=83, speed=45, cost=2.5, attackGrowth=1.45, defenseGrowth=1.26, strategyGrowth=1.45, speedGrowth=0.79, siege=11, siegeGrowth=0.97, attackDistance=4, biography="【史】曹操与卞夫人的长子。其文武双全，八岁能提笔为文，善骑射，好击剑，博览古今经传，通晓诸子百家学说。曹操去世后，曹丕继任丞相、魏王。之后逼献帝禅让成为文帝，以魏代汉，结束了汉朝四百多年的统治。在位期间，平定边患。击退鲜卑，和匈奴、氐、羌等外夷修好，恢复汉朝在西域的设置。并执行了多个优良政策，重用贤臣，使魏国安定。但时年四十岁，病逝。\n【演】在继承权问题上处心积虑，战胜了文才更胜一筹的曹植，被立为王世子。曹操逝世后，曹丕继位成为魏王，以不参加葬礼之罪逼弟弟曹植写下七步诗，险些将其所害，又顺利夺下弟弟曹彰的兵权，坐稳魏王之位。不久，曹丕逼汉献帝让位，代汉称帝，为魏国开国皇帝。\n刘备伐吴时，曹丕看出刘备要失败，但不听谋士之言，偏要坐山观虎斗，事后又起兵伐吴，结果被徐盛火攻击败。回洛阳后，曹丕大病，临终前托付曹叡给曹真、司马懿等人，终年四十岁。", advancedTroops="长弓兵 、死士", combination="孟德之子(成员:曹彰(魏)、曹植(魏)、曹丕(魏)、曹昂(魏),加成属性:攻击、谋略)", policyName="谷帛易市", policyText="令势力交易比率提高20.0%" };
yield return new GeneralDefinition("s1_100557","张梁",Homeland.Han,5,81,"人公将军","张梁·群·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100557.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="人公将军", nativeSkillText="战斗前4回合，使我军全体的防御属性提高60.0，并使我军前锋、中军受到普通攻击时会进行反击（伤害率75.0%），在此期间，敌方武将存在妖术效果时造成的攻击伤害降低20.0%", defense=85, strategy=55, speed=32, cost=3, attackGrowth=1.77, defenseGrowth=2, strategyGrowth=0.73, speedGrowth=0.54, siege=16, siegeGrowth=1.11, attackDistance=2, biography="【史】东汉末农民起义首领。张角、张宝的弟弟。熹平年间，张角创太平道，梁与角同在河北一带传教，秘密进行组织工作。中平元年（184）黄巾起义时，号称“人公将军”，协同张角击败卢植、董卓进攻。角病死，东汉政府增调左中郎将皇甫嵩往攻，梁坚守广宗，英勇反击而获胜。后因麻痹轻敌，于广宗被皇甫嵩击败身亡。\n【演】在《三国演义》中，张梁同兄弟一起发动黄巾起义，在曲阳被皇甫嵩和曹操围攻，连败七阵身亡。", advancedTroops="重步兵、长枪兵", combination="苍天已死(成员:张角(群)、张梁(群)、张宝(群),加成属性:谋略、【黄天当立】发动率提高)", policyName="五品之责", policyText="可担任分城参军，令该分城补给范围内己方5级及以下土地产量提高10.0%，5级以上土地产量提高5.0%" };
yield return new GeneralDefinition("s1_100592","董白",Homeland.Han,5,48,"未笄难言","董白·群·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100592.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="未笄难言", nativeSkillText="使敌军群体陷入妖术诅咒，每回合损失一定兵力（伤害率108.0%，受谋略属性影响），持续2回合；同时使敌军群体进行攻击和策略攻击时的伤害降低18.0%，该效果可叠加，持续直到战斗结束使敌军全体陷入妖术诅咒，每回合损失一定兵力（伤害率108.0%，受谋略属性影响），持续2回合；同时使敌军全体进行攻击和策略攻击时的伤害降低18.0%，该效果可叠加，持续直到战斗结束", defense=83, strategy=86, speed=62, cost=2.5, attackGrowth=0.51, defenseGrowth=1.4, strategyGrowth=1.59, speedGrowth=0.76, siege=10, siegeGrowth=1.11, attackDistance=3, biography="【史】董白，东汉末年县君，陇西临洮（今甘肃省岷县）人，董卓之孙女，尚未及笄就被封渭阳君。董卓被诛，灭三族时被处死。", advancedTroops="弩兵、死士", combination="", policyName="渭阳君", policyText="可担任分城参军，令该分城的资源建筑产量增加20.0%，如果董卓位于该分城上阵，则其所在部队征兵粮草消耗额外降低10.0%" };
yield return new GeneralDefinition("s1_100562","张宝",Homeland.Han,5,69,"地公将军","张宝·群·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100562.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="地公将军", nativeSkillText="对敌军群体发动策略攻击（伤害率136.0%，受谋略属性影响），并吸取其24.0的防御、谋略属性并附加于友军群体（受谋略属性影响），若有目标存在妖术效果，则额外附加属性至自身，持续2回合", defense=78, strategy=80, speed=50, cost=2.5, attackGrowth=0.8, defenseGrowth=1.31, strategyGrowth=1.88, speedGrowth=0.75, siege=9, siegeGrowth=0.91, attackDistance=4, biography="【史】张角之弟，张梁之兄，中平元年（184）二月，同兄弟一起发动黄巾起义，号地公将军。同年十一月于下曲阳（今河北晋州）遭到左中郎将皇甫嵩、钜鹿太守郭典的围攻，兵败被斩。\n【演】在《三国演义》中，张宝同兄弟一起发动黄巾起义，于阳城与朱儁军对抗。后刘备兄弟率军前来，帮助朱儁与张宝交战，张宝使用妖术，一度获胜，但不久就被破解，张宝被刘备射伤，逃入阳城坚守。朱儁等加紧围攻，张宝的部下严政斩了张宝，献首投降。", advancedTroops="长弓兵 、弩兵", combination="苍天已死(成员:张角(群)、张宝(群)、张梁(群),加成属性:谋略、【黄天当立】发动率提高)", policyName="缮城脩池", policyText="使用民伕时，可在民伕基础上额外降低600秒建造时间" };
yield return new GeneralDefinition("s1_100435","夏侯渊",Homeland.Han,5,91,"虎步关右","夏侯渊·魏·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100435.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="虎步关右", nativeSkillText="使自身首次造成的攻击伤害提高70.0%（受速度属性影响）使自身首次造成的主动战法伤害提高70.0%（受速度属性影响），此效果最多叠加2次", defense=90, strategy=66, speed=100, cost=3, attackGrowth=2, defenseGrowth=1.85, strategyGrowth=0.76, speedGrowth=2.04, siege=10, siegeGrowth=0.69, attackDistance=3, biography="【史】东汉末年名将，擅长千里奔袭作战，官至征西将军，封博昌亭侯。初期随曹操征伐，官渡之战为曹操督运粮草，又督诸将先后平定昌豨、徐和、雷绪、商曜等叛乱。后率军驻凉州，逐马超、破韩遂、灭宋建、横扫羌、氐，虎步关右。张鲁降曹操后夏侯渊留守汉中，与刘备相拒逾年，于定军山被刘备部将黄忠所袭，战死，谥曰愍侯。\n【演】在《三国演义》中，夏侯渊是夏侯婴之后、大将军惇族弟。自曹操陈留起兵起，便跟随征伐，历任陈留、颍川太守。官渡之战后，夏侯渊负责粮草补给，保证了曹操平定北方。而后夏侯渊又率兵四处征讨叛乱，破昌豨、徐和、雷绪、商曜等，战功卓著。而后夏侯渊督张郃、徐晃等留守汉中，与前来取汉中的刘备大军交战，为刘备将黄忠所袭，不幸战死。谥曰愍侯。魏齐王正始四年从祀曹操庙庭。", advancedTroops="轻骑兵、弓骑兵", combination="魏武强将(成员:夏侯渊(魏)、曹洪(魏)、夏侯惇(魏)、曹仁(魏),加成属性:攻击、速度)", policyName="一马当先", policyText="可担任戍城参军，令所属部队骑兵武将行军速度提高40.0" };
yield return new GeneralDefinition("s1_100634","吕姬",Homeland.Han,5,85,"缚父临危","吕姬·群·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100634.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="缚父临危", nativeSkillText="对敌军群体发动一次攻击（伤害率210.0%），并使自身及友军攻击属性最高的单体下两次攻击造成的伤害提升30.0%。同时使友军中吕布下一次造成的伤害无视规避", defense=74, strategy=51, speed=35, cost=3, attackGrowth=1.86, defenseGrowth=1.49, strategyGrowth=0.59, speedGrowth=0.53, siege=12, siegeGrowth=1.21, attackDistance=2, biography="【史】吕布与严氏之女，生卒年不详。下邳战役时吕布遭曹操围困，作为派出援军条件，吕姬与袁术之子有政治婚姻，但因出嫁途中被刘备与曹操拦截因而返回。吕布死后随母亲发往许昌，后不知所终。", advancedTroops="重步兵、长枪兵", combination="温侯无双(成员:吕姬(群)、吕布(群)、高顺(群)、陈宫(群)、貂蝉(群)、张辽(群)、貂蝉(汉)、吕布(汉),加成属性:攻击)", policyName="烁玉流金", policyText="令势力铁矿产量提高4800，吕布所在部队行军速度提高10.0点" };
yield return new GeneralDefinition("s1_100004","蔡文姬",Homeland.Han,5,61,"胡笳离愁","蔡文姬·汉·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100004.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="胡笳离愁", nativeSkillText="恢复我军群体较多兵力（恢复率157.0%，受谋略属性影响），并使其进入休整状态，每回合再度恢复大量兵力（恢复率206.0%，受谋略属性影响），持续1回合", defense=72, strategy=90, speed=85, cost=2, attackGrowth=0.82, defenseGrowth=0.8, strategyGrowth=1.31, speedGrowth=0.95, siege=2, siegeGrowth=0.14, attackDistance=2, biography="【史】东汉末才女，博学多才且精通音律。匈奴入侵时，被匈奴掳走。十二年后，曹操统一北方，用重金将蔡文姬赎回，并将其嫁给董祀。", advancedTroops="轻骑兵、弓骑兵", combination="", policyName="作金石声", policyText="令势力铁矿产量提高4800，部队位于城邑待命时，体力恢复速度提高10.0%" };
yield return new GeneralDefinition("s1_100603","卞夫人",Homeland.Han,5,35,"俭仪蹈和","卞夫人·魏·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100603.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="俭仪蹈和", nativeSkillText="战斗开始后前3回合，使敌军攻击属性最高的武将攻击属性下降100.0，谋略属性最高武将谋略属性下降100.0，同时敌军群体每次发动主动战法或普通攻击后有50.0%几率使自身在下一回合随机陷入犹豫或怯战状态中的一种", defense=78, strategy=87, speed=88, cost=2, attackGrowth=0.44, defenseGrowth=0.97, strategyGrowth=1.41, speedGrowth=1.09, siege=4, siegeGrowth=0.3, attackDistance=2, biography="【史】魏武帝曹操的正妻（继室），魏文帝曹丕、任城威王曹彰、陈思王曹植、萧怀王曹熊的母亲。原本是倡家，即汉代专门从事音乐歌舞的乐人家庭，后来与曹操成婚，建安初年，原配丁夫人被废，卞夫人成为曹操的正妻。曹丕继位后尊其为皇太后，曹叡继位后尊其为太皇太后。卞后在太和四年去世，与魏武帝曹操合葬高陵。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="躬行节俭", policyText="令势力部队维持消耗降低50.0%" };
yield return new GeneralDefinition("s1_100032","周姬",Homeland.Han,5,27,"复誓业火","周姬·吴·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100032.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="复誓业火", nativeSkillText="使敌军群体受到策略攻击时的伤害提高16.0%（受谋略属性影响），持续2回合，并对其发动一次火攻（伤害率114.0%，受谋略属性影响），同时使其陷入燃烧状态，每回合损失一定兵力（伤害率114.0%，受谋略属性影响），持续1回合", defense=50, strategy=85, speed=37, cost=2.5, attackGrowth=0.36, defenseGrowth=0.94, strategyGrowth=1.72, speedGrowth=0.5, siege=12, siegeGrowth=0.96, attackDistance=3, biography="【史】周瑜之女，母疑为汉末美女小乔，兄长为周循和周胤。\n【演】在《三国演义》中，提及周瑜去世后留下二子一女，孙权对他们很关照。周瑜的女儿日后嫁给了太子。", advancedTroops="弩兵、死士", combination="", policyName="食租衣税", policyText="令势力税收提高4800" };
yield return new GeneralDefinition("s1_100586","庞德",Homeland.Han,5,94,"令明负榇","庞德·群·骑·5星。已有全池移除记录；仅保留历史图鉴。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100586.html", evidence="已有全池移除记录；仅保留历史图鉴", nativeSkill="令明负榇", nativeSkillText="战斗开始后前3回合，每回合使我军群体骑兵及步兵攻击造成的伤害提高6.0%，该效果可叠加3次，持续直到战斗结束，第4回合起进入分兵状态（伤害率50.0%，受速度属性影响），持续直到战斗结束", defense=86, strategy=70, speed=90, cost=3, attackGrowth=2.22, defenseGrowth=2.03, strategyGrowth=0.69, speedGrowth=1.35, siege=3, siegeGrowth=0.24, attackDistance=3, biography="【史】初为马腾部下，在平定羌民的征伐中屡立战功。建安年间，庞德跟随马超征战，每次出征常冲锋陷阵，勇冠凉州三军。后几经辗转，随张鲁归降于曹操麾下。219年，庞德协助曹仁抵御关羽。时值汉水暴溢，他率诸将与关羽殊死搏斗，箭镞尽，又短兵相接。\n而他格斗益怒，胆气愈壮，力战多时后因小舟被洪水打翻为关羽军所擒。关羽敬重他的刚毅威武，以封将劝降，但他却怒目不跪，怒斥关羽，最终殒身殉节。\n【演】在《三国演义》中，曹操进攻汉中时，庞德被曹操所擒，且因张鲁的不仁而转投曹操。此后，庞德屡立战功，濡须口之战斩东吴名将陈武，汉中之战中击败蜀汉名将魏延，救出曹操。后来曹仁被关羽包围在樊城，庞德随于禁引军赴救。其时诸将皆以庞德兄长庞柔、故主马超均在蜀，都怀疑庞德有二心；\n庞德抬棺决死，遂力斗关羽父子，又箭射关羽，深为关羽所忌惮。然而于禁惧其立功，加以掣肘。魏军战败，庞德被周仓在水中擒获，誓死不降，为关羽所害。曹操闻知此事甚为伤悲，为之流涕。", advancedTroops="轻骑兵、铁骑兵", combination="", policyName="白马将军", policyText="完成部队操演时，额外获得10000经验道具" };
yield return new GeneralDefinition("s1_100037","何太后",Homeland.Han,5,68,"母仪浮梦","何太后·汉·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100037.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="母仪浮梦", nativeSkillText="战斗开始后，使我军全体在受到首次攻击时可进入规避状态免疫伤害，并使敌军全体在前4回合进行攻击或策略攻击时，有60.0%的几率使本次攻击的伤害降低40.0%（受谋略属性影响）", defense=77, strategy=81, speed=53, cost=2.5, attackGrowth=0.82, defenseGrowth=1.4, strategyGrowth=1.37, speedGrowth=0.64, siege=10, siegeGrowth=0.72, attackDistance=3, biography="【史】何氏出身于屠户家庭，后选入掖庭，得到汉灵帝临幸，生下皇子刘辩，并受封贵人。光和三年（180年），立为皇后。中平六年（189年），汉灵帝去世，刘辩继位，尊何氏为皇太后。董卓进京，废黜刘辩，不久毒死刘辩及何氏。\n【演】在《三国演义》中，何太后生平基本与正史相符。不过并非被董卓毒死。董卓当权后，废少帝辩为弘农王，何太后还政。后董卓欲灭口，太后大骂：“董贼逼我母子，皇天不佑！汝等助恶，必当灭族！”李儒大怒，双手扯住太后，直撺下楼。", advancedTroops="长弓兵 、禁卫", combination="宦官斗外戚(成员:何进(汉)、何太后(汉)、十常侍(汉),加成属性:攻击距离提高)、少帝父子(成员:少帝(汉)、灵帝(汉)、何太后(汉),加成属性:防御)、母仪天下(成员:吴夫人(吴)、甘皇后(蜀)、何太后(汉)、丁夫人(魏)、郭皇后(魏)、卫子夫(汉)、阴丽华(汉),加成属性:谋略、速度)", policyName="衅隙之生", policyText="令主城补给范围内己方领地所有资源产量提高300" };
yield return new GeneralDefinition("s1_100005","貂蝉",Homeland.Han,5,79,"闭月","貂蝉·汉·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100005.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="闭月", nativeSkillText="1回合准备，使敌军群体陷入暴走状态，进行无差别攻击，并使其防御属性降低29.0（受谋略属性影响），持续3回合1回合准备，使敌军群体陷入暴走状态，进行无差别攻击，并使其防御属性降低29.0（受谋略属性影响），持续4回合", defense=74, strategy=88, speed=68, cost=2.5, attackGrowth=1.24, defenseGrowth=1.07, strategyGrowth=1.6, speedGrowth=1.07, siege=10, siegeGrowth=0.72, attackDistance=2, biography="【演】中国古代四大美女之一。其善歌舞，色伎俱佳，凭借自己的美貌智慧在诸侯争霸的战乱年代，辗转于各诸侯之间。她通过王允的安排成为了吕布的妾室，巧施连环计成功诱使吕布诛灭了董卓。", advancedTroops="弩兵、死士", combination="温侯无双(成员:高顺(群)、吕姬(群)、貂蝉(汉)、张辽(群)、吕布(汉)、陈宫(群)、吕布(群),加成属性:攻击)、行刺太师(成员:王允(汉)、董卓(汉)、貂蝉(汉)、曹操(汉)、董卓(群),加成属性:攻击、谋略、攻击距离提高)", policyName="连环美人", policyText="可担任要塞或大型要塞参军，令其容纳1支己方部队时，所属部队体力恢复速度提高40.0%，但容纳多支己方部队时，所属部队体力恢复速度降低20.0%" };
yield return new GeneralDefinition("s1_100013","马超",Homeland.Han,5,97,"血溅黄砂","马超·群·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100013.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="血溅黄砂", nativeSkillText="以无法发动主动战法为代价，使自身进行攻击时的伤害提高120.0%", defense=91, strategy=45, speed=92, cost=3, attackGrowth=2.78, defenseGrowth=1.84, strategyGrowth=0.52, speedGrowth=1.54, siege=4, siegeGrowth=0.41, attackDistance=3, biography="【史】马腾之子，少年成名，曹操曾多次征召马超入京为官，但都被马超拒绝。建安十六年（211年），曹操治兵关中，马超联合关中诸侯韩遂等抵抗曹操，曾一度对曹操造成了极大的威胁，但被曹操用离间计击败退走，而后聚拢部队再次攻取陇上诸郡，失败后依附汉中张鲁。刘备攻打刘璋时，马超投降刘备，与刘备军合围成都，汉中之战后联名上书尊刘备为汉中王。蜀汉建立后，马超官至骠骑将军、斄乡侯。\n【演】在《三国演义》中，马超被称为“锦马超”，羌人将其奉为“神威天将军”。出场时十七岁，在长安连破之前逐走吕布的董卓部将王方、李蒙。曹操诱诛马腾后，马超为报父仇，起兵反曹，在潼关击败大将张郃，数合枪挑李通，逼得曹操割须弃袍。而后大战虎痴许褚，被贾诩用离间计击败，败走凉州。\n不久马超卷土重来，占领冀城，虽然非常勇猛，战场上阵斩杨阜七位兄弟，但仍被夏侯渊、杨阜等人联合击退。投奔汉中张鲁后，在葭萌关前大战张飞，被劝降归附刘备，随即引兵迫降刘璋，并活跃于汉中之战。蜀汉建立后马超镇守西平关，令伐蜀五路兵的羌兵不战自退。", advancedTroops="轻骑兵、西凉铁骑", combination="驰马西凉(成员:马岱(蜀)、马腾(群)、马超(群)、马云禄(蜀),加成属性:速度、攻心)", policyName="驰骋西州", policyText="令势力所有骑兵武将所在部队练兵时经验增加40000；势力所有骑兵武将战斗时获得经验提高10.0%" };
yield return new GeneralDefinition("s1_100015","甄洛",Homeland.Han,5,65,"洛水佳人","甄洛·群·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100015.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="洛水佳人", nativeSkillText="本场战斗中，使我军全体每回合都有80.0%的几率恢复一定兵力（恢复率90.0%，受谋略属性影响）", defense=75, strategy=90, speed=42, cost=2, attackGrowth=1.31, defenseGrowth=1.29, strategyGrowth=0.88, speedGrowth=0.85, siege=10, siegeGrowth=0.94, attackDistance=3, biography="【史】魏文帝曹丕的妻子，魏明帝曹叡的生母。黄初二年（221年），曹丕称帝以后甄夫人被赐死，曹叡即位后追尊甄氏为文昭皇后。\n【演】在《三国演义》中，甄氏生平与正史大体相当。初期嫁与袁绍次子袁熙，袁熙带兵出外征战，留下甄氏独身照顾婆婆，袁氏败亡后，曹操之子曹丕见其美艳动人，便纳为己有。黄初年间，魏文帝曹丕登基后，郭贵妃以巫蛊之术陷害甄氏。文帝曹丕大怒，将甄氏赐死。", advancedTroops="长弓兵 、弩兵", combination="", policyName="济寒赈贫", policyText="可担任主城或分城参军，令该城邑资源产量提高30.0%，但税收降低20.0%" };
yield return new GeneralDefinition("s1_100372","妲己",Homeland.Han,5,70,"青丘媚祸","妲己·群·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100372.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="青丘媚祸", nativeSkillText="本场战斗中，自身受到伤害后有60.0%的几率使距离4以内的随机敌军单体在下次行动时陷入暴走状态，进行无差别攻击，持续1回合，并使其下一次攻击和策略攻击的伤害下降24.0%（受谋略属性影响）", defense=76, strategy=87, speed=56, cost=3, attackGrowth=1.41, defenseGrowth=1.53, strategyGrowth=1.76, speedGrowth=0.75, siege=15, siegeGrowth=1.35, attackDistance=2, biography="中国古代四大妖姬之一。殷朝末期祸乱纣王的妖姬，是难得一见的绝世美女。纣王沉迷于妲己的美色，荒理朝政，对她言听计从，到了“妲己之所誉贵之，妲己之所憎诛之”的地步，使商朝灭亡，最后被周武王所诛。", advancedTroops="重步兵、长枪兵", combination="", policyName="惑乱是修", policyText="令势力税收提高3500，但部队维持消耗提高15.0%" };
yield return new GeneralDefinition("s1_100474","张宁",Homeland.Han,5,37,"黄天余音","张宁·群·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100474.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="黄天余音", nativeSkillText="吸取敌军单体26.0的全属性（受谋略属性影响）并附加于自身与友军单体，持续1回合", defense=72, strategy=88, speed=47, cost=3, attackGrowth=0.88, defenseGrowth=1.7, strategyGrowth=2.38, speedGrowth=0.71, siege=14, siegeGrowth=1.26, attackDistance=2, biography="张宁在《三国志》，《三国演义》均未有提及，是东汉末年大贤良师张角的女儿，虚拟人物。", advancedTroops="弩兵、重步兵", combination="", policyName="承继太平", policyText="令部队在晴天时，行军速度提高10.0，在雨天时，征兵资源消耗降低10.0%" };
yield return new GeneralDefinition("s1_100494","祝融夫人",Homeland.Han,5,88,"火兽冲锋","祝融夫人·群·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100494.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="火兽冲锋", nativeSkillText="使自身进行普通攻击时的伤害提高80.0%，每回合有50.0%的几率对敌军单体发动一次攻击（伤害率160.0%），并使自身下一次普通攻击所造成的伤害额外提高160.0%", defense=81, strategy=30, speed=73, cost=2.5, attackGrowth=1.91, defenseGrowth=1.24, strategyGrowth=0.32, speedGrowth=1.01, siege=3, siegeGrowth=0.25, attackDistance=3, biography="【演】在《三国演义》中，为火神祝融氏后裔，南蛮王孟获之妻，带来洞主之姐。武艺高强，善使飞刀，百发百中。曾与孟获一起抵抗蜀军，在两军阵前被赵云活捉，在诸葛亮七擒七纵孟获之后，随孟获归顺蜀汉。祝融夫人为虚构人物，不见于正史记载。", advancedTroops="蛮兵、轻骑兵", combination="惧内(成员:孙尚香(蜀)、祝融夫人(群)、王异(魏)、孙尚香(吴)、张春华(魏),加成属性:前锋受到攻击伤害降低 前锋受到策略攻击伤害降低)、南蛮王者(成员:花鬘(群)、祝融夫人(群)、孟优(群)、孟获(群),加成属性:攻击、防御)", policyName="同协归蜀", policyText="令势力所有部队中，象兵、蛮兵、藤甲兵武将体力恢复速度提高40.0%" };
yield return new GeneralDefinition("s1_100677","公孙瓒",Homeland.Han,5,93,"动如雷震","公孙瓒·群·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100677.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="动如雷震", nativeSkillText="使我军群体追击战法发动率提升100.0%，追击战法伤害提升40.0%（受速度属性影响），持续1回合", defense=85, strategy=46, speed=100, cost=3, attackGrowth=2.2, defenseGrowth=1.86, strategyGrowth=0.69, speedGrowth=2.02, siege=3, siegeGrowth=0.27, attackDistance=3, biography="【史】汉末群雄之一。依靠自己的才能逐步做到中郎将，以强硬的态度对抗北方少数民族，作战勇猛，威震边疆。公孙瓒好战，与主张以怀柔政策对待胡人的刘虞不和，后来公孙瓒诛灭刘虞，并挟持朝廷使者，得到了总督北方四州的授权，成为北方最强大的诸侯之一。他与袁绍多次相争，初期占据优势，但在龙凑之战后，公孙瓒锐气顿减，采取自保战略，逐渐失去了部下信任，被袁绍击败。最终困于高楼，引火自焚。\n【演】在《三国演义》中，公孙瓒犹如刘备恩人一般的存在。在黄巾起义和讨伐董卓时，公孙瓒均有举荐刘备。刘备在徐州抵御为报父仇而兴兵的曹操后，几乎没有与公孙瓒有任何联系。最终由曹操麾下的满宠告知刘备，公孙瓒已败于袁绍之手，死于易京的消息。", advancedTroops="轻骑兵、弓骑兵", combination="", policyName="白马义从", policyText="令势力所有骑兵武将战斗获得经验提高10.0%" };
yield return new GeneralDefinition("s1_100377","骊姬",Homeland.Han,5,84,"陷储立齐","骊姬·群·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100377.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="陷储立齐", nativeSkillText="战斗中，我军全体每回合首次受到伤害后会随机吸取伤害来源的攻击、防御、谋略属性中的一种70.0并附加于自身，持续2回合", defense=83, strategy=55, speed=62, cost=3.5, attackGrowth=1.86, defenseGrowth=1.68, strategyGrowth=0.7, speedGrowth=0.91, siege=7, siegeGrowth=1.09, attackDistance=3, biography="【史】春秋时代骊戎国君的女儿，有姿色，攻心计。被晋献公虏入晋国，成为晋献公的妃子。她使计离间了献公与申生、重耳、夷吾父子兄弟之间的感情，并设计害死了太子申生，制造了\"骊姬倾晋\"的事件。", advancedTroops="长弓兵 、弩兵", combination="", policyName="鸟飞鹿骤", policyText="可担任军事设施参军，令所属己方部队出征补给范围内领地速度提高20.0%，但体力恢复速度降低10.0%" };
yield return new GeneralDefinition("s1_100376","褒姒",Homeland.Han,5,62,"烽火覆周","褒姒·群·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100376.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="烽火覆周", nativeSkillText="对敌军单体发动一次火攻（伤害率95.0%，受谋略属性影响），烽火覆周每次发动火攻后有60.0%概率再次发动火攻，此概率每次降低20%，每次目标独立判定，战法结束后此概率重置", defense=58, strategy=76, speed=80, cost=2.5, attackGrowth=1.25, defenseGrowth=1.07, strategyGrowth=1.53, speedGrowth=1.1, siege=6, siegeGrowth=0.78, attackDistance=2, biography="【史】中国古代四大妖姬之一，周幽王攻打褒国，褒国兵败，献出褒姒乞降。周幽王爱之如掌上明珠，之后更是废黜申后，而立褒姒为王后；褒姒冷艳少笑，周幽王为博其一笑，烽火戏诸侯。最终西周灭亡，褒姒亦遭劫掳，从此下落不明。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="举烽致兵", policyText="可担任军事设施参军，令己方部队向该军事设施调动时速度提高15.0%，同时该军事设施视野额外增加2" };
yield return new GeneralDefinition("s1_100374","妺喜",Homeland.Han,5,60,"酩酊不休","妺喜·群·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100374.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="酩酊不休", nativeSkillText="使敌军单体受到的伤害提升30.0%（受谋略属性影响），持续2回合，同时该目标下次行动时，受到一次猛烈的策略攻击（伤害率240.0%，受谋略属性影响）", defense=65, strategy=80, speed=90, cost=2, attackGrowth=0.94, defenseGrowth=1.21, strategyGrowth=1.49, speedGrowth=1.41, siege=3, siegeGrowth=0.26, attackDistance=2, biography="【史】夏朝最后一位君主夏桀的王后。夏桀在位时，发动大军攻打有施氏，有施兵败求和，并得到妺喜。夏桀得到妺喜后，更加荒淫无度。妺喜有三个癖好：一是笑看人们在规模大到可以划船的酒池里饮酒；二是笑听撕裂绢帛的声音；三是喜欢穿戴男人的官帽。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="醉酒撕绢", policyText="令势力粮草产量提高4800，但军事设施征兵时间增加10.0%" };
yield return new GeneralDefinition("s1_100027","张辽",Homeland.Han,5,91,"其疾如风","张辽·魏·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100027.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="其疾如风", nativeSkillText="战斗开始后前3回合，使我军全体速度属性提高41.0（受谋略属性影响），并使其每回合有70.0%的几率可以进行两次普通攻击", defense=94, strategy=83, speed=105, cost=3.5, attackGrowth=2.21, defenseGrowth=2.27, strategyGrowth=1.05, speedGrowth=2.72, siege=3, siegeGrowth=0.29, attackDistance=3, biography="【史】汉末三国时期曹魏名将。曾从属丁原、董卓、吕布。吕布下邳败亡后，归顺曹操。此后随曹操四处征讨，战功累累。张辽为历代推崇，并成为古今六十四名将之一。曹丕登基后，仍令张辽守御孙权。黄初二年（221年），张辽屯驻雍丘，染病。张辽大病期间，孙权依旧对其非常忌惮。黄初三年（222年），张辽不负众望，抱病击破吴将吕范。同年在江都病逝，谥刚侯，享年五十四岁。\n【演】在《三国演义》中，他先为吕布部将，多番令曹军陷于苦战，其武勇连关羽亦甚称道。后来吕布战败遭擒，曹操下令绞死吕布后，刘备、关羽为张辽求情，曹操便待张辽以上宾之礼。张辽感其恩情，于是投降，自此成为曹操将领。后来，张辽随曹丕以大船征伐江东，军队被徐盛所击败。曹丕登岸逃亡时，吴将丁奉从岸边袭来，张辽为保护曹丕上前迎敌，却被丁奉以箭射其腰，回营后不治身亡，曹丕厚葬之。", advancedTroops="重骑兵、轻骑兵", combination="五子良将(成员:乐进(魏)、徐晃(魏)、张辽(魏)、于禁(魏),加成属性:攻击)", policyName="驱马并进", policyText="令势力所属部队行军速度增加20.0；且行军距离每提升10格，行军速度额外增加8.0，最多可额外增加80.0" };
yield return new GeneralDefinition("s1_100475","郝昭",Homeland.Han,5,83,"不动如山","郝昭·魏·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100475.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="不动如山", nativeSkillText="战斗中，行动时会移除所有有害效果，同时防御属性提高100.0，谋略属性提高25.0战斗中，行动时会移除所有有害效果，同时全属性提高100.0", defense=92, strategy=82, speed=31, cost=3, attackGrowth=1.58, defenseGrowth=2.29, strategyGrowth=1.19, speedGrowth=0.31, siege=15, siegeGrowth=1.17, attackDistance=2, biography="【史】曹魏初年著名将领。郝昭少年从军，屡立战功，后受曹真的推荐镇守陈仓，防御蜀汉。太和二年（228年），诸葛亮率军北伐，为郝昭所阻，劝降不成，昼夜相攻二十余日后被迫退军。\n【演】在《三国演义》中，郝昭生平与正史大体相当。身长九尺，猿臂善射，深有谋略。诸葛亮第三次北伐前探知郝昭病重，赶在张郃换防前出兵。郝昭呻吟之间忽听报蜀军到城下，急令人上城把守。但当时各门上火起，城中大乱。郝昭听知惊死，陈仓终被破。事后诸葛亮怜郝昭之死，令其妻小扶灵柩回魏国，以表其忠。", advancedTroops="重步兵、禁卫", combination="", policyName="画地守之", policyText="令势力坚守持续时间提高60分钟，坚守期间己方所有部队征兵时间降低15.0%" };
yield return new GeneralDefinition("s1_100029","张春华",Homeland.Han,5,77,"强势","张春华·魏·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="弓", sourceUrl="https://stzb.163.com/herolist/100029.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="强势", nativeSkillText="使敌军群体进行攻击时的伤害降低48.0%（受谋略属性影响），并使其陷入犹豫状态，无法发动主动战法，持续2回合", defense=56, strategy=82, speed=55, cost=2.5, attackGrowth=1.24, defenseGrowth=0.75, strategyGrowth=1.55, speedGrowth=1.04, siege=9, siegeGrowth=1.02, attackDistance=3, biography="【史】曹魏粟邑令张汪之女，晋宣帝司马懿之妻，晋景帝司马师和晋文帝司马昭的母亲。正始八年（247年），张春华去世，时年五十九岁，葬于洛阳高原陵，追赠广平县君。咸熙元年（264年），追谥为宣穆妃。泰始元年（265年），张春华之孙晋武帝司马炎登基，追谥她为宣穆皇后。", advancedTroops="长弓兵 、弩兵", combination="惧内(成员:孙尚香(吴)、张春华(魏)、王异(魏)、孙尚香(蜀)、祝融夫人(蜀)、祝融夫人(群),加成属性:前锋受到攻击伤害降低 前锋受到策略攻击伤害降低)", policyName="灶火兴旺", policyText="令势力粮草产量提高4800，部队维持消耗降低20.0%" };
yield return new GeneralDefinition("s1_100672","曹植",Homeland.Han,5,46,"七步释嫌","曹植·魏·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100672.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="七步释嫌", nativeSkillText="战斗中，我军全体每次发动普通攻击、试图发动主动战法或试图发动追击战法时，曹植使随机敌军单体下1次造成的伤害降低6.0%（受谋略属性影响），可叠加。我军全体发动普通攻击、试图发动主动战法或试图发动追击战法每累计7次时，曹植对我军群体恢复一定兵力（恢复率135.0%，受谋略属性影响）", defense=80, strategy=94, speed=76, cost=2.5, attackGrowth=0.55, defenseGrowth=1.51, strategyGrowth=2.03, speedGrowth=1.12, siege=6, siegeGrowth=0.38, attackDistance=3, biography="【史】曹操的三子。曹植很有才学，早年被曹操宠爱，几乎被立为太子，后失宠。魏文帝时，他受兄长曹丕的猜忌和迫害，屡遭贬爵和改换封地。曹植为建安文学中成就最高者，其诗以笔力雄健和词采画眉见长，留有集三十卷，已佚，今存《曹子建集》为宋人所编。\n【演】在《三国演义》中，曹操一度想立他为世子，但疑其乖巧，而不如曹丕心诚，最终听信贾诩的建议，立曹丕为嗣。曹操去世后，曹丕继位，以曹植不来奔丧为由问罪。曹丕发兵将曹植捉来，让其“七步成诗”，继而又让其立即成诗，曹植均能做到。之后，曹丕迫于太后的压力，放过曹植，对其只做贬爵处罚。", advancedTroops="轻骑兵、铁骑兵", combination="孟德之子(成员:曹彰(魏)、曹植(魏)、曹丕(魏)、曹昂(魏),加成属性:攻击、谋略)", policyName="务农殖谷", policyText="可担任分城参军，令该分城补给范围内己方土地产量提高20.0%" };
yield return new GeneralDefinition("s1_100028","王异",Homeland.Han,5,88,"世仇","王异·魏·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="弓", sourceUrl="https://stzb.163.com/herolist/100028.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="世仇", nativeSkillText="普通攻击后，对攻击目标再次发动策略攻击（伤害率233.0%，受谋略属性影响），并使其陷入围困状态，持续2回合", defense=52, strategy=90, speed=53, cost=2.5, attackGrowth=1.42, defenseGrowth=0.84, strategyGrowth=1.7, speedGrowth=0.86, siege=9, siegeGrowth=0.72, attackDistance=4, biography="【史】益州刺史赵伟璋妻，后为羌道令赵昂妻。赵英、赵月之母。马超作乱凉州时，王异协助丈夫守城，多有功勋，自马超攻冀城至祁山坚守，赵昂曾出奇计九条，王异皆有参与。\n【演】在《三国演义》中，作者不载其名，只称“王氏”。赵昂与杨阜、姜叙、尹奉等密谋起兵对抗强攻冀城的马超，赵昂因顾虑儿子赵月而回家跟妻子王氏商量，王氏听罢便怒道：“雪君父之大耻，虽丧身亦不惜，何况一子乎！君若顾子而不行，吾当先死矣！”令赵昂下定决心协助杨阜。王氏更将自己的首饰资帛，亲自往祁山军中赏劳军士，亦因此而避过马超后来的屠戮。", advancedTroops="长弓兵 、弩兵", combination="惧内(成员:孙尚香(吴)、张春华(魏)、王异(魏)、祝融夫人(群)、孙尚香(蜀)、祝融夫人(蜀),加成属性:前锋受到攻击伤害降低 前锋受到策略攻击伤害降低)", policyName="轻赋薄敛", policyText="可担任军事设施参军，令所属部队征兵消耗铜钱降低50.0%" };
yield return new GeneralDefinition("s1_100649","魏延",Homeland.Han,5,93,"奇兵拒北","魏延·蜀·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100649.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="奇兵拒北", nativeSkillText="每回合行动时有30.0%几率对敌军大营和中军分别发动一次攻击（伤害率180.0%），同时使速度最高的友军单体对敌军大营及中军分别发动一次攻击（伤害率120.0%-180.0%）。每回合奇兵拒北未生效时可提升其5%的发动率，可叠加，生效后发动率提升效果消失", defense=90, strategy=69, speed=50, cost=3, attackGrowth=1.91, defenseGrowth=1.71, strategyGrowth=1.11, speedGrowth=0.8, siege=14, siegeGrowth=1.1, attackDistance=2, biography="【史】刘备入川时魏延因数有战功被任命为牙门将军，刘备攻下汉中后又将其破格提拔为镇远将军，领汉中太守，镇守汉中，成为独当一方的大将。魏延镇守汉中近十年，之后又屡次随诸葛亮北伐，功绩显著。期间魏延多次请诸葛亮给他统领一万兵，另走一路攻关中，最后与诸葛亮会师于潼关，如同韩信的例子，但诸葛亮一直不许，因而认为自己无法完全发挥才能，心怀不满。\n与长史杨仪不和，诸葛亮死后，两人矛盾激化，相互争权，魏延败逃，为马岱所追斩，并被夷灭三族。\n【演】在《三国演义》中，刘备率军入蜀，魏延随军前往。刘备逝世后，魏延随诸葛亮平定“南蛮王”孟获的叛乱。于诸葛亮北伐时献“子午谷奇谋”之策，但未被诸葛亮采纳；因此在奉命进攻箕谷时无视诸葛亮的军令，险些败北。于诸葛亮向天祈祷延命时进帐报告敌军入侵的消息，不慎碰倒主灯，导致诸葛亮的祈祷失败。\n诸葛亮临终前遗命杨仪统兵，魏延对此不满，于诸葛亮病逝后率军反攻杨仪，而杨仪则根据诸葛亮的遗计挑衅魏延，魏延最终被马岱所斩。", advancedTroops="死士、长枪兵", combination="", policyName="以勇略任", policyText="可担任戍城参军，令所属部队与系统守军战斗时获得经验增加10.0%，部队中等级低于其他所有武将的武将额外获得2.0%经验" };
yield return new GeneralDefinition("s1_100442","黄忠",Homeland.Han,5,94,"定军扬威","黄忠·蜀·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100442.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="定军扬威", nativeSkillText="对敌军群体发动一次攻击（伤害率120.0%）并进行挑衅，同时使自身受到攻击的伤害降低25.0%（受防御属性影响）战法距离提升至4，对敌军群体发动一次攻击（伤害率120.0%）并进行挑衅，同时使自身受到攻击和策略攻击时的伤害降低25.0%（受防御属性影响）", defense=99, strategy=56, speed=42, cost=3, attackGrowth=1.79, defenseGrowth=2.32, strategyGrowth=0.56, speedGrowth=0.74, siege=20, siegeGrowth=1.74, attackDistance=1, biography="【史】本为刘表部下，后归刘备，并助刘备攻益州刘璋。在定军山一战中阵斩曹操部下名将夏侯渊。黄忠在后世多以勇猛的老将形象出现于各类文学艺术作品中。\n【演】在《三国演义》中，刘备称汉中王后将其封为五虎上将之一。初为刘表部下，后事韩玄；虽年近六旬，却有万夫不当之勇。关羽攻长沙时，关羽用拖刀计将黄忠击败，但不忍害之。次日，黄忠计诱关羽，为报关羽之恩，用弓箭只射关羽盔缨，但韩玄却因此怀疑黄忠有二心，想将黄忠斩首，但遭魏延劫场，韩玄被诛，黄忠与魏延一同降蜀。\n黄忠入蜀后，战功赫赫。先与严颜败张郃，后更于定军山亲斩夏侯渊。刘备称帝后伐吴，黄忠不顾年迈，请令担任先锋，为吴将马忠偷袭射中，回营后不治而亡。", advancedTroops="重步兵、禁卫", combination="老当益壮(成员:黄忠(蜀)、黄盖(吴)、严颜(蜀),加成属性:防御、攻城)、五虎上将(成员:黄忠(蜀)、马超(蜀)、张飞(蜀)、赵云(蜀)、关羽(蜀),加成属性:攻击)", policyName="建功平川", policyText="可担任主城或戍城参军，令所属部队征兵粮草消耗降低18.0%；如果该部队中有五虎上将称号的武将，则该部队维持粮草消耗也降低20.0%" };
yield return new GeneralDefinition("s1_100072","关银屏",Homeland.Han,5,80,"巾帼战阵","关银屏·蜀·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100072.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="巾帼战阵", nativeSkillText="使自身造成的攻击伤害提高40.0%，且对敌军群体发动主动战法攻击（伤害率120.0%），但无法进行普通攻击", defense=84, strategy=63, speed=33, cost=3, attackGrowth=1.52, defenseGrowth=1.85, strategyGrowth=0.63, speedGrowth=0.43, siege=15, siegeGrowth=1.17, attackDistance=2, biography="【史】关羽之女。史书里未载关羽女儿名字。后人编造名字为关银屏和关凤等。因在关羽的四个子女中排行第三，故又被称作“关三小姐”、“关氏三姐”或“关羽三小姐”。在传说中她是赵云的弟子、并随同诸葛亮平定南蛮，嫁给蜀国名臣李恢之子李遗，最终也在建宁俞元（今云南澄江）去世，现澄江存有夫妻二人的合墓。\n【演】关羽之女，孙权曾欲为子娶之，但被关羽以“虎女安嫁犬子”拒绝。", advancedTroops="重步兵、禁卫", combination="", policyName="宣化承流", policyText="令势力粮草产量提高4800，蜀阵营武将征兵粮草消耗降低10.0%" };
yield return new GeneralDefinition("s1_100582","法正",Homeland.Han,5,60,"难知如阴","法正·蜀·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100582.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="难知如阴", nativeSkillText="战斗中，每2回合使友军单体在1回合内主动主战法发动率提高120.0%，第3回合发动时目标调整为友军全体，如该主战法需要准备，则有60.0%的几率（受速度属性影响）跳过1回合准备时间战斗中，每2回合使友军单体在1回合内主动主战法发动率提高120.0%，第3，5，7回合发动时目标调整为友军全体，如该主战法需要准备，则60.0%的几率（受速度属性影响）跳过1回合准备时间", defense=85, strategy=99, speed=91, cost=3, attackGrowth=0.78, defenseGrowth=1.36, strategyGrowth=2.18, speedGrowth=1.46, siege=4, siegeGrowth=0.32, attackDistance=2, biography="【史】原为刘璋部下，刘备围成都时劝说刘璋投降，而后又与刘备进取汉中，献计将曹操大将夏侯渊斩首。法正善奇谋，深受刘备信任和敬重，被陈寿称赞为可比魏国的程昱和郭嘉。\n【演】在《三国演义》中，法正的生平事迹与正史大体相当。原为刘璋部属，与张松、孟达合谋献益州给刘备。在涪城大会上，与庞统一起策划谋害刘璋的计划。伐蜀成功后，曾与诸葛亮讨论治法之事。后来任蜀郡太守时公报私仇，听闻诸葛亮向他人的解释后有所收敛。曹刘争汉中时，说服刘备亲征，又受诸葛亮之命助黄忠斩夏侯渊。", advancedTroops="轻骑兵、铁骑兵", combination="蜀之智(成员:法正(蜀)、诸葛亮(蜀)、庞统(蜀)、徐庶(蜀),加成属性:谋略)、三国智将(成员:程昱(魏)、鲁肃(吴)、法正(蜀),加成属性:谋略)", policyName="奇谋鲜双", policyText="可担任军事设施参军，令所属己方部队出发3分钟后撤退可退还本次行军消耗25.0%的体力，同时武将重伤时间降低120秒" };
yield return new GeneralDefinition("s1_100358","张姬",Homeland.Han,5,94,"将门虎女","张姬·蜀·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="弓", sourceUrl="https://stzb.163.com/herolist/100358.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="将门虎女", nativeSkillText="对敌军群体发动一次进攻（伤害率200.0%），使其无法恢复兵力，持续2回合，并在1回合内，使其受到攻击伤害时有80.0%的几率引发一次动摇效果（伤害率60.0%）", defense=81, strategy=42, speed=53, cost=2.5, attackGrowth=1.77, defenseGrowth=1.42, strategyGrowth=0.39, speedGrowth=0.86, siege=7, siegeGrowth=0.45, attackDistance=3, biography="【史】张皇后，张飞次女，刘禅之妻。其姊敬哀皇后死后，于238年正月立为皇后。蜀汉灭亡后，随刘禅到洛阳。", advancedTroops="长弓兵 、死士", combination="", policyName="安乐继美", policyText="令势力木材产量提高4800，张飞所在部队征兵木材消耗降低8.0%" };
yield return new GeneralDefinition("s1_100020","黄月英",Homeland.Han,5,33,"匠心不竭","黄月英·蜀·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100020.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="匠心不竭", nativeSkillText="战斗开始后，使敌军全体从第1、3、5回合开始，逐渐陷入恐慌（伤害率34.0%，受谋略属性影响）、燃烧（伤害率41.0%，受谋略属性影响）与妖术（伤害率44.0%，受谋略属性影响）的状态，每回合开始时损失一定兵力，持续直到战斗结束，所造成的伤害无视规避", defense=70, strategy=94, speed=29, cost=2.5, attackGrowth=0.53, defenseGrowth=1.13, strategyGrowth=1.9, speedGrowth=0.47, siege=16, siegeGrowth=1.81, attackDistance=2, biography="【史】诸葛亮之妻，本名不详。其长相丑陋，黄头发，黑皮肤，但才华却与诸葛亮相当。诸葛亮发明木牛流马，相传就是从黄月英的传授的技巧上发展出来。\n【演】诸葛瞻之母，容貌甚丑，而有奇才。上通天文，下察地理，韬略近于诸书无所不晓，诸葛亮在南阳时闻其贤，迎娶黄月英。诸葛亮所学，很多是由黄月英所授。诸葛亮死后，黄月英也很快病逝，临终以“忠孝”勉励其子诸葛瞻。而正史上没有提及诸葛瞻是何人所生。", advancedTroops="重步兵、长枪兵", combination="", policyName="机关奇巧", policyText="令势力建造和升级城外建筑、主城设施的资源消耗及所需时间降低8.0%" };
yield return new GeneralDefinition("s1_100019","马云禄",Homeland.Han,5,89,"红颜铁骑","马云禄·蜀·骑·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100019.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="红颜铁骑", nativeSkillText="使自身每回合可以进行两次普通攻击，并使攻击属性提高50.0使自身每回合可以进行两次普通攻击，并使攻击属性提高50.0。发动主动战法后，造成的攻击伤害提高40.0%，持续1回合", defense=78, strategy=55, speed=88, cost=2.5, attackGrowth=1.56, defenseGrowth=1.14, strategyGrowth=0.57, speedGrowth=1.42, siege=3, siegeGrowth=0.24, attackDistance=3, biography="是民国作家周大荒小说《反三国演义》中的虚构人物。马超之妹，自幼习武，女中无双。在为马腾复仇的战事中跟随马超来到中原，与赵云一见钟情。\n之后嫁于赵云，与丈夫和兄长并肩作战。", advancedTroops="轻骑兵、铁骑兵", combination="驰马西凉(成员:马岱(蜀)、马云禄(蜀)、马超(群)、马腾(群)、马超(蜀),加成属性:速度、攻心)", policyName="巾帼无双", policyText="可担任戍城参军，令所属部队女性武将征兵时间降低10.0%" };
yield return new GeneralDefinition("s1_100035","吕蒙",Homeland.Han,5,86,"白衣渡江","吕蒙·吴·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100035.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="白衣渡江", nativeSkillText="战斗开始后前2回合，使敌军群体无法进行普通攻击，在此效果结束后，将对敌军全体发动一次强力策略攻击（伤害率215.0%，受谋略属性影响），造成的伤害无视规避", defense=92, strategy=93, speed=54, cost=3.5, attackGrowth=1.66, defenseGrowth=2.23, strategyGrowth=1.64, speedGrowth=0.87, siege=9, siegeGrowth=0.87, attackDistance=4, biography="【史】孙吴重臣。早年果敢有胆，后折节读书，识见精博，终成大将，有“士别三日，刮目相待”之语。少年时依附姊夫邓当，随孙策为将。孙权统事后，渐受重用。破黄祖作先登，封横野中郎将。围曹仁于南郡，破朱光于皖城，累功拜庐江太守。后进占荆南三郡，计擒郝普，在逍遥津之战中奋勇抵抗张辽军追袭，并于濡须数御魏军，以功除左护军、虎威将军。鲁肃去世后，代守陆口，设计袭取荆州，击败蜀汉名将关羽，使东吴国土面积大增。\n【演】在《三国演义》中，吕蒙和正史的形象大体相当。但小说中则将夺荆州的功劳归于陆逊。吕蒙听说荆州早有防备，害怕无法实现目标因此称病躲避主公。直到孙权派来的陆逊来献出白衣渡江之计。历史上这则是吕蒙和孙权的计谋。第七十七回《玉泉山关公显圣》吕蒙的死法也较为荒诞，竟被关羽魂魄索命而死。另外，小说中未有提及吕蒙年轻时奋进及其由武转文的学习经历。", advancedTroops="长弓兵 、死士", combination="东吴大都督(成员:周瑜(吴)、鲁肃(吴)、吕蒙(吴)、陆逊(吴),加成属性:谋略、速度)", policyName="谈笑封侯", policyText="令势力在荆州、扬州范围内的所有地图建筑和城邑补给范围增加1，同时扬州范围内的城邑所属部队征兵木材消耗额外降低40.0%" };
yield return new GeneralDefinition("s1_100033","孙坚",Homeland.Han,5,90,"遗志","孙坚·吴·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100033.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="遗志", nativeSkillText="战斗开始后第3回合，使我军前锋步兵或弓兵恢复极大量兵力，此后，受到普通攻击可以进行反击（伤害率85.0%），同时无法恢复兵力，持续直到战斗结束战斗开始后第3回合，使我军前锋步兵或弓兵恢复极大量兵力，此后，受到普通攻击可以进行反击（伤害率85.0%），持续直到战斗结束", defense=100, strategy=72, speed=36, cost=3.5, attackGrowth=1.89, defenseGrowth=2.09, strategyGrowth=0.8, speedGrowth=0.57, siege=20, siegeGrowth=2.11, attackDistance=3, biography="【史】县吏出身，因勇敢又有谋略被官府赏识，提拔为军官。曾参与讨伐黄巾军的战役以及讨伐董卓的战役。后与刘表作战时阵亡。孙坚的儿子孙策、孙权后来创建了东吴政权。\n【演】在《三国演义》中，孙坚由于征讨黄巾有功，被封为长沙太守。在董卓乱政期间，孙坚作为诸侯联军的先锋，表现得十分活跃，但因袁术存在私心，拒不发粮，而被董卓将华雄击败。后来董卓迁都长安，孙坚进驻洛阳，意外发现传国玉玺，并藏匿返回。不料事情泄漏，与袁绍、刘表结仇。不久，孙坚在与刘表手下黄祖的交战中，中埋伏而死。", advancedTroops="重步兵、禁卫", combination="枭雄父子(成员:孙策(吴)、孙坚(吴)、孙权(吴),加成属性:攻击)", policyName="兵威破虏", policyText="可担任主城或戍城参军，令所属部队扫荡土地守军时体力消耗提高20点，同时战斗获得经验提高100.0%" };
yield return new GeneralDefinition("s1_100654","孙鲁班",Homeland.Han,5,70,"全主诿异","孙鲁班·吴·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100654.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="全主诿异", nativeSkillText="使敌军全体被施加的燃烧、恐慌和妖术诅咒伤害提升20.0%（受谋略属性影响），持续3回合，同时对敌军群体1-2目标额外发动1次策略攻击（伤害率197.0%，受谋略属性影响）  ", defense=82, strategy=87, speed=68, cost=3, attackGrowth=1.02, defenseGrowth=1.44, strategyGrowth=1.53, speedGrowth=1.09, siege=8, siegeGrowth=0.7, attackDistance=4, biography="【史】孙权与步练师之女，曾嫁于周瑜之子，后改嫁全琮，故又称全公主。凭借孙权的宠爱，介入吴国继任者之争，为权谋斗争致死胞妹，曾与情夫孙峻凭借外戚关系把持朝政。孙峻死后，在政治斗争中失败被流放豫章，不知所终。", advancedTroops="长弓兵 、死士", combination="", policyName="同心盈赋", policyText="令势力税收增加4000，若所有施政的武将为同一阵营，税收额外增加2000" };
yield return new GeneralDefinition("s1_100034","甘宁",Homeland.Han,5,96,"侵掠如火","甘宁·吴·步·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100034.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="侵掠如火", nativeSkillText="在战斗中可以优先行动，攻击类主动战法发动率提升20.0%，进行攻击时有30.0%的几率使本次攻击伤害提高50.0%", defense=87, strategy=67, speed=46, cost=3, attackGrowth=2.11, defenseGrowth=1.92, strategyGrowth=0.78, speedGrowth=0.67, siege=14, siegeGrowth=1.35, attackDistance=2, biography="【史】吴国猛将。性格粗暴，年轻时经常为非作歹，行为举止旁若无人。后来熟读诸子而被感化，投靠刘表和黄祖，但均未被重用。于是甘宁率部众投奔孙权，破黄祖据楚关，攻曹仁取夷陵，镇益阳拒关羽，守西陵获朱光，率骑袭曹营，战功赫赫。孙权曾说：“孟德有张辽，孤有甘兴霸，足相敌也。”他为人仗义疏财，深得士卒拥戴，被陈寿盛赞为“江表之虎臣”。\n【演】在《三国演义》中，描写的甘宁事迹与史书记载基本相同。小说中甘宁参与了夷陵之战，被蜀国蛮将沙摩柯一箭射中额头，此后逃到一棵大树下坐着死去。", advancedTroops="重步兵、长枪兵", combination="苦肉计(成员:黄盖(吴)、甘宁(吴)、周瑜(吴),加成属性:攻击、防御)、纵横江海(成员:徐盛(吴)、周泰(吴)、甘宁(吴),加成属性:速度、防御)", policyName="孤胆夜袭", policyText="可担任军事设施参军，令所属己方部队深夜期间行军速度提高80.0，但无法恢复体力" };
yield return new GeneralDefinition("s1_100090","太史慈",Homeland.Han,5,98,"方阵突击","太史慈·吴·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100090.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="方阵突击", nativeSkillText="普通攻击后，对攻击目标再次发动攻击（伤害率200.0%），并使其陷入混乱状态，持续1回合", defense=89, strategy=67, speed=65, cost=2.5, attackGrowth=1.98, defenseGrowth=1.8, strategyGrowth=0.62, speedGrowth=1.05, siege=8, siegeGrowth=0.57, attackDistance=5, biography="【史】东汉末年名将，官至建昌都尉。弓马熟练，箭法精良。原为刘繇部下，后被孙策收降，自此太史慈为孙氏大将，助其扫荡江东。孙权统事后，因太史慈能制刘磐，便将管理南方的要务委托给他。建安十一年（206年）太史慈逝世。\n【演】在《三国演义》中，初登场为第十一回“刘皇叔北海救孔融，吕温侯濮阳破曹操”，后来表现与《三国志》中没有太大分别，但其死亡时间却往后调了数年。于群英会、赤壁之战中，太史慈也有登场，先在群英会上为周瑜担任监酒官，于赤壁战中则负责绕到曹军背后，断绝来自合肥的曹军援兵。\n后来太史慈更于合肥之战一役中大战魏将张辽，可惜其所献的“里应外合”之计被张辽悉破，张辽更将计就计，安排伏兵，袭击进入合肥城的太史慈，令太史慈身中数箭，回营后伤重身亡。", advancedTroops="弩兵、弓骑兵", combination="", policyName="弓马娴熟", policyText="可担任主城或戍城参军，令所属部队练兵经验增加20000，弓兵武将额外增加10000" };
yield return new GeneralDefinition("s1_100036","孙尚香",Homeland.Han,5,90,"枭姬","孙尚香·吴·弓·5星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100036.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="枭姬", nativeSkillText="1回合准备，对敌军全体发动一次攻击（伤害率160.0%），并随机对敌军群体2目标再度发动一次攻击（伤害率140.0%）", defense=77, strategy=62, speed=59, cost=2.5, attackGrowth=1.7, defenseGrowth=1.35, strategyGrowth=0.57, speedGrowth=0.79, siege=9, siegeGrowth=0.72, attackDistance=4, biography="【史】孙权之妹，名字不详。刘备定荆州时，孙权对其十分畏惮，于是进妹予刘备为夫人，重固盟好。孙夫人才捷刚猛，有诸兄之风，身边侍婢百余人，皆亲自执刀侍立，刘备每入，心内常觉凛然惊惧。后刘备入益州，使赵云领留营司马，留守荆州。\n此时孙夫人自以孙权之妹的身份，骄妄豪强，常带着一群东吴吏兵，在荆州纵横不法。既尔孙权闻知刘备西征，于是大遣舟船以迎孙夫人，而夫人带着后主刘禅回吴，幸得赵云与张飞勒兵截江，方重夺刘禅。\n【演】在《三国演义》中，名为孙尚香。孙夫人才捷刚猛，有诸兄之风，身边侍婢百余人，皆亲自执刀侍立。不料在诸葛亮的锦囊妙计安排下，假婚成真姻；后来夫人更助刘备返蜀，于路上怒斥追袭的吴将。后刘备入益州，使赵云领留营司马，留守荆州。\n此时孙权闻知刘备西征，于是遣周善引领舟船以迎孙夫人，而夫人带着后主刘禅回吴，幸得赵云与张飞勒兵截江，方重夺刘禅。彝陵之战，刘备战败，有讹言传入吴中，道刘备已死，孙夫人伤心不已，望西痛哭，投江而死。", advancedTroops="长弓兵 、死士", combination="惧内(成员:孙尚香(吴)、张春华(魏)、王异(魏)、祝融夫人(蜀)、祝融夫人(群),加成属性:前锋受到攻击伤害降低 前锋受到策略攻击伤害降低)", policyName="灵泽膏润", policyText="令势力粮草产量提高4800，部队征兵粮草消耗降低5.0%" };
yield return new GeneralDefinition("s1_100351","张任",Homeland.Han,4,87,"拔剑护主","张任·群·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100351.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="拔剑护主", nativeSkillText="使自身受到普通攻击时可以反击（伤害率80.0%），受到攻击和策略攻击的伤害降低30.0%，持续2回合", defense=89, strategy=76, speed=58, cost=3, attackGrowth=1.18, defenseGrowth=1.34, strategyGrowth=0.79, speedGrowth=0.7, siege=9, siegeGrowth=0.56, attackDistance=4, biography="【史】东汉末年益州牧刘璋的属下，官至益州从事。公元213年（建安十八年），在刘备进攻刘璋的战争中，张任率军迎战刘备，战败身死。\n【演】在《三国演义》中，张任以忠勇著称。刘备入蜀时，张任等文武官员出言劝谏刘璋提防刘备，刘璋不听。宴会之际，刘备手下谋士庞统策划让将军魏延舞剑，趁机除掉刘璋，张任见势，出面对舞，解救刘璋。刘备攻打刘璋，张任与诸将引兵对抗，并在落凤坡埋伏射死庞统。后诸葛亮从荆州前来支援刘备，用计擒获张任，张任宁死不降，遂被处斩。刘备感叹不已，令收其尸首，葬于金雁桥侧，以表其忠。", advancedTroops="长弓兵 、禁卫", combination="", policyName="志节胆勇", policyText="可担任主城参军，令所属部队弓兵武将征兵资源消耗降低5.0%" };
yield return new GeneralDefinition("s1_100051","张梁",Homeland.Han,4,81,"黄巾军威","张梁·群·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100051.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="黄巾军威", nativeSkillText="战斗开始后前3回合，使我军群体的防御属性提高29.0，每回合有60.0%的几率使其受到普通攻击时进行反击（伤害率100.0%）", defense=79, strategy=77, speed=32, cost=3, attackGrowth=1.22, defenseGrowth=1.07, strategyGrowth=0.92, speedGrowth=0.44, siege=16, siegeGrowth=1, attackDistance=2, biography="【史】东汉末农民起义首领。张角、张宝的弟弟。熹平年间，张角创太平道，梁与角同在河北一带传教，秘密进行组织工作。中平元年（184）黄巾起义时，号称“人公将军”，协同张角击败卢植、董卓进攻。角病死，东汉政府增调左中郎将皇甫嵩往攻，梁坚守广宗，英勇反击而获胜。后因麻痹轻敌，于广宗被皇甫嵩击败身亡。\n【演】在《三国演义》中，张梁同兄弟一起发动黄巾起义，在曲阳被皇甫嵩和曹操围攻，连败七阵，身亡。", advancedTroops="重步兵、长枪兵", combination="苍天已死(成员:张角(群)、张宝(群)、张梁(群),加成属性:谋略、【黄天当立】发动率提高)", policyName="夜备之疏", policyText="可担任军事设施参军，令所属己方部队白天体力恢复速度提高20.0%，夜间该军事设施受到攻城伤害提高30.0%" };
yield return new GeneralDefinition("s1_100049","华雄",Homeland.Han,4,82,"重斩","华雄·群·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100049.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="重斩", nativeSkillText="普通攻击后，对攻击目标再次发动攻击（伤害率150.0%），并使其攻击属性降低25.0，持续2回合", defense=86, strategy=41, speed=32, cost=3, attackGrowth=1.24, defenseGrowth=1.43, strategyGrowth=0.49, speedGrowth=0.44, siege=19, siegeGrowth=1.36, attackDistance=2, biography="【史】东汉末年为董卓帐下都督。袁绍等起兵讨伐董卓时，孙坚大破董卓军，华雄在此战中被孙坚一军所斩。\n【演】在《三国演义》中华雄的相关故事与史实差距较大。华雄被描述为身长九尺、虎体狼腰、豹头猿臂的猛将。在第五回中，华雄自告奋勇在汜水关抵挡十八路诸侯联军的进攻，并偷袭了孙坚的营寨，大败孙坚军，并斩了孙坚部将祖茂。后来诸侯们先后派出俞涉、潘凤两员大将与华雄交战，但二人均被华雄所斩。\n正当诸侯们手足无措之时，当时名不见经传的关羽自告奋勇出战华雄，并且在曹操为他斟的热酒尚温之时，便斩了华雄得胜归来。此段故事也被称作“温酒斩华雄”。", advancedTroops="重步兵、长枪兵", combination="", policyName="扬威轻敌", policyText="可担任主城参军，令所属部队步兵武将征兵木材消耗降低10.0%" };
yield return new GeneralDefinition("s1_100638","越吉",Homeland.Han,4,82,"羌帅衅敌","越吉·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100638.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="羌帅衅敌", nativeSkillText="使自身和敌军单体互相挑衅，并使目标陷入犹豫状态，持续2回合；2回合后，使其陷入怯战状态，持续1回合；下一回合内，自身将会陷入犹豫状态", defense=80, strategy=32, speed=79, cost=3, attackGrowth=1.24, defenseGrowth=1.21, strategyGrowth=0.34, speedGrowth=0.95, siege=2, siegeGrowth=0.15, attackDistance=3, biography="【演】《三国演义》中的虚构人物，西羌元帅，西羌王彻里吉手下大将。诸葛亮“一出祁山”伐魏时，曾起羌兵十五万并兵车直扣西平关，大败关兴，后因关公显灵而败退。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="西羌帅勇", policyText="可担任戍城参军，令所属部队骑兵武将体力上限增加5" };
yield return new GeneralDefinition("s1_100490","带来洞主",Homeland.Han,4,81,"伪刺","带来洞主·群·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100490.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="伪刺", nativeSkillText="使自身规避下一次伤害，并在进行攻击时伤害提高65.0%，持续1回合", defense=73, strategy=65, speed=35, cost=2.5, attackGrowth=1.23, defenseGrowth=1.01, strategyGrowth=0.71, speedGrowth=0.39, siege=10, siegeGrowth=0.66, attackDistance=2, biography="【演】南蛮王孟获之妻祝融夫人之弟。曾向连败的孟获相继推荐了木鹿大王和兀突骨以应对诸葛亮率领的来犯蜀军，并假投降欲接近诸葛亮趁机行刺，但均被诸葛亮识破。", advancedTroops="死士、蛮兵", combination="", policyName="假降未遂", policyText="可担任戍城参军，令所属部队群阵营武将练兵经验增加6000" };
yield return new GeneralDefinition("s1_100487","张鲁",Homeland.Han,4,65,"师君乐道","张鲁·群·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100487.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="师君乐道", nativeSkillText="使友军全体攻击属性、防御属性、谋略属性、速度属性提高22.0，持续2回合，并为其恢复一定兵力（恢复率113.0%，受谋略属性影响）", defense=75, strategy=89, speed=40, cost=2.5, attackGrowth=0.81, defenseGrowth=0.93, strategyGrowth=1.23, speedGrowth=0.44, siege=11, siegeGrowth=0.82, attackDistance=3, biography="【史】东汉末年割据汉中一带的军阀，据传是西汉留侯张良的十世孙、天师道（五斗米道）教祖张陵之孙。张鲁为五斗米道的第三代天师（称系师），在诛灭张修后继续在汉中一带传播五斗米道，并自称“师君”。雄据汉中近三十年，后投降曹操，官拜镇南将军，封阆中侯，食邑万户。张鲁去世后谥号为“原”，葬于邺城东。\n【演】在《三国演义》中，张鲁为汉宁太守，继父祖之后传播五斗米教。刘璋害死张鲁之母，二人因此结仇，多次交战。刘备攻益州时，刘璋向张鲁求援。张鲁派马超前往，但马超投降刘备。张鲁后见曹操自封魏王，想要自立为汉宁王，为谋士阎圃劝免。后曹操讨汉中，张鲁败，众人劝其烧粮仓，张鲁认为这是国家之物，未听从，为曹操所称赞。不久投降曹操，任镇南将军。", advancedTroops="长弓兵 、弩兵", combination="", policyName="携众北迁", policyText="担任主城或分城参军时，屯田时可获得木材资源4000" };
yield return new GeneralDefinition("s1_100639","彻里吉",Homeland.Han,4,79,"岁贡固疆","彻里吉·群·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100639.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="岁贡固疆", nativeSkillText="1回合准备，为友军群体恢复一定兵力（恢复率160.0%），并使其在下次行动时对距离3以内敌军单体发动一次攻击（伤害率150.0%）", defense=84, strategy=70, speed=30, cost=2.5, attackGrowth=1.09, defenseGrowth=1.04, strategyGrowth=0.67, speedGrowth=0.33, siege=13, siegeGrowth=0.75, attackDistance=2, biography="【演】《三国演义》中的虚构人物，西羌国王。诸葛亮“一出祁山”伐魏时，曾遣越吉元帅率羌兵并兵车十五万直扣阳平关，后羌兵大败，蜀国尽数归还所获俘虏辎重，彻里吉感蜀恩义，与之结盟。", advancedTroops="重步兵、长枪兵", combination="", policyName="不谙计策", policyText="可担任戍城参军，令所属部队步兵武将练兵经验增加2400" };
yield return new GeneralDefinition("s1_100636","迷当大王",Homeland.Han,4,78,"去缚犒军","迷当大王·群·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100636.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="去缚犒军", nativeSkillText="正式回合开始后，前3回合使自身受到的攻击伤害提升20.0%，从第4回合起，每回合自身行动前为我军群体恢复一定兵力（恢复率200.0%）", defense=76, strategy=50, speed=40, cost=2.5, attackGrowth=1.08, defenseGrowth=0.94, strategyGrowth=0.48, speedGrowth=0.5, siege=12, siegeGrowth=0.79, attackDistance=3, biography="【史】羌族首领，正始元年，响应姜维北伐曹魏，后被郭淮镇压。\n【演】羌族之王，与蜀交好，共讨魏国。姜维北伐之时，起兵五万出南安。后被魏将陈泰设计生擒，被郭淮好言相劝投降后，带魏兵奇袭蜀军大营。", advancedTroops="重步兵、长枪兵", combination="", policyName="中计亡生", policyText="可担任主城参军，令所属部队步兵武将征兵资源消耗降低4.8%" };
yield return new GeneralDefinition("s1_100491","金环三结",Homeland.Han,4,85,"莽撞","金环三结·群·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100491.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="莽撞", nativeSkillText="使自身防御属性提高35.0，同时随机使自身恢复一定兵力（恢复率150.0%），或进行攻击的伤害提高14.0%（受防御属性影响）", defense=70, strategy=40, speed=38, cost=2.5, attackGrowth=1.3, defenseGrowth=1.07, strategyGrowth=0.38, speedGrowth=0.42, siege=12, siegeGrowth=0.89, attackDistance=3, biography="【演】是《三国演义》的虚构人物。南蛮孟获属下大将，第一洞元帅。为了迎击蜀汉军马，与阿会喃、董荼那一起出洞。遭到夜袭，混乱之中被赵云一枪刺死。", advancedTroops="长枪兵、蛮兵", combination="", policyName="乱战未还", policyText="令势力所属全体部队蛮兵体力上限提高20" };
yield return new GeneralDefinition("s1_100116","袁术",Homeland.Han,4,78,"伪帝","袁术·群·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100116.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="伪帝", nativeSkillText="以每回合损失自身一定兵力为代价，使攻击属性提高39.0，防御属性提高42.0，持续2回合", defense=79, strategy=70, speed=37, cost=2.5, attackGrowth=1.08, defenseGrowth=1.09, strategyGrowth=0.87, speedGrowth=0.41, siege=20, siegeGrowth=1.66, attackDistance=2, biography="【史】袁逢之嫡次子，袁基、袁绍之弟。初为虎贲中郎将。董卓进京后以袁术为后将军，袁术因畏祸而出奔南阳。初平元年（190年）与袁绍、曹操等同时起兵，共讨董卓。后与袁绍对立，被袁绍、曹操击败，率馀众奔九江，割据扬州。建安二年（197年）称帝，建号仲氏 ，但未受人承认。此后袁术奢侈荒淫，横征暴敛，使江淮地区残破不堪，民多饥死，部众离心，先后为吕布、曹操所破，元气大伤，后于建安四年（199年）呕血而死。\n【演】在《三国演义》中，他的家族四代中有五人位居三公，是当世的大豪族。因董卓祸国，十八路诸侯聚讨董卓，袁术以第一镇诸侯的身份参与。同盟解散后，袁术为了除掉刘备，派遣使者想和吕布结亲，吕布将使者送给曹操斩首。得知吕布送斩他的使者，就发兵攻打他，却反被吕布所破。曹操又会合吕布、刘备、孙策等讨伐袁术，袁术大败。", advancedTroops="重步兵、禁卫", combination="", policyName="勇而无断", policyText="可担任分城参军，令该分城民居税收增加40.0%" };
yield return new GeneralDefinition("s1_100059","文丑",Homeland.Han,4,91,"奋威","文丑·群·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100059.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="奋威", nativeSkillText="对敌军群体发动一次攻击（伤害率130.0%），并挑衅之使其攻击自身，持续2回合", defense=89, strategy=50, speed=23, cost=2.5, attackGrowth=1.26, defenseGrowth=1.48, strategyGrowth=0.48, speedGrowth=0.29, siege=15, siegeGrowth=0.99, attackDistance=2, biography="【史】东汉末年冀州牧袁绍帐下的大将。建安五年（200年），袁绍命文丑率军于延津攻曹操，曹操以诱敌之计大破文丑一军，文丑于此战中丧生。\n【演】在《三国演义》中，于讨董战役的汜水关之战中第一次被提及。袁绍计逼韩馥，夺取冀州之时，关纯行刺袁绍，被文丑阵斩。磐河一战，文丑策马挺枪，直扑上桥，十余合大败公孙瓒，随后与颜良为先锋，击公孙瓒，平定河北。曹、袁交兵，先锋颜良攻白马被斩，文丑领军为其报仇，据延津挑战曹操，却中饵敌之计而军乱，文丑挺身独战，射退张辽，与徐晃大战三十合不分胜败，追击中正遇关羽，战不三合，心怯欲走，被关羽赶上斩于马下。", advancedTroops="重步兵、长枪兵", combination="河北四庭柱(成员:高览(群)、文丑(群)、颜良(群)、张郃(群)、颜良＆文丑(群),加成属性:攻击、防御)", policyName="有勇无谋", policyText="可担任军事设施参军，令所属己方部队兵力＜5000时，该部队行军速度提高10.0" };
yield return new GeneralDefinition("s1_100637","俄何烧戈",Homeland.Han,4,82,"叛羌急袭","俄何烧戈·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100637.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="叛羌急袭", nativeSkillText="对敌军群体发动一次攻击（伤害率225.0%），下一回合内，自身将会陷入犹豫状态", defense=78, strategy=44, speed=80, cost=2.5, attackGrowth=1.13, defenseGrowth=1.08, strategyGrowth=0.42, speedGrowth=0.99, siege=3, siegeGrowth=0.2, attackDistance=2, biography="【史】正史中俄何、烧戈为两名羌族首领。在联结蜀汉共同伐魏的过程中，为郭淮所败，两将双双被斩。\n【演】演义中的羌族将领，羌王迷当账下大将。羌军援蜀北伐之时，中魏将陈泰诈降之计，同陈泰共劫魏营，反被魏军围困，遂自刎而死。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="连羌叛魏", policyText="可担任戍城参军，令所属部队练兵的时间降低240秒" };
yield return new GeneralDefinition("s1_100635","丘力居",Homeland.Han,4,82,"寇略四州","丘力居·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100635.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="寇略四州", nativeSkillText="1回合准备，对敌军群体发动一次攻击（伤害率170.0%），使其攻击属性降低30.0，同时自身攻击属性提高60.0，持续2回合", defense=83, strategy=45, speed=81, cost=2.5, attackGrowth=0.9, defenseGrowth=0.91, strategyGrowth=0.75, speedGrowth=1, siege=2, siegeGrowth=0.14, attackDistance=3, biography="【史】东汉末年辽西乌丸首领，楼班之父。曾与张举、张纯于渔阳反叛，自立为三郡乌丸元帅，横行幽、冀、青、徐四州，后降于幽州牧刘虞。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="叛反掠民", policyText="可担任戍城参军，令所属部队骑兵武将练兵经验增加2400" };
yield return new GeneralDefinition("s1_100489","孟优",Homeland.Han,4,75,"愚勇","孟优·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100489.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="愚勇", nativeSkillText="使自身攻击属性提高30.0，但受到的所有伤害提高12.0%，持续2回合，并对敌军群体1-2目标发动一次猛攻（伤害率210.0%）", defense=84, strategy=51, speed=78, cost=2.5, attackGrowth=1.13, defenseGrowth=1.04, strategyGrowth=0.49, speedGrowth=0.86, siege=3, siegeGrowth=0.2, attackDistance=2, biography="【演】《三国演义》中的虚构人物，南蛮王孟获之弟。与诸葛亮的南征军交战，向战败的兄长推荐朵思大王，劝兄长借助朵思之力与蜀军对抗。后来与兄长一起归顺蜀汉。", advancedTroops="蛮兵、轻骑兵", combination="南蛮王者(成员:花鬘(群)、祝融夫人(群)、孟优(群)、祝融夫人(蜀)、孟获(群),加成属性:攻击、防御)", policyName="自恃武力", policyText="令势力所有部队蛮兵武将体力恢复速度提高30.0%" };
yield return new GeneralDefinition("s1_100430","张宝",Homeland.Han,4,77,"太平异道","张宝·群·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100430.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="太平异道", nativeSkillText="对敌军单体发动策略攻击（伤害率124.0%，受谋略属性影响），并窃取其15.4的攻击转化至自身（受谋略属性影响），持续1回合", defense=87, strategy=88, speed=50, cost=2, attackGrowth=0.78, defenseGrowth=1.11, strategyGrowth=1.13, speedGrowth=0.57, siege=9, siegeGrowth=0.69, attackDistance=4, biography="【史】张角之弟，张梁之兄，中平元年（184）二月，同兄弟一起发动黄巾起义，号地公将军。同年十一月于下曲阳（今河北晋州）遭到左中郎将皇甫嵩、钜鹿太守郭典的围攻，兵败被斩。\n【演】在《三国演义》中，张宝同兄弟一起发动黄巾起义，于阳城与朱儁军对抗。后刘备兄弟率军前来，帮助朱儁与张宝交战，张宝使用妖术，一度获胜，但不久就被破解，张宝被刘备射伤，逃入阳城坚守。朱儁等加紧围攻，张宝的部下严政斩了张宝，献首投降。", advancedTroops="长弓兵 、弩兵", combination="苍天已死(成员:张角(群)、张梁(群)、张宝(群),加成属性:谋略、【黄天当立】发动率提高)", policyName="义起乱世", policyText="令势力城外建造和升级铁矿消耗降低25.0%" };
yield return new GeneralDefinition("s1_100340","于吉",Homeland.Han,4,20,"符医术毒","于吉·群·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100340.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="符医术毒", nativeSkillText="对敌军单体发动一次策略攻击（伤害率168.0%，受谋略属性影响）并使其攻击属性降低32.0，持续1回合，同时有50.0%的几率为友军单体恢复一定兵力（恢复率153.0%，受谋略属性影响）", defense=34, strategy=90, speed=31, cost=2, attackGrowth=0.18, defenseGrowth=0.3, strategyGrowth=1.27, speedGrowth=0.36, siege=10, siegeGrowth=0.77, attackDistance=3, biography="【史】东汉末年黄老道代表人物之一，史书有两种说法：（1）认为其即《太平经》作者。《后汉书·襄楷传》：“顺帝时，琅邪宫崇诣阙，上其师干吉于曲阳泉水上所得神书百七十卷，皆缥白素朱介青首朱目，号《太平青领书》。”（2）认为其乃三国时道士，《三国志·孙策传》注引《江表传》：“时有道士琅邪于吉，先寓居东方，往来吴会，立精舍，烧香读道书，制作符水以治病，吴会人多事之。”后为孙策所斩。\n【演】在《三国演义》中，于吉在吴郡、会稽一带为百姓治病，深得人心。孙策以蛊惑人心为由将他斩了。后策常受吉咒，死。", advancedTroops="长弓兵 、弩兵", combination="", policyName="引道著经", policyText="可担任分城参军，令该分城资源产量均增加15.0%" };
yield return new GeneralDefinition("s1_100110","李儒",Homeland.Han,4,53,"逆反毒杀","李儒·群·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100110.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="逆反毒杀", nativeSkillText="使敌军群体陷入恐慌及怯战状态，每回合损失一定兵力（伤害率83.0%，受谋略属性影响），并且无法发动普通攻击，持续2回合", defense=63, strategy=93, speed=54, cost=2, attackGrowth=0.47, defenseGrowth=0.81, strategyGrowth=1.56, speedGrowth=0.69, siege=11, siegeGrowth=0.76, attackDistance=3, biography="【史】董卓专政时担任弘农王郎中令，奉董卓之命，入宫毒死汉少帝。董卓死后，李傕攻进长安，控制朝政，李傕推举博士李儒为侍中，但被汉献帝拒绝。\n【演】董卓的谋士，董卓的大小事宜均与之参谋，堪称智囊。董卓趁乱进京、说降吕布、废立皇帝、迁都长安等举动，均离不开李儒的参谋之功。汉少帝刘辩被废后不满，李儒奉董卓之命，亲自带人入宫，毒死刘辩。后王允使“连环计”离间董卓、吕布，李儒劝董卓放弃貂蝉而换取吕布的效忠，董卓最终没有听从，死于吕布之手。董卓死时，李儒卧病在家，被家仆捆绑献出，处斩于市曹之中。", advancedTroops="长弓兵 、弩兵", combination="", policyName="为虎傅翼", policyText="令势力所有领地木材产量增加100" };
yield return new GeneralDefinition("s1_100048","邹氏",Homeland.Han,4,59,"枭雄所愿","邹氏·群·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100048.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="枭雄所愿", nativeSkillText="战斗开始后第5回合直到战斗结束，使我军群体进入休整状态，每回合恢复一定兵力（恢复率118.0%，受谋略属性影响），并使其能够优先行动", defense=79, strategy=55, speed=30, cost=2, attackGrowth=0.76, defenseGrowth=1.01, strategyGrowth=0.71, speedGrowth=0.35, siege=16, siegeGrowth=1.1, attackDistance=1, biography="【演】在《三国演义》中，出现在第十六回，被曹操强纳，因而之后有张绣造反，曹操兵败宛城，曹昂、典韦、曹安民战死等诸多之事。", advancedTroops="重步兵、长枪兵", combination="", policyName="艳倾枭雄", policyText="可担任分城参军，令该分城城内设施的建造和升级木材消耗降低20.0%" };
yield return new GeneralDefinition("s1_100047","严氏",Homeland.Han,4,90,"怯弱","严氏·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100047.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="怯弱", nativeSkillText="战斗开始后前3回合，使敌军单体攻击距离-1，进行策略攻击时的伤害下降36.0%（受谋略属性影响）", defense=63, strategy=67, speed=75, cost=2, attackGrowth=1.14, defenseGrowth=0.81, strategyGrowth=0.86, speedGrowth=1.06, siege=1, siegeGrowth=0.06, attackDistance=2, biography="【史】东汉末年著名武将吕布的正妻，未提及姓名。在李傕郭汜之乱期间曾受困，幸亏被庞舒所救，私藏于府中而得以幸免。吕布被曹操围困时，反对陈宫的计谋，导致了吕布的失败。\n【演】在《三国演义》中，严氏是吕布的妻子。", advancedTroops="轻骑兵、弓骑兵", combination="", policyName="碍计误军", policyText="可担任分城参军，令该分城城内设施的建造和升级时间降低6.0%" };
yield return new GeneralDefinition("s1_100058","颜良",Homeland.Han,4,92,"骁勇","颜良·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100058.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="骁勇", nativeSkillText="对敌军群体发动一次攻击（伤害率150.0%），并使其进行攻击时的伤害降低25.0%，持续2回合", defense=74, strategy=52, speed=95, cost=2.5, attackGrowth=1.53, defenseGrowth=1.02, strategyGrowth=0.5, speedGrowth=1.31, siege=2, siegeGrowth=0.14, attackDistance=1, biography="【史】东汉末年河北军阀袁绍部将，以勇而闻名。建安四年（199年），袁绍以颜良、文丑为将，率精卒十万，准备攻许（今河南许昌）。建安五年（200年），兵进黎阳（今河南浚县），遣颜良攻白马（今河南滑县）。曹操北救，以荀攸计分兵渡河，引袁绍西应，自率轻兵掩袭白马，颜良仓猝逆战，被关羽击斩。\n【演】在《三国演义》中，颜良未参加关东联军，使袁绍颇为华雄的猖狂而叹息。绍计逼韩馥，谋夺冀州，耿武欲行刺，颜良斩之。随后与文丑为先锋，击公孙瓒，平定河北。曹袁交兵，颜良统十万精兵为前部，进攻白马，连斩宋宪、魏续，二十合败徐晃，曹军诸将栗然。关羽出战，颜良方欲问时，因赤兔马快，措手不及，被关羽一刀刺于马下而死。", advancedTroops="重骑兵、轻骑兵", combination="河北四庭柱(成员:高览(群)、文丑(群)、颜良(群)、张郃(群)、颜良＆文丑(群),加成属性:攻击、防御)", policyName="骁勇促狭", policyText="可担任军事设施参军，令所属己方部队行军速度提高10.0，但该军事设施耐久上限降低20" };
yield return new GeneralDefinition("s1_100057","田丰",Homeland.Han,4,50,"直言","田丰·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100057.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="直言", nativeSkillText="恢复我军群体一定兵力（恢复率112.0%，受谋略属性影响），并使其谋略属性提高30.0，持续2回合", defense=84, strategy=91, speed=79, cost=2.5, attackGrowth=0.55, defenseGrowth=1.28, strategyGrowth=1.52, speedGrowth=0.98, siege=4, siegeGrowth=0.27, attackDistance=1, biography="【史】东汉末年袁绍部下谋臣，官至冀州别驾。其为人刚直，曾多次向袁绍进言而不被采纳，曹操部下谋臣荀彧曾评价他“刚而犯上”。后因谏阻袁绍征伐曹操而被袁绍下令监禁。官渡之战后，田丰被袁绍所害。\n【演】在《三国演义》中，田丰博览多识，权略多奇，曾在朝中任侍御史，因不满宦官专权，弃官归家。袁绍起兵讨伐董卓，应其邀请，出任别驾，以图匡救王室之志。后袁绍用田丰谋略，消灭公孙瓒，平定河北，虎据四州。官渡之战，田丰建议据险固守，分兵抄掠的疲敌策略，乃至强谏，被袁绍以为沮众，械系牢狱。建安五年，袁绍官渡战败，因羞见田丰而害。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="刚而犯上", policyText="令势力城外建造和升级石料消耗降低20.0%" };
yield return new GeneralDefinition("s1_100052","管亥",Homeland.Han,4,91,"劫掠","管亥·群·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100052.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="劫掠", nativeSkillText="普通攻击后，对攻击目标再次发动攻击（伤害率50.0%），并有50.0%的几率借此恢复一定兵力", defense=70, strategy=33, speed=84, cost=2.5, attackGrowth=1.26, defenseGrowth=0.97, strategyGrowth=0.32, speedGrowth=1.15, siege=5, siegeGrowth=0.33, attackDistance=2, biography="【史】东汉末年黄巾军的将领。孔融屯兵都昌时，他率军围攻孔融，孔融派太史慈前去向刘备求救，他被刘备的援军击退。\n【演】在《三国演义》中，管亥曾经一合阵斩孔融的大将宗宝，后与关羽大战数十合后被斩。", advancedTroops="重骑兵、轻骑兵", combination="黄巾强将(成员:周仓(群)、张曼成(群)、管亥(群),加成属性:攻城、攻击距离提高)", policyName="渠帅之侵", policyText="可担任军事设施参军，令所属己方部队出征山寨时行军速度提高10.0%" };
yield return new GeneralDefinition("s1_100640","朵思大王",Homeland.Han,4,64,"疫箭拦江","朵思大王·群·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100640.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="疫箭拦江", nativeSkillText="1回合准备，使敌军群体陷入动摇（伤害率130.0%）和恐慌状态（伤害率130.0%，受谋略属性影响），持续2回合", defense=59, strategy=81, speed=58, cost=2, attackGrowth=0.74, defenseGrowth=0.68, strategyGrowth=1.04, speedGrowth=0.59, siege=8, siegeGrowth=0.43, attackDistance=4, biography="【演】《三国演义》中的虚构人物，南蛮秃龙洞元帅，号称南蛮第一智者。曾以南蛮地势与四眼毒泉防御；被俘释放后，又于三江城以毒矢大败蜀军，后三江城破，死于乱军之中。", advancedTroops="长弓兵 、蛮兵", combination="", policyName="南蛮智者", policyText="可担任军事设施参军，令所属部队群阵营武将征兵资源消耗降低5.0%" };
yield return new GeneralDefinition("s1_100040","朱儁",Homeland.Han,4,89,"节镇关东","朱儁·汉·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100040.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="节镇关东", nativeSkillText="战斗开始后前2回合，使我军群体每回合都能优先行动，在此期间，令敌军群体陷入动摇，每回合损失一定兵力（伤害率120.0%），动摇效果造成的伤害无视规避", defense=83, strategy=75, speed=48, cost=2.5, attackGrowth=0.96, defenseGrowth=0.9, strategyGrowth=0.65, speedGrowth=0.52, siege=12, siegeGrowth=0.7, attackDistance=4, biography="【史】东汉末年名将。光和七年（184年），黄巾起义爆发，朱儁担任右中郎将、持节。平定三郡之地后，被皇甫嵩上表推功，进封西乡侯，迁任镇贼中郎将。又率军讨平南阳黄巾。董卓秉政时，想任朱儁为副手，遭其婉拒。其后出逃荆州，更屯军中牟，徐州刺史陶谦等欲推举他为太师，并传檄各州牧伯，相邀讨伐李傕、奉迎天子。但朱儁却奉诏入京任太仆。兴平二年（195年），李傕、郭汜相攻时，郭汜扣留朱儁为人质，朱儁性格刚烈，同日即发病而死。\n【演】在《三国演义》中，朱儁形象与正史相似。是汉车骑将军。黄巾起义时，为中郎将，引军讨伐。屡立功绩，迁车骑将军，河南尹。后董卓余党李傕、郭汜乱政，掠夺公卿，朱儁对汉室衰微的状况感到悲哀，归家后即病逝。", advancedTroops="长弓兵 、弩兵", combination="末路尽忠(成员:卢植(汉)、张奂(汉)、朱儁(汉)、皇甫嵩(汉),加成属性:防御、速度、镇静)、汉朝官军(成员:皇甫嵩(汉)、何进(汉)、朱儁(汉),加成属性:攻击)", policyName="大将之略", policyText="可担任戍城参军，令己方部队驻守在该戍城补给范围内时，战斗后立即恢复20.0%伤兵" };
yield return new GeneralDefinition("s1_100001","献帝",Homeland.Han,4,35,"衣带密诏","献帝·汉·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100001.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="衣带密诏", nativeSkillText="使友军单体的攻击属性提高18.8（受谋略属性影响），并使其进入休整状态，每回合恢复一定兵力（恢复率80.0%，受谋略属性影响），持续2回合", defense=81, strategy=81, speed=41, cost=2.5, attackGrowth=0.38, defenseGrowth=1.14, strategyGrowth=0.79, speedGrowth=0.45, siege=9, siegeGrowth=0.41, attackDistance=3, biography="【史】东汉最后一任皇帝，公元189年－220年在位。因被董太后抚养，故称“董侯”，初封渤海王，后改封陈留王。公元189年，董卓废汉少帝刘辩，立刘协为皇帝。董卓被王允和吕布诛灭后，董卓部将李傕等攻入长安，再次挟持了他，后来逃出长安。公元196年，曹操控制了刘协，并迁都许县，挟天子以令诸侯。公元220年，曹操病死，刘协被曹丕控制，随后被迫禅让于曹丕。公元234年，刘协寿终正寝，享年54岁。\n【演】在《三国演义》中，他是汉灵帝中子。汉中平九月甲戌，即皇帝位，年九岁。后为董卓、曹操接连要挟，成为傀儡。建安二十五年冬十月乙卯，帝逊位，丕称天子。奉帝为山阳公。传言帝遇害，汉中王刘备闻知，痛哭终日，下令百官挂孝，遥望设祭，上尊谥曰“孝愍皇帝”。", advancedTroops="长弓兵 、禁卫", combination="汉朝皇族(成员:少帝(汉)、灵帝(汉)、献帝(汉),加成属性:防御)、献帝父子(成员:灵帝(汉)、王美人(汉)、献帝(汉),加成属性:防御)", policyName="不甘傀儡", policyText="令势力粮草产量提高4200" };
yield return new GeneralDefinition("s1_100039","皇甫嵩",Homeland.Han,4,76,"猛火","皇甫嵩·汉·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100039.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="猛火", nativeSkillText="对敌军单体发动策略攻击（伤害率80.0%，受谋略属性影响），并使其陷入燃烧状态，每回合损失一定兵力（伤害率75.0%，受谋略属性影响），持续1回合", defense=93, strategy=82, speed=89, cost=2.5, attackGrowth=0.82, defenseGrowth=1.01, strategyGrowth=0.8, speedGrowth=0.96, siege=7, siegeGrowth=0.41, attackDistance=2, biography="【史】为人仁爱谨慎，尽忠职守，有谋略，有胆识。于黄巾起义时，以中郎将身份讨伐黄巾，用火攻大破张梁、张宝，拜左车骑将军。后因拒绝贿赂宦官而被免职。董卓掌权时，征皇甫嵩入朝为城门校尉，因私怨被其陷害下狱，经其子皇甫坚寿求情才得以保全。\n【演】在《三国演义》中，皇甫嵩形象与正史相似。于黄巾起义时，大破张梁、张宝。后接替董卓进攻张梁，连胜七阵。掘张角墓，拜左车骑将军、冀州牧，因拒绝贿赂宦官而被免职。董卓死，王允命其与吕布等共至郿坞抄籍董卓家产、人口，皇甫嵩将坞中所藏良家子女，尽行释放。", advancedTroops="重骑兵、轻骑兵", combination="末路尽忠(成员:卢植(汉)、朱儁(汉)、皇甫嵩(汉)、张奂(汉),加成属性:防御、速度、镇静)、汉朝官军(成员:何进(汉)、朱儁(汉)、皇甫嵩(汉),加成属性:攻击)", policyName="尽忠职守", policyText="令势力部队维持消耗降低50.0%" };
yield return new GeneralDefinition("s1_100378","伏寿",Homeland.Han,4,76,"乱离中宫","伏寿·汉·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100378.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="乱离中宫", nativeSkillText="移除友军全体的有害效果，并使其攻击属性提高27.0（受谋略属性影响），持续2回合", defense=50, strategy=71, speed=42, cost=2, attackGrowth=0.76, defenseGrowth=0.5, strategyGrowth=1.01, speedGrowth=0.42, siege=6, siegeGrowth=0.33, attackDistance=2, biography="【史】汉献帝皇后，徐州琅邪郡东武县（今山东诸城）人，西汉大司徒伏湛八世孙，父亲是学者伏完，母为阳安长公主刘华。作为皇后二十年，于建安十九年被曹操幽闭而死。\n【演】在《三国演义》中，伏寿的生平与正史大体相当，不过在小说里，伏寿并非病死，而是与伏完一起谋划除掉曹操，但遭曹操发现而被族灭。有诗叹曰：“曹瞒凶残世所无，伏完忠义欲何如。可怜帝后分离处，不及民间妇与夫！”", advancedTroops="长弓兵 、弩兵", combination="", policyName="谋诛拼生", policyText="令势力铁矿资源上限提高200000" };
yield return new GeneralDefinition("s1_100379","杜氏",Homeland.Han,4,32,"飘零红颜","杜氏·汉·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="步", sourceUrl="https://stzb.163.com/herolist/100379.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="飘零红颜", nativeSkillText="以一定兵力为代价，对敌军群体发动一次策略攻击（伤害率90.0%，受谋略属性影响），并使其的攻击距离-1，持续1回合", defense=78, strategy=61, speed=27, cost=2, attackGrowth=0.32, defenseGrowth=1.03, strategyGrowth=0.61, speedGrowth=0.27, siege=17, siegeGrowth=0.92, attackDistance=2, biography="【史】初为吕布麾下秦宜禄之妻，生子秦朗。吕布被围时，关羽曾向曹操讨要杜氏，曹操不允，后曹操自纳之，又生曹林、曹衮、金乡公主。", advancedTroops="重步兵、长枪兵", combination="", policyName="颠沛太妃", policyText="令势力石料资源上限提高200000" };
yield return new GeneralDefinition("s1_100041","张奂",Homeland.Han,4,78,"威震北疆","张奂·汉·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="步", sourceUrl="https://stzb.163.com/herolist/100041.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="威震北疆", nativeSkillText="使敌军群体陷入恐慌状态，每回合损失一定兵力（伤害率64.0%，受谋略属性影响），同时谋略属性下降20.0，持续2回合", defense=79, strategy=88, speed=33, cost=2, attackGrowth=0.78, defenseGrowth=0.79, strategyGrowth=0.97, speedGrowth=0.3, siege=20, siegeGrowth=1.08, attackDistance=2, biography="【史】东汉时期名将、学者，凉州三明之一。汉阳太守张惇之子。少年时师从太尉朱宠，学习《欧阳尚书》，又自行删减《牟氏章句》。在东汉对外战争中功勋卓著，多次以恩信安抚、招降外族，使得北方宁静一时。后入朝，为宦官所利用，率军前往进击窦武。\n事后自责不已，拒受封侯。拜少府，迁任大司农，又上疏为窦武等人伸冤。不久迁太常，因得罪宦官被诬陷罢免。最终回乡教授弟子，不再出仕。光和四年（181年）去世，终年七十八岁，遗令素服薄葬。", advancedTroops="重步兵、长枪兵", combination="末路尽忠(成员:卢植(汉)、张奂(汉)、朱儁(汉)、皇甫嵩(汉),加成属性:防御、速度、镇静)", policyName="仁惠及民", policyText="可担任分城参军，令该分城补给范围内己方领地产量提高80" };
yield return new GeneralDefinition("s1_100471","曹节",Homeland.Han,4,70,"身佑废皇","曹节·汉·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100471.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="身佑废皇", nativeSkillText="使友军全体受到攻击的伤害以及发动攻击造成的伤害都降低28.0%（受谋略属性影响），持续2回合", defense=70, strategy=64, speed=83, cost=2, attackGrowth=0.7, defenseGrowth=0.99, strategyGrowth=0.78, speedGrowth=0.83, siege=1, siegeGrowth=0.05, attackDistance=2, biography="【史】曹操次女。初为汉献帝贵人，伏皇后被废杀后，进号皇后。建安二十五年，其兄长曹丕代汉自立，派遣使者索取皇帝玺绶，曹皇后愤怒不与。如此反复数次，曹皇后最终召见使者，要亲手交出玉玺。但使者来后，她又将玉玺摔至轩下，流泪怒斥：“天不祚尔！”左右皆莫能仰视。献帝禅位后被封山阳公，曹节为山阳公夫人，去世后谥曰“献穆皇后”。\n【演】在《三国演义》中，曹节生平与正史大体一致。而曹节则是对曹休、曹洪破口大骂：“俱是汝等乱贼，希图富贵，共造逆谋！吾父功盖寰区，威震天下，然且不敢篡窃神器。今吾兄嗣位未几，辄思篡汉，皇天必不祚尔！”言罢，痛哭入宫。", advancedTroops="禁卫、重骑兵", combination="", policyName="扔玺责兄", policyText="可担任分城参军，令该分城仓库资源上限提高15.0%" };
yield return new GeneralDefinition("s1_100355","蔡夫人",Homeland.Han,4,24,"猜忌","蔡夫人·汉·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="步", sourceUrl="https://stzb.163.com/herolist/100355.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="猜忌", nativeSkillText="使敌军单体防御属性降低41.0（受谋略属性影响）、速度属性降低53.0（受谋略属性影响），持续2回合，在此期间，每回合开始时都会移除其有益状态", defense=30, strategy=83, speed=29, cost=1.5, attackGrowth=0.18, defenseGrowth=0.23, strategyGrowth=0.78, speedGrowth=0.28, siege=14, siegeGrowth=0.79, attackDistance=2, biography="【史】荆州牧刘表的后妻，荆襄一带的豪族蔡氏家族的一员。她是诸葛亮之妻黄月英的姨母，以侄女妻表次子刘琮，因爱之，常毁刘琦而誉刘琮于表。表死，与蔡瑁等共排表长子刘琦，奉刘琮为嗣，寻降曹操。\n【演】在《三国演义》中，蔡夫人为荆州刺史刘表后妻、刘琮生母、蔡瑁之姐。心肠恶毒，因先主劝刘表立长子琦为嗣，深恨之，数次欲加害于琦。后表亡，借兄瑁之力，立子琮为主。操军到襄阳，蔡氏随子琮举州请降。操命琮为青州刺史，上任途中，命于禁将其母子二人灭口。", advancedTroops="长弓兵 、长枪兵", combination="", policyName="祸乱是非", policyText="令势力四项资源上限均提高50000" };
yield return new GeneralDefinition("s1_100420","夏侯渊",Homeland.Han,4,88,"疾行速战","夏侯渊·魏·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100420.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="疾行速战", nativeSkillText="对敌军单体发动一次攻击（伤害率150.0%），并使其进行攻击的伤害降低31.0%（受速度属性影响），持续1回合", defense=92, strategy=54, speed=91, cost=3, attackGrowth=1.14, defenseGrowth=1.21, strategyGrowth=0.49, speedGrowth=1.32, siege=2, siegeGrowth=0.15, attackDistance=2, biography="【史】东汉末年名将，擅长千里奔袭作战，官至征西将军，封博昌亭侯。初期随曹操征伐，官渡之战为曹操督运粮草，又督诸将先后平定昌豨、徐和、雷绪、商曜等叛乱。后率军驻凉州，逐马超、破韩遂、灭宋建、横扫羌、氐，虎步关右。张鲁降曹操后夏侯渊留守汉中，与刘备相拒逾年，于定军山被刘备部将黄忠所袭，战死，谥曰愍侯。\n【演】在《三国演义》中，夏侯渊是夏侯婴之后、大将军惇族弟。自曹操陈留起兵起，便跟随征伐，历任陈留、颍川太守。官渡之战后，夏侯渊负责粮草补给，保证了曹操平定北方。而后夏侯渊又率兵四处征讨叛乱，破昌豨、徐和、雷绪、商曜等，战功卓著。而后夏侯渊督张郃、徐晃等留守汉中，与前来取汉中的刘备大军交战，为刘备将黄忠所袭，不幸战死。谥曰愍侯。魏齐王正始四年从祀曹操庙庭。", advancedTroops="重骑兵、轻骑兵", combination="魏武强将(成员:夏侯惇(魏)、夏侯渊(魏)、曹洪(魏)、曹仁(魏),加成属性:攻击、速度)", policyName="五出平叛", policyText="可担任主城参军，令所属部队魏阵营武将征兵资源消耗降低8.0%" };
yield return new GeneralDefinition("s1_100644","王双",Homeland.Han,4,95,"万夫之勇","王双·魏·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100644.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="万夫之勇", nativeSkillText="普通攻击后，随机对敌军中军或大营发动一次猛攻（伤害率160.0%），并使其陷入动摇状态，每回合损失一定兵力（伤害率80.0%），持续2回合", defense=90, strategy=28, speed=40, cost=3, attackGrowth=1.63, defenseGrowth=1.18, strategyGrowth=0.26, speedGrowth=0.36, siege=15, siegeGrowth=0.94, attackDistance=1, biography="【史】正史中，王双为曹真部将，于诸葛亮第二次北伐时追击撤还的蜀军，后战死。\n【演】魏国将领，善使流星锤，有万夫不当之勇。诸葛亮“二出祁山”之时，曾被曹真举荐，任虎威将军，驰援坚守陈仓的郝昭。于阵中斩蜀国数将，又重创张嶷，后因中了诸葛亮的诱敌之计为魏延所斩。", advancedTroops="重步兵、禁卫", combination="", policyName="铁弓神力", policyText="可担任戍城参军，令所属部队魏阵营武将练兵经验增加6000" };
yield return new GeneralDefinition("s1_100081","典韦",Homeland.Han,4,93,"奋不顾身","典韦·魏·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100081.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="奋不顾身", nativeSkillText="援护友军单体，为其抵挡普通攻击，并使自身进入休整状态，每回合恢复一定兵力（恢复率200.0%），持续3回合", defense=92, strategy=33, speed=29, cost=3, attackGrowth=1.22, defenseGrowth=1.45, strategyGrowth=0.3, speedGrowth=0.34, siege=18, siegeGrowth=1.27, attackDistance=1, biography="【史】曹操部将，相貌魁梧，膂力过人。本属张邈，后归曹操。曹操征讨吕布时被募为陷阵，表现英勇，被拜为校尉，宿卫曹操。后曹操于宛城时，张绣先降而复反，急迫曹操本营；典韦守着大门，殊死恶斗，破敌无算，最终因敌人太多而战死。 \n【演】在《三国演义》中，因其悍武，曹操称其为“古之恶来”。张绣背叛时，先令胡车儿暗盗韦双戟，再引军急迫曹操本营。典韦守大门，殊死恶斗，破敌无算，刀坏了竟双手各提一人为武器迎敌。群贼不敢近，只远远以箭射之，箭如骤雨，典韦犹死拒寨门。", advancedTroops="重步兵、禁卫", combination="", policyName="克宁寰宇", policyText="可担任主城参军，令主城城区耐久上限提高250" };
yield return new GeneralDefinition("s1_100084","庞德",Homeland.Han,4,79,"死战明志","庞德·魏·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100084.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="死战明志", nativeSkillText="战斗中使自身处于洞察状态，免疫混乱、犹豫、怯战、暴走和挑衅效果，防御属性提高25.0", defense=98, strategy=71, speed=96, cost=3, attackGrowth=1.04, defenseGrowth=1.42, strategyGrowth=0.74, speedGrowth=1.26, siege=2, siegeGrowth=0.13, attackDistance=1, biography="【史】初为马腾部下，在平定羌民的征伐中屡立战功。建安年间，庞德跟随马超征战，每次出征常冲锋陷阵，勇冠凉州三军。后几经辗转，随张鲁归降于曹操麾下。219年，庞德协助曹仁抵御关羽。时值汉水暴溢，他率诸将与关羽殊死搏斗，箭镞尽，又短兵相接。\n而他格斗益怒，胆气愈壮，力战多时后因小舟被洪水打翻为关羽军所擒。关羽敬重他的刚毅威武，以封将劝降，但他却怒目不跪，怒斥关羽，最终殒身殉节。\n【演】在《三国演义》中，曹操进攻汉中时，庞德被曹操所擒，且因张鲁的不仁而转投曹操。此后，庞德屡立战功，濡须口之战斩东吴名将陈武，汉中之战中击败蜀汉名将魏延，救出曹操。后来曹仁被关羽包围在樊城，庞德随于禁引军赴救。其时诸将皆以庞德兄长庞柔、故主马超均在蜀，都怀疑庞德有二心；\n庞德抬棺决死，遂力斗关羽父子，又箭射关羽，深为关羽所忌惮。然而于禁惧其立功，加以掣肘。魏军战败，庞德被周仓在水中擒获，誓死不降，为关羽所害。曹操闻知此事甚为伤悲，为之流涕。", advancedTroops="重步兵、重骑兵", combination="", policyName="陨身殉节", policyText="可担任军事设施参军，令所属己方部队中纯骑兵组成部队行军速度提高15.0点" };
yield return new GeneralDefinition("s1_100079","夏侯惇",Homeland.Han,4,89,"拔箭啖睛","夏侯惇·魏·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100079.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="拔箭啖睛", nativeSkillText="战斗中，每当自身受到攻击伤害后，将使攻击、防御属性提高10.0，此效果最多叠加15次", defense=92, strategy=76, speed=83, cost=3, attackGrowth=1.05, defenseGrowth=1.21, strategyGrowth=0.69, speedGrowth=0.98, siege=3, siegeGrowth=0.19, attackDistance=1, biography="【史】汉末年三国时期曹魏名将，西汉开国元勋夏侯婴的后代。少年时以勇气闻名于乡里。曹操起兵，夏侯惇是其最早的将领之一。与吕布军交战时，曾一度被擒为人质，又被流矢射瞎左眼。多次为曹操镇守后方，曾率军民阻断太寿河水，筑陂塘灌溉农田，使百姓受益，功勋卓著。历任折冲校尉、济阴太守、建武将军，官至大将军，封高安乡侯，追谥忠侯。青龙元年（233年），得以配享太祖（曹操）庙庭。\n【演】在《三国演义》中，夏侯惇在徐州攻防战时迎战吕布部将高顺，高顺败逃，夏侯惇从后追赶，不料遭另一名敌将曹性射箭偷袭。夏侯惇左眼被射中，痛得怒吼一声便匆忙用手拔箭，却不慎连着眼珠子拔了出来。夏侯惇立即大喊：“父精母血，不可弃也！”便把眼睛塞进嘴巴吞咽下去；然后又挺枪纵马，上前斩了曹性报回一箭之仇。", advancedTroops="重骑兵、铁骑兵", combination="魏武强将(成员:夏侯渊(魏)、曹洪(魏)、夏侯惇(魏)、曹仁(魏),加成属性:攻击、速度)", policyName="失睛之训", policyText="可担任军事设施参军，令所属己方部队武将重伤恢复时间降低240秒" };
yield return new GeneralDefinition("s1_100643","文钦",Homeland.Han,4,89,"勇而无算","文钦·魏·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100643.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="勇而无算", nativeSkillText="对敌军群体发动一次攻击（伤害率200.0%），同时使自身受到的谋略攻击伤害提高50.0%，持续1回合", defense=92, strategy=55, speed=86, cost=2.5, attackGrowth=1.07, defenseGrowth=0.99, strategyGrowth=0.46, speedGrowth=0.82, siege=3, siegeGrowth=0.22, attackDistance=3, biography="【史】魏国将领，文鸯、文虎之父。曾与毌丘俭起兵勤王，讨伐司马师，兵败后投奔吴国，任镇北大将军，幽州牧，封谯侯。后其随吴军援助起兵反抗司马氏的诸葛诞，却与之不和被诛。\n【演】在《三国演义》中，文钦和正史的形象大体相当。", advancedTroops="重骑兵、轻骑兵", combination="一门虎将(成员:文虎(晋)、文鸯(晋)、文钦(魏),加成属性:攻击)", policyName="反复无常", policyText="可担任戍城参军，令所属部队魏阵营武将体力上限增加15" };
yield return new GeneralDefinition("s1_100421","徐晃",Homeland.Han,4,93,"斧钺之利","徐晃·魏·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100421.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="斧钺之利", nativeSkillText="移除敌军群体的有益效果，并使其因为受重伤而动摇，每回合产生逃兵（伤害率120.0%），持续2回合", defense=84, strategy=64, speed=75, cost=2.5, attackGrowth=1.23, defenseGrowth=1.11, strategyGrowth=0.53, speedGrowth=0.9, siege=4, siegeGrowth=0.23, attackDistance=2, biography="【史】三国时期曹魏名将。本为杨奉帐下骑都尉，杨奉被曹操击败后转投曹操，在曹操手下多立功勋，参与官渡、赤壁、关中征伐、汉中征伐等几次重大战役。樊城之战中徐晃作为曹仁的援军击败关羽，因于此役中治军严整而被曹操称赞“有周亚夫之风”。曹丕称帝后，徐晃被加为右将军，于公元227年病逝，谥曰壮侯。\n【演】在《三国演义》中，徐晃的生平与正史大体相当。", advancedTroops="重骑兵、轻骑兵", combination="五子良将(成员:乐进(魏)、于禁(魏)、徐晃(魏)、张辽(魏),加成属性:攻击)", policyName="奇功解围", policyText="可担任军事设施参军，令所属己方部队中魏阵营武将所在部队体力恢复速度提高20.0%" };
yield return new GeneralDefinition("s1_100149","程昱",Homeland.Han,4,62,"重谋","程昱·魏·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100149.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="重谋", nativeSkillText="使我军单体的谋略属性提高16.8（受谋略属性影响），防御属性提高18.0（受谋略属性影响），持续3回合", defense=76, strategy=93, speed=25, cost=2, attackGrowth=0.69, defenseGrowth=0.76, strategyGrowth=1.36, speedGrowth=0.22, siege=17, siegeGrowth=1.02, attackDistance=2, biography="【史】东汉后期至三国时期曹魏谋士、名臣。本名程立，因梦中在泰山捧日，更名程昱。曾于东阿率领民众抗击黄巾。初平三年，被曹操征辟为寿张令，从此为其出谋献策、征战四方。曹操征徐州时，程昱与荀彧留守后方，阻吕布、陈宫大军，保住三城。\n【演】在《三国演义》中，程昱初在山中读书，经荀彧荐仕曹操。曾于徐州用计迫降关羽；曹操征河北，昱举羽以敌颜良，又於仓亭献十面埋伏之计，大胜袁绍。后与刘备战，昱计挟亲赚徐庶，使庶来投。从南征，昱谏曹操以防火攻，又识黄盖粮船之伪，免大寨遭创，曹操亦因此逃逸得及。后又于濡须劝曹操班师。魏国既建，以昱为卫尉。", advancedTroops="重步兵、长枪兵", combination="三国智将(成员:鲁肃(吴)、法正(蜀)、程昱(魏),加成属性:谋略)、魏之智(成员:贾诩(魏)、荀攸(魏)、程昱(魏)、郭嘉(魏)、荀彧(魏),加成属性:谋略)", policyName="百堵皆兴", policyText="令势力城外建造和升级资源消耗降低15.0%" };
yield return new GeneralDefinition("s1_100076","卞夫人",Homeland.Han,4,32,"素衣伶姬","卞夫人·魏·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100076.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="素衣伶姬", nativeSkillText="战斗开始后前3回合，使敌军群体进行策略攻击时的伤害降低26.0%（受谋略属性影响），此效果结束后的1回合内有100.0%的几率陷入混乱状态", defense=41, strategy=70, speed=90, cost=2, attackGrowth=0.36, defenseGrowth=0.46, strategyGrowth=0.78, speedGrowth=1, siege=6, siegeGrowth=0.32, attackDistance=1, biography="【史】魏武帝曹操的正妻（继室），魏文帝曹丕、任城威王曹彰、陈思王曹植、萧怀王曹熊的母亲。原本是倡家，即汉代专门从事音乐歌舞的乐人家庭，后来与曹操成婚，建安初年，原配丁夫人被废，卞夫人成为曹操的正妻。曹丕继位后尊其为皇太后，曹叡继位后尊其为太皇太后。卞后在太和四年去世，与魏武帝曹操合葬高陵。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="内助之贤", policyText="可担任分城参军，令该分城城内设施的建造和升级资源消耗降低10.0%" };
yield return new GeneralDefinition("s1_100077","丁夫人",Homeland.Han,4,50,"决绝","丁夫人·魏·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100077.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="决绝", nativeSkillText="使敌军单体陷入犹豫状态，无法发动主动战法，并使其受到策略攻击时的伤害提高28.0%（受谋略属性影响），持续2回合", defense=72, strategy=66, speed=24, cost=1.5, attackGrowth=0.53, defenseGrowth=0.76, strategyGrowth=0.48, speedGrowth=0.23, siege=19, siegeGrowth=1.07, attackDistance=2, biography="【史】曹操的正室，曹操长子曹昂的养母。因养子之死与曹操决裂，后来离异，丁夫人去世后，葬在许都城南。\n【演】在《三国演义》中，丁夫人乃曹操大妻，因为无出被黜。", advancedTroops="重步兵、长枪兵", combination="母仪天下(成员:吴夫人(吴)、丁夫人(魏)、甘皇后(蜀)、何太后(汉)、郭皇后(魏)、卫子夫(汉)、阴丽华(汉),加成属性:谋略、速度)", policyName="哀子长怨", policyText="可担任分城参军，令该分城石料产量增加25.0%" };
yield return new GeneralDefinition("s1_100398","关兴＆张苞",Homeland.Han,4,86,"勇将继传","关兴＆张苞·蜀·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100398.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="勇将继传", nativeSkillText="战斗开始后前4回合，使自身造成的伤害无视规避，在此期间，每回合都有90.0%进入分兵状态，普通攻击后同时对附近的敌军造成伤害（伤害率100.0%）", defense=77, strategy=57, speed=25, cost=4, attackGrowth=1.49, defenseGrowth=1.34, strategyGrowth=0.62, speedGrowth=0.36, siege=19, siegeGrowth=1.79, attackDistance=1, biography="【史】关兴为关羽次子，蜀汉后期重要将领，在诸葛亮第六次北伐之前病逝。张苞为张飞长子，早夭。\n【演】在《三国演义》中，关兴和张苞是关系很好的结拜兄弟，两人并称“小关张”。在蜀军中的表现相当活跃。", advancedTroops="重步兵、禁卫", combination="", policyName="名门虎子", policyText="可担任军事设施参军，部队每有一个蜀阵营武将上阵，则部队征兵铁矿、粮草消耗降低2.0%，如果关羽或张飞上阵，则该部队征兵时间降低2.0%" };
yield return new GeneralDefinition("s1_100642","关索",Homeland.Han,4,97,"月偃蛮平","关索·蜀·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100642.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="月偃蛮平", nativeSkillText="对敌军单体发动一次攻击（伤害率190.0%），并使其陷入犹豫状态，持续2回合-3回合", defense=81, strategy=70, speed=72, cost=3, attackGrowth=1.4, defenseGrowth=1.17, strategyGrowth=0.63, speedGrowth=0.85, siege=2, siegeGrowth=0.13, attackDistance=2, biography="【演】《三国演义》中的虚构人物，关羽三子，荆州失陷后逃难至鲍家庄养伤，后回归蜀国，并随诸葛亮南征，留下众多传说遗迹。明《花关索传》曾记载其与妻鲍三娘守葭萌关，《花关索》中提及其认父途中与王悦、王桃比武并迎娶二女；京剧《化外奇缘》则记载其在南征途中与孟获之女花鬘相爱结为夫妻。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="平蛮守南", policyText="可担任主城参军，令所属部队骑兵武将征兵资源消耗降低6.0%" };
yield return new GeneralDefinition("s1_100134","严颜",Homeland.Han,4,83,"蜀中老将","严颜·蜀·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="弓", sourceUrl="https://stzb.163.com/herolist/100134.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="蜀中老将", nativeSkillText="使我军全体攻击属性提高30.0，持续2回合", defense=73, strategy=54, speed=37, cost=2.5, attackGrowth=1.2, defenseGrowth=0.97, strategyGrowth=0.45, speedGrowth=0.4, siege=12, siegeGrowth=0.69, attackDistance=3, biography="【史】东汉末年武将，初为刘璋部下，担任巴郡太守。建安十九年，刘备进攻江州，严颜战败被俘，张飞对严颜说：“大军至，何以不降而敢拒战？”，严颜回答说：“卿等无状，侵夺我州，我州但有断头将军，无降将军也！”，张飞生气，命左右将严颜牵去砍头，严颜表情不变地说：“砍头便砍头，何为怒邪！”张飞敬佩严颜的勇气，遂释放严颜并以严颜为宾客，之后的事迹不在正史中出现。\n【演】在《三国演义》中，严颜在刘备攻取成都，径取汉川中登场。擅使硬弓和大刀，有万夫莫敌之勇。据守巴郡，与张飞交战，后为张飞用计俘虏。张飞质问：“大将在这里，为什么不投降，而敢率军拒敌？”颜宁死不屈，张飞壮而释之，引为上宾，严颜感概张飞的恩义而归降。", advancedTroops="长弓兵 、弩兵", combination="老当益壮(成员:黄忠(蜀)、黄盖(吴)、严颜(蜀),加成属性:防御、攻城)", policyName="断首何惧", policyText="可担任戍城参军，令所属部队蜀阵营武将体力上限增加15" };
yield return new GeneralDefinition("s1_100334","黄权",Homeland.Han,4,56,"安途若素","黄权·蜀·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100334.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="安途若素", nativeSkillText="以进行策略攻击时伤害下降30.0%为代价，使自身防御增加20.0，受到策略攻击时的伤害下降20.0%", defense=88, strategy=78, speed=27, cost=2.5, attackGrowth=0.54, defenseGrowth=1.28, strategyGrowth=0.84, speedGrowth=0.29, siege=14, siegeGrowth=1.01, attackDistance=2, biography="【史】原为刘璋部将，因劝谏刘璋勿引刘备入蜀，而为刘璋所疏远。刘璋战败，才降刘备。刘备称帝，将征伐东吴，黄权劝谏而不纳。刘备伐吴败还，而归途隔绝，黄权不得归，无奈之下率部降魏。\n【演】在《三国演义》中，黄权生平与正史大体相当，而在黄权归降的描写上略有不同。刘璋战败，刘备平定益州后，黄权闭门不降，刘备于是亲自前往请他，黄权才归降。", advancedTroops="重步兵、长枪兵", combination="", policyName="快士局量", policyText="令势力四项资源产量均提高1000" };
yield return new GeneralDefinition("s1_100069","庞统",Homeland.Han,4,59,"索命连环","庞统·蜀·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100069.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="索命连环", nativeSkillText="移除敌军单体的有益效果，使其受到策略攻击时的伤害提高34.0%（受谋略属性影响），并陷入妖术诅咒，每回合有80.0%的几率损失较多兵力（伤害率145.0%，受谋略属性影响），持续2回合", defense=71, strategy=98, speed=23, cost=2.5, attackGrowth=0.71, defenseGrowth=0.85, strategyGrowth=1.42, speedGrowth=0.25, siege=18, siegeGrowth=1.15, attackDistance=2, biography="【史】号凤雏，刘备帐下重要谋士，与诸葛亮同拜为军师中郎将。与刘备一同入川，于刘备与刘璋决裂之际，献上上中下三条计策，刘备用其中计。进围雒县时，庞统率众攻城，不幸中流矢而亡，年仅三十六岁。后来庞统所葬之处遂名为落凤坡。\n【演】被称为凤雏，与诸葛亮齐名。赤壁之战时，庞统避乱江东，鲁肃将其荐于周瑜，入曹营献连环计，助周瑜大败曹军。周瑜死后，诸葛亮前往吊孝，因而得见庞统。当时鲁肃亦引荐庞统给孙权，但因其外貌丑陋，而不被起用。庞统于是投靠刘备，但亦因其貌丑陋而不被重用。\n庞统到任后，不理政事，于是刘备遣张飞前往问责，张飞因赏识庞统之才，遂拜其为副军师中郎将，与诸葛亮共赞方略，教练军士。后庞统随刘备取蜀，设计斩杨怀、高沛，得涪水关。攻雒城时，因疑诸葛亮欲争功，而不听从劝阻，进至落凤坡，中张任埋伏，为乱箭射死。", advancedTroops="重步兵、长枪兵", combination="蜀之智(成员:徐庶(蜀)、诸葛亮(蜀)、庞统(蜀)、法正(蜀),加成属性:谋略)", policyName="密献三计", policyText="可担任戍城参军，令该戍城待命部队征兵时间降低5.0%，若戍城处于益州境内，则征兵资源消耗额外降低5.0%" };
yield return new GeneralDefinition("s1_100066","魏延",Homeland.Han,4,93,"傲将奇兵","魏延·蜀·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100066.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="傲将奇兵", nativeSkillText="普通攻击后，对攻击目标再次发动猛攻（伤害率230.0%），此攻击有几率会引起自身一定兵力的损耗", defense=85, strategy=66, speed=32, cost=2.5, attackGrowth=1.12, defenseGrowth=1.02, strategyGrowth=0.55, speedGrowth=0.35, siege=16, siegeGrowth=1.03, attackDistance=1, biography="【史】刘备入川时魏延因数有战功被任命为牙门将军，刘备攻下汉中后又将其破格提拔为镇远将军，领汉中太守，镇守汉中，成为独当一方的大将。魏延镇守汉中近十年，之后又屡次随诸葛亮北伐，功绩显著。期间魏延多次请诸葛亮给他统领一万兵，另走一路攻关中，最后与诸葛亮会师于潼关，如同韩信的例子，但诸葛亮一直不许，因而认为自己无法完全发挥才能，心怀不满。\n与长史杨仪不和，诸葛亮死后，两人矛盾激化，相互争权，魏延败逃，为马岱所追斩，并被夷灭三族。\n【演】在《三国演义》中，刘备率军入蜀，魏延随军前往。刘备逝世后，魏延随诸葛亮平定“南蛮王”孟获的叛乱。于诸葛亮北伐时献“子午谷奇谋”之策，但未被诸葛亮采纳；因此在奉命进攻箕谷时无视诸葛亮的军令，险些败北。于诸葛亮向天祈祷延命时进帐报告敌军入侵的消息，不慎碰倒主灯，导致诸葛亮的祈祷失败。\n诸葛亮临终前遗命杨仪统兵，魏延对此不满，于诸葛亮病逝后率军反攻杨仪，而杨仪则根据诸葛亮的遗计挑衅魏延，魏延最终被马岱所诛。", advancedTroops="重步兵、长枪兵", combination="", policyName="趋道为奇", policyText="可担任军事设施参军，令该军事设施补给范围内己方领地（不含战场与守军城区）耐久上限提升30" };
yield return new GeneralDefinition("s1_100326","夏侯月姬",Homeland.Han,4,85,"行樵偶遇","夏侯月姬·蜀·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100326.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="行樵偶遇", nativeSkillText="普通攻击后，对攻击目标再次发动攻击（伤害率50.0%），并使友军单体发动主动战法或追击战法的伤害提高21.0%（受攻击属性影响），持续2回合", defense=77, strategy=70, speed=80, cost=2.5, attackGrowth=1.13, defenseGrowth=0.93, strategyGrowth=0.76, speedGrowth=1.15, siege=10, siegeGrowth=0.5, attackDistance=2, biography="【史】张飞之妻、后主敬哀皇后之母、魏夏侯渊之弟女。父早亡，时兖、豫大乱，伯父渊以饥乏，弃其幼子，而活亡之。建安五年，时年十三四，在本郡，出行樵采，为张飞所得。飞知其良家女，遂以为妻，产息女，为刘禅皇后。渊之初亡，飞妻请而葬之。", advancedTroops="重骑兵、轻骑兵", combination="", policyName="采桑结缘", policyText="可担任主城参军，令所属部队蜀阵营武将征兵时间降低3.0%" };
yield return new GeneralDefinition("s1_100139","马岱",Homeland.Han,4,86,"借刀斩叛","马岱·蜀·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100139.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="借刀斩叛", nativeSkillText="每回合有25.0%的几率对敌军单体发动一次猛攻（伤害率300.0%），但此后将无法再发动主动战法，持续1回合", defense=81, strategy=72, speed=77, cost=2.5, attackGrowth=1.25, defenseGrowth=1.07, strategyGrowth=0.69, speedGrowth=0.83, siege=5, siegeGrowth=0.29, attackDistance=2, biography="【史】三国时期蜀汉将领，马超的从弟。早年追随马超大战曹操，反攻陇上，围攻成都，汉中之战等。后在诸葛亮病逝后受杨仪派遣斩了蜀将魏延。曾率领军队出师北伐，被魏将牛金击败而退还。官至平北将军，陈仓侯。\n【演】在《三国演义》中，马岱初次登场随马腾入许昌。后来马腾和其余诸子尽皆被害，马岱乔装逃出。马超起兵，马岱随之周旋。曾在潼关前打败钟繇。建安十九年，马岱随马超救援刘璋，曾与张飞大战十余合败北，旋即随马超归降刘备。刘禅登基后，跟随丞相诸葛亮南征孟获和北伐曹魏。马岱久经沙场、多负辛劳，作战冷静而勇猛，深得诸葛亮信任。诸葛亮临终授命于马岱，袭斩魏延。", advancedTroops="重骑兵、轻骑兵", combination="驰马西凉(成员:马腾(群)、马超(蜀)、马岱(蜀)、马云禄(蜀)、马超(群),加成属性:速度、攻心)", policyName="久经沙场", policyText="可担任军事设施参军，令该军事设施视野增加1，同时耐久上限提高20" };
yield return new GeneralDefinition("s1_100331","霍弋",Homeland.Han,4,77,"南中平蛮","霍弋·蜀·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100331.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="南中平蛮", nativeSkillText="对敌军单体发动攻击使其动摇，每回合产生逃兵（伤害率135.0%），持续2回合，在此期间，其防御会下降25.0", defense=83, strategy=64, speed=32, cost=2, attackGrowth=0.77, defenseGrowth=1.02, strategyGrowth=0.57, speedGrowth=0.32, siege=17, siegeGrowth=1.02, attackDistance=2, biography="【史】三国蜀汉至西晋初时将领，霍峻之子。尽言规谏刘禅，甚为得体。后永昌郡蛮夷作乱，刘禅以霍弋领永昌太守，率军讨伐，斩其豪帅。邓艾偷袭阴平，霍弋想率军救援成都，但刘禅以成都已有准备，不准，后刘禅投降，霍弋在得知司马氏善待刘禅后，才率领南中六郡投降。\n【演】初为蜀建宁太守，弋闻成都不守，素服望西大哭三日。诸将皆劝速降，弋不从。后弋探听得后主受封，遂率部下军士来降。", advancedTroops="重步兵、长枪兵", combination="", policyName="世戍南中", policyText="可担任戍城参军，令所属部队步兵武将体力上限增加10" };
yield return new GeneralDefinition("s1_100329","敬哀皇后",Homeland.Han,4,52,"默守贤义","敬哀皇后·蜀·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100329.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="默守贤义", nativeSkillText="使我军群体以无法恢复兵力为代价，受到攻击或策略攻击时的伤害降低45.0%（受谋略属性影响），持续2回合", defense=85, strategy=82, speed=34, cost=2, attackGrowth=0.57, defenseGrowth=0.95, strategyGrowth=0.91, speedGrowth=0.34, siege=18, siegeGrowth=1.08, attackDistance=1, biography="【史】张飞长女，蜀汉后主刘禅第一任皇后。221年作为太子刘禅的妃子入宫；223年被立为皇后。237年逝世，其妹成为刘禅之皇后。她通常被称为敬哀皇后，其妹则被称为张皇后。\n【演】在《三国演义》中，敬哀皇后为人贤惠，十七岁时，诸葛亮上言后主刘禅立其为正宫皇后。", advancedTroops="重步兵、长枪兵", combination="", policyName="贤良淑德", policyText="令势力木材资源上限提高200000" };
yield return new GeneralDefinition("s1_100063","甘皇后",Homeland.Han,4,35,"昭烈神思","甘皇后·蜀·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100063.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="昭烈神思", nativeSkillText="战斗开始后前3回合，使我军群体进行策略攻击时的伤害提高22.0%（受谋略属性影响），每回合有80.0%的几率能优先行动", defense=52, strategy=86, speed=21, cost=2, attackGrowth=0.39, defenseGrowth=0.57, strategyGrowth=0.96, speedGrowth=0.24, siege=15, siegeGrowth=0.9, attackDistance=2, biography="【史】刘备之妻，刘禅之母。刘备因早年多次丧偶，甘夫人常代理主持家事。甘夫人随刘备到荆州时，生刘备长子刘禅，后来去世，葬于南郡。刘备称帝后，追谥其为“皇思夫人”。刘禅即位后追谥其为“昭烈皇后”。\n【演】刘备住在小沛时，娶甘氏为妻，与麋夫人俱为刘备夫人。后来刘备兵败，投袁绍。关羽保二夫人暂投曹操。关羽寻得刘备下落，带二夫人奔之。甘夫人随刘备至荆州，生下刘禅。后曹操军至，刘备逃走，甘夫人及刘禅走失，为赵云所救。赤壁之战结束后不久，甘夫人去世，周瑜遂定下美人计。", advancedTroops="长枪兵、禁卫", combination="母仪天下(成员:吴夫人(吴)、丁夫人(魏)、甘皇后(蜀)、何太后(汉)、郭皇后(魏)、卫子夫(汉)、阴丽华(汉),加成属性:谋略、速度)", policyName="淑慎其身", policyText="可担任分城参军，令该分城城内设施的建造和升级铁矿消耗降低20.0%" };
yield return new GeneralDefinition("s1_100064","麋夫人",Homeland.Han,4,65,"存嗣流愿","麋夫人·蜀·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="弓", sourceUrl="https://stzb.163.com/herolist/100064.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="存嗣流愿", nativeSkillText="以一定兵力为代价，使友军全体在受到下1次攻击时进入规避状态，可以免疫伤害", defense=48, strategy=80, speed=41, cost=1.5, attackGrowth=0.68, defenseGrowth=0.51, strategyGrowth=0.84, speedGrowth=0.43, siege=11, siegeGrowth=0.62, attackDistance=4, biography="【史】刘备之妻，麋竺之妹。与关羽一起被曹操俘虏后事迹不详。\n【演】在《三国演义》中写作“糜夫人”，刘备兵败长坂坡之时，她怀抱年仅两岁的刘禅在乱军中走散，后来被赵云发现。但她因为赵云只有一匹马而不肯上马，最终将阿斗托付给赵云后投井而亡。", advancedTroops="长弓兵 、弩兵", combination="", policyName="彤史生光", policyText="令势力税收提高2000" };
yield return new GeneralDefinition("s1_100088","孙坚",Homeland.Han,4,89,"古锭之锋","孙坚·吴·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="骑", sourceUrl="https://stzb.163.com/herolist/100088.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="古锭之锋", nativeSkillText="强化自身造成的伤害并发动攻击，使敌军单体陷入动摇状态，每回合产生逃兵（伤害率110.0%），持续2回合", defense=93, strategy=67, speed=86, cost=3, attackGrowth=1.29, defenseGrowth=1.09, strategyGrowth=0.61, speedGrowth=1.13, siege=4, siegeGrowth=0.25, attackDistance=1, biography="【史】县吏出身，因勇敢又有谋略被官府赏识，提拔为军官。曾参与讨伐黄巾军的战役以及讨伐董卓的战役。后与刘表作战时阵亡。孙坚的儿子孙策、孙权后来创建了东吴政权。\n【演】在《三国演义》中，孙坚由于征讨黄巾有功，被封为长沙太守。在董卓乱政期间，孙坚作为诸侯联军的先锋，表现得十分活跃，但因袁术存在私心，拒不发粮，而被董卓将华雄击败。后来董卓迁都长安，孙坚进驻洛阳，意外发现传国玉玺，并藏匿返回。不料事情泄漏，与袁绍、刘表结仇。不久，孙坚在与刘表手下黄祖的交战中，中埋伏而死。", advancedTroops="重骑兵、轻骑兵", combination="枭雄父子(成员:孙策(吴)、孙坚(吴)、孙权(吴),加成属性:攻击)", policyName="将星兵威", policyText="可担任主城参军，令所属部队吴阵营武将征兵资源消耗降低15.0%" };
yield return new GeneralDefinition("s1_100426","凌统",Homeland.Han,4,82,"国士","凌统·吴·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100426.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="国士", nativeSkillText="战斗开始后前4回合，使自身造成的伤害无视规避，每回合有100.0%的几率进入洞察状态，免疫混乱、犹豫、怯战、暴走和挑衅效果", defense=85, strategy=41, speed=49, cost=2.5, attackGrowth=1.09, defenseGrowth=1.13, strategyGrowth=0.34, speedGrowth=0.59, siege=10, siegeGrowth=0.65, attackDistance=2, biography="【史】吴国名将。凌操之子，少有名盛，为人有国士之风，多次战役中表现出色，官至偏将军。被陈寿盛赞为“江表之虎臣”。\n【演】在《三国演义》中，凌统因父亲凌操被甘宁所害而一直仇视甘宁，但在濡须口与乐进交战时得甘宁所救，从此便尽释前嫌，与甘宁结为生死之交。其他事迹与正史大致相同。", advancedTroops="长弓兵 、弩兵", combination="", policyName="亲贤下士", policyText="可担任主城参军，令所属部队征兵木材、铁矿消耗均降低5.0%" };
yield return new GeneralDefinition("s1_100087","徐盛",Homeland.Han,4,83,"炬石","徐盛·吴·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100087.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="炬石", nativeSkillText="对敌军群体发动一次攻击（伤害率130.0%），使其防御属性降低22.0（受谋略属性影响），并陷入燃烧状态，每回有75.0%的几率损失一定兵力（伤害率108.0%，受谋略属性影响），持续2回合", defense=76, strategy=73, speed=57, cost=2.5, attackGrowth=1.1, defenseGrowth=1.01, strategyGrowth=0.7, speedGrowth=0.69, siege=11, siegeGrowth=0.71, attackDistance=4, biography="【史】三国时吴国名将。早年徐盛抗击黄祖，因功升为中郎将。刘备伐吴时，徐盛跟随陆逊攻下蜀军多处屯营；曹休伐吴时，徐盛在形势不利的情况下以少抗多，成功防御。因前后战功，徐盛先后升任建武将军、安东将军，任庐江太守。后来，曹丕大举攻吴，吴国依徐盛的建议在建业外围筑上围墙，曹丕被迫退走。黄武年间，徐盛病逝，被陈寿盛赞为“江表之虎臣”。其官爵由儿子徐楷继承。\n【演】在《三国演义》中，无论前期或者后期，徐盛与丁奉都是一起登场和破敌。在曹丕224年伐吴，徐盛与丁奉一起率军迎敌，偃旗息鼓地在广陵城内设芦苇草人，装作布满士兵的空城。曹丕在龙舟上闻曹真回报城里没有一人，认为是诡计打算下舟查探，但心里拿不定注意询问刘晔，但刘晔也跟曹丕一样看法。当夜，曹丕军举起火把，灯火通明，反而江南没有半点光。曹丕认为是诡计便撤退，而淮河布满事先浸满鱼油的芦苇，徐盛把芦苇点燃，大火连横。", advancedTroops="长弓兵 、弩兵", combination="纵横江海(成员:甘宁(吴)、徐盛(吴)、周泰(吴),加成属性:速度、防御)", policyName="雄豪致果", policyText="可担任主城参军，令所属部队弓兵武将征兵木材消耗降低15.0%" };
yield return new GeneralDefinition("s1_100092","陆逊",Homeland.Han,4,68,"奇计迭出","陆逊·吴·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100092.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="奇计迭出", nativeSkillText="1回合准备，对敌军全体发动策略攻击（伤害率92.0%，受谋略属性影响），有50.0%的几率对其再次发动策略攻击（伤害率133.0%，受谋略属性影响），并使其陷入燃烧状态，每回合都有等同于上述的几率额外损失一定兵力（伤害率76.0%，受谋略属性影响）持续2回合", defense=96, strategy=99, speed=25, cost=2.5, attackGrowth=0.73, defenseGrowth=1.03, strategyGrowth=1.43, speedGrowth=0.27, siege=19, siegeGrowth=1.37, attackDistance=2, biography="【史】三国时期吴国政治家、军事家。建安二十四年（219年），陆逊参与袭取荆州。章武二年（222年），孙权以陆逊为大都督，在夷陵火烧连营击败刘备，一战成名。黄武七年（228年），陆逊取得石亭之战的胜利。黄龙元年（229年），孙权称帝后，以陆逊为上大将军、辅佐太子孙登并掌管陪都武昌事宜，后卷入立嗣之争。\n赤乌七年（244年）拜为丞相，总领三公事务，领武昌事。陆逊跟随孙权四十余年，统领吴国军政十余年，深得孙权器重。深谋远虑，忠诚耿直。一生出将入相，被赞为“社稷之臣”。\n【演】在《三国演义》中，称其“身长八尺，面如美玉，体如凝酥”。孙权统事后，陆逊投奔入孙权门下。陆逊、董袭作为第五队参与了赤壁之战。合肥之战时陆逊董袭又救出重伤的太史慈；樊城之战前吕蒙因为想不出对付关羽的办法装病躲避。陆逊向孙权进言猜测是诈病，后又献夺荆州计谋。孙权遂以陆逊代吕蒙守陆口。后孙权力排众议，拜陆逊为大都督。", advancedTroops="弩兵、重步兵", combination="东吴大都督(成员:周瑜(吴)、鲁肃(吴)、陆逊(吴)、吕蒙(吴),加成属性:谋略、速度)、吴之智(成员:张昭(吴)、鲁肃(吴)、陆逊(吴),加成属性:谋略)", policyName="智变规虑", policyText="可担任军事设施参军，令该军事设施的补给范围增加1，所属己方部队在补给范围内行军速度提高20.0%" };
yield return new GeneralDefinition("s1_100243","孙桓",Homeland.Han,4,85,"困守","孙桓·吴·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100243.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="困守", nativeSkillText="因处于被围困状态而无法恢复兵力，自身发动攻击和策略攻击所造成的伤害提高25.0%", defense=85, strategy=83, speed=43, cost=2, attackGrowth=0.85, defenseGrowth=0.95, strategyGrowth=0.83, speedGrowth=0.43, siege=10, siegeGrowth=0.6, attackDistance=3, biography="【史】吴国将领。其人仪容端正，器怀聪明，博学强记，能论议应对，孙权常称其为“宗室颜渊”。跟随陆逊抗击进攻东吴的刘备时。刘备率领众多兵众进攻，满山都是蜀军，孙桓奋战，与陆逊等协力击破蜀军。刘备兵败逃走，孙桓截击，“斩上夔道，扼要径”，差点生擒刘备。刘备忿恨地感叹：“吾昔初至京城，（孙）桓尚小儿，而今迫孤至此也！”\n【演】在《三国演义》中，孙桓的事迹基本与正史相符。", advancedTroops="长弓兵 、重步兵", combination="", policyName="宗室颜渊", policyText="可担任主城参军，令所属部队吴阵营武将征兵木材消耗降低15.0%" };
yield return new GeneralDefinition("s1_100159","蒋钦",Homeland.Han,4,82,"水泽伏击","蒋钦·吴·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100159.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="水泽伏击", nativeSkillText="普通攻击后，对攻击目标发动出其不意的伏击（伤害率120.0%），此攻击有50.0%的几率再度触发一次", defense=67, strategy=74, speed=42, cost=2, attackGrowth=1.1, defenseGrowth=0.67, strategyGrowth=0.57, speedGrowth=0.42, siege=11, siegeGrowth=0.59, attackDistance=3, biography="【史】汉末东吴名将，其人贵守约，性豁达。早年随孙策平定丹阳、吴郡、会稽和豫章四郡。平盗贼，迁西部都尉。讨会稽贼吕合、秦狼等，徙讨越中郎将。又与贺齐并力讨平黟贼。从征合肥，因功迁荡寇将军，被陈寿盛赞为“江表之虎臣”。孙权讨伐关羽时，蒋钦率领水军入沔水。回军途中病逝。\n【演】在《三国演义》中，蒋钦是擅长弓术的将领。与周泰原为江贼，孙策下江东自立门户时，和周泰一起率众投靠。孙策攻刘繇，并引出城中麾下的陈横、薛礼、张英三名将领，陈横被蒋钦一箭射死。曾在赤壁之战与周泰，还有擅使长枪的韩当率领水军在三江口踏江破敌。南郡之战请命攻曹仁，但却被曹仁和牛金击退，周瑜打算怒斩蒋钦，众将求情劝免，其后故事与《三国志》基本相同。", advancedTroops="长弓兵 、弩兵", combination="东吴老将(成员:程普(吴)、黄盖(吴)、蒋钦(吴)、韩当(吴),加成属性:攻击、防御)", policyName="属宣其力", policyText="可担任戍城参军，令所属部队吴阵营武将体力上限增加15" };
yield return new GeneralDefinition("s1_100641","朱然",Homeland.Han,4,75,"名震敌国","朱然·吴·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100641.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="名震敌国", nativeSkillText="战斗开始后，使自己与随机友军单体在第1、3、5回合自身行动前，分别提高攻击属性30.0，防御属性40.0，谋略属性50.0", defense=80, strategy=72, speed=28, cost=2, attackGrowth=0.66, defenseGrowth=1.08, strategyGrowth=0.89, speedGrowth=0.28, siege=12, siegeGrowth=0.64, attackDistance=2, biography="【史】吴国名将，朱治之甥及养子。于夷陵之战中与陆逊大破刘备；并面对曹真，张郃等魏将的围困，坚守江陵六月之久，名震敌国。官至左大司马，右军师，当阳侯。\n【演】演义中，朱然协助潘璋擒住关羽父子。后与孙桓共同抵抗刘备大军，参加夷陵之战。在追击刘备途中，被前来接应的赵云所诛。", advancedTroops="重步兵、长枪兵", combination="", policyName="胆守有余", policyText="令势力位于扬州的城邑耐久上限提高250" };
yield return new GeneralDefinition("s1_100091","吴夫人",Homeland.Han,4,49,"国太威仪","吴夫人·吴·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="骑", sourceUrl="https://stzb.163.com/herolist/100091.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="国太威仪", nativeSkillText="战斗开始后前5回合，使我军群体的谋略属性提高34.0（受谋略属性影响），此效果结束后，使其进行策略攻击时的伤害提高28.0%（受谋略属性影响），持续直到战斗结束", defense=66, strategy=80, speed=87, cost=1.5, attackGrowth=0.41, defenseGrowth=0.62, strategyGrowth=0.84, speedGrowth=0.91, siege=2, siegeGrowth=0.1, attackDistance=2, biography="【史】孙坚夫人。孙策、孙权之母。本姓吴，早丧父母，与其弟吴景居处。孙坚闻其才貌，娶而为妻，生四男一女。孙策、孙权分别执政时，吴夫人皆助治军国大事，甚有补益。临终引见张昭等，嘱以后事。死后与孙坚合葬高陵。\n【演】在《三国演义》中，被称为吴太夫人。其次子孙权自立为吴国皇帝后，她被追尊为皇后。并且演义中虚构其妹继为国太，在孙刘联姻一事上起主导作用。", advancedTroops="重骑兵、轻骑兵", combination="母仪天下(成员:卫子夫(汉)、阴丽华(汉)、吴夫人(吴)、郭皇后(魏)、丁夫人(魏)、甘皇后(蜀)、何太后(汉),加成属性:谋略、速度)", policyName="辅子助治", policyText="担任主城或分城参军时，屯田时可获得铁矿资源9000" };
yield return new GeneralDefinition("s1_102002","夏侯渊",Homeland.Han,5,91,"定军绝战","夏侯渊·魏·骑·5星·SP。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100435.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="定军绝战", nativeSkillText="对敌军单体发动一次攻击（伤害率140.0%）", defense=90, strategy=66, speed=100, cost=3, attackGrowth=2, defenseGrowth=1.85, strategyGrowth=0.76, speedGrowth=2.04, siege=10, siegeGrowth=0.69, attackDistance=3, biography="【史】东汉末年名将，擅长千里奔袭作战，官至征西将军，封博昌亭侯。初期随曹操征伐，官渡之战为曹操督运粮草，又督诸将先后平定昌豨、徐和、雷绪、商曜等叛乱。后率军驻凉州，逐马超、破韩遂、灭宋建、横扫羌、氐，虎步关右。张鲁降曹操后夏侯渊留守汉中，与刘备相拒逾年，于定军山被刘备部将黄忠所袭，战死，谥曰愍侯。\n【演】在《三国演义》中，夏侯渊是夏侯婴之后、大将军惇族弟。自曹操陈留起兵起，便跟随征伐，历任陈留、颍川太守。官渡之战后，夏侯渊负责粮草补给，保证了曹操平定北方。而后夏侯渊又率兵四处征讨叛乱，破昌豨、徐和、雷绪、商曜等，战功卓著。而后夏侯渊督张郃、徐晃等留守汉中，与前来取汉中的刘备大军交战，为刘备将黄忠所袭，不幸战死。谥曰愍侯。魏齐王正始四年从祀曹操庙庭。", advancedTroops="轻骑兵、弓骑兵", combination="魏武强将(成员:夏侯渊(魏)、曹洪(魏)、夏侯惇(魏)、曹仁(魏),加成属性:攻击、速度)", policyName="一马当先", policyText="可担任戍城参军，令所属部队骑兵武将行军速度提高40.0" };
yield return new GeneralDefinition("s1_102005","甄洛",Homeland.Han,5,65,"幽兰洛神","甄洛·群·弓·5星·SP。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100015.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="幽兰洛神", nativeSkillText="恢复友军单体一定兵力（恢复率105.0%，受谋略属性影响），并使其受到普通攻击的伤害降低33.0%（受谋略属性影响）", defense=75, strategy=90, speed=42, cost=2, attackGrowth=1.31, defenseGrowth=1.29, strategyGrowth=0.88, speedGrowth=0.85, siege=10, siegeGrowth=0.94, attackDistance=3, biography="【史】魏文帝曹丕的妻子，魏明帝曹叡的生母。黄初二年（221年），曹丕称帝以后甄夫人被赐死，曹叡即位后追尊甄氏为文昭皇后。\n【演】在《三国演义》中，甄氏生平与正史大体相当。初期嫁与袁绍次子袁熙，袁熙带兵出外征战，留下甄氏独身照顾婆婆，袁氏败亡后，曹操之子曹丕见其美艳动人，便纳为己有。黄初年间，魏文帝曹丕登基后，郭贵妃以巫蛊之术陷害甄氏。文帝曹丕大怒，将甄氏赐死。", advancedTroops="长弓兵 、弩兵", combination="", policyName="济寒赈贫", policyText="可担任主城或分城参军，令该城邑资源产量提高30.0%，但税收降低20.0%" };
yield return new GeneralDefinition("s1_102011","蔡文姬",Homeland.Han,5,61,"胡笳离愁","蔡文姬·汉·步·5星·SP。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="步", sourceUrl="https://stzb.163.com/herolist/100004.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="胡笳离愁", nativeSkillText="恢复我军群体较多兵力（恢复率157.0%，受谋略属性影响），并使其进入休整状态，每回合再度恢复大量兵力（恢复率206.0%，受谋略属性影响），持续1回合", defense=82, strategy=90, speed=45, cost=2.5, attackGrowth=0.89, defenseGrowth=0.99, strategyGrowth=1.53, speedGrowth=0.54, siege=16, siegeGrowth=1.14, attackDistance=2, biography="【史】东汉末才女，博学多才且精通音律。匈奴入侵时，被匈奴掳走。十二年后，曹操统一北方，用重金将蔡文姬赎回，并将其嫁给董祀。", advancedTroops="重步兵、禁卫", combination="", policyName="作金石声", policyText="令势力铁矿产量提高4800，部队位于城邑待命时，体力恢复速度提高10.0%" };
yield return new GeneralDefinition("s1_102012","姜维",Homeland.Han,5,92,"列营守险","姜维·蜀·弓·5星·SP。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="弓", sourceUrl="https://stzb.163.com/herolist/100074.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="列营守险", nativeSkillText="使我军全体攻击、防御、速度、谋略属性提高29.2（受谋略属性影响），持续2回合，同时友军全体受到下3次伤害时有50.0%几率进入规避状态，免疫该次伤害。若自身士气高昂时，规避状态的目标变为我军全体使我军全体攻击、防御、速度、谋略属性提高29.2（受谋略属性影响），持续2回合，同时我军全体受到下3次伤害时有50.0%几率进入规避状态，免疫该次伤害", defense=89, strategy=91, speed=61, cost=2.5, attackGrowth=1.61, defenseGrowth=1.68, strategyGrowth=1.21, speedGrowth=0.82, siege=9, siegeGrowth=0.65, attackDistance=3, biography="【史】三国时蜀汉名将，官至大将军。曾为魏中郎将，诸葛亮北伐时，姜维被怀疑有异心，姜维不得已投降蜀汉。因他忠勤时事、思虑精密、敏于军事、既有胆义，又兼心存汉室，故深得诸葛亮器重。诸葛亮去世后姜维在蜀汉开始崭露头角，费祎死后姜维开始独掌军权，继续率领蜀汉军队北伐曹魏。\n后因蜀中大臣多反对北伐，而宦官黄皓弄权，姜维只得在沓中屯田避祸。后司马昭五道伐蜀，姜维据守剑阁，阻挡钟会大军，却被邓艾从阴平偷袭成都，刘禅投降。后姜维假意投降魏将钟会，打算利用钟会反叛曹魏以实现恢复汉室的愿望，但最终反叛失败，与钟会一同被魏军所害。\n【演】在《三国演义》中，姜维生平与正史相似。在描写姜维降蜀时，在天水中识破设伏的赵云，并劫了诸葛亮的寨。诸葛亮视其为接班人，用计令夏侯楙和马遵误以姜维降蜀，最终使得姜维走投无路而降蜀。", advancedTroops="长弓兵 、弩兵", combination="", policyName="武侯遗志", policyText="可担任主城、分城或戍城参军，令该城邑视野增加2，同时预警时间增加600秒，城区耐久上限提高300" };
yield return new GeneralDefinition("s1_102014","张角",Homeland.Han,5,21,"黄天当立","张角·群·骑·5星·SP。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100008.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="黄天当立", nativeSkillText="1回合准备，使敌军全体陷入妖术诅咒，每回合损失一定兵力（伤害率180.0%，受谋略属性影响），持续2回合；敌军受到该战法的妖术伤害时，张角恢复一定兵力（恢复率60.0%，受谋略属性影响）", defense=67, strategy=93, speed=85, cost=3, attackGrowth=0.32, defenseGrowth=1.01, strategyGrowth=2.36, speedGrowth=1.72, siege=3, siegeGrowth=0.27, attackDistance=2, biography="【史】东汉末农民起义领袖。汉灵帝时期在各地传播“太平道”，发展部众至几十万，遍及青、徐、幽、冀、荆、扬、兖、豫八州。184年二月，张角发动起义，打出了“苍天已死，黄天当立”的口号，矛头直指东汉政府，史称“黄巾起义”，影响遍及全国，极大地动摇了东汉政府的统治。同年十月，张角病死，不久其直接领导的黄巾军被镇压，但其后各地起义不断，最终导致东汉灭亡。\n【演】在《三国演义》中，张角原是个不第的秀才，在山中采药时遇南华老仙，得天书三卷，名为《太平要术》。张角依此书所传道术，开始散施符水，为人治病，徒众发展到数十万。张角遂起了夺取天下的野心，与兄弟张宝、张梁一起发兵起义，声势浩大，但最终被朝廷和各路豪杰镇压。张角病死，黄巾军主力随即覆灭，但仍有很多残党在各地活动。", advancedTroops="死士、轻骑兵", combination="苍天已死(成员:张角(群)、张梁(群)、张宝(群),加成属性:谋略、【黄天当立】发动率提高)", policyName="太平要术", policyText="令势力群阵营武将征兵时间降低7.5%，处于灾害范围内时额外降低7.5%" };
yield return new GeneralDefinition("s1_102017","周姬",Homeland.Han,5,25,"复誓业火","周姬·吴·步·5星·SP。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100032.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="复誓业火", nativeSkillText="使敌军群体受到策略攻击时的伤害提高16.0%（受谋略属性影响），持续2回合，并对其发动一次火攻（伤害率114.0%，受谋略属性影响），同时使其陷入燃烧状态，每回合损失一定兵力（伤害率114.0%，受谋略属性影响），持续1回合", defense=49, strategy=80, speed=35, cost=2, attackGrowth=0.3, defenseGrowth=0.99, strategyGrowth=1.62, speedGrowth=0.47, siege=15, siegeGrowth=1.2, attackDistance=3, biography="【史】周瑜之女，母疑为汉末美女小乔，兄长为周循和周胤。\n【演】在《三国演义》中，提及周瑜去世后留下二子一女，孙权对他们很关照。周瑜的女儿日后嫁给了太子。", advancedTroops="重步兵、禁卫", combination="", policyName="食租衣税", policyText="令势力税收提高4800" };
yield return new GeneralDefinition("s1_100710","嵇康",Homeland.Han,4,56,"广陵绝唱","嵇康·魏·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100710.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="广陵绝唱", nativeSkillText="为友军全体恢复一定兵力（恢复率172.0%，受谋略属性影响），并使随机友军单体士气提升5.0", defense=83, strategy=84, speed=36, cost=2.5, attackGrowth=0.54, defenseGrowth=1, strategyGrowth=1.43, speedGrowth=0.44, siege=20, siegeGrowth=1.14, attackDistance=2, biography="【史】“竹林七贤”之一，三国时期著名文学家、思想家、音乐家，官至中散大夫。嵇康激烈地抨击世俗规范，主张顺应自然，保全天性，积极推广服食养生理论，在当时具有极高的声望与影响力，后因司马昭忌惮其言论会影响到司马氏政权，于吕安案中被处死。嵇康死后，其思想主张在东晋与南朝备受推崇，成为了魏晋玄学的重要构成理论。嵇康著有《嵇康集》、《养生论》、《声无哀乐论》等，其作曲《广陵散》，给后人留下了广陵绝响的典故。", advancedTroops="重步兵、长枪兵", combination="竹林七贤(成员:阮籍(魏)、刘伶(晋)、嵇康(魏)、山涛(晋)、向秀(晋)、阮咸(晋)、王戎(晋),加成属性:谋略、规避)", policyName="归隐山林", policyText="令势力所有武将在未上阵时，体力恢复速度提升50.0%" };
yield return new GeneralDefinition("s1_100711","刘伶",Homeland.Han,4,34,"幕天席地","刘伶·晋·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="步", sourceUrl="https://stzb.163.com/herolist/100711.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="幕天席地", nativeSkillText="每回合自身行动时使敌军兵力最高单体下一次造成的伤害降低30.0%（受谋略属性影响），我军兵力最低单体下一次受到的伤害降低30.0%（受谋略属性影响）", defense=66, strategy=80, speed=39, cost=2.5, attackGrowth=0.33, defenseGrowth=0.63, strategyGrowth=1.36, speedGrowth=0.52, siege=23, siegeGrowth=1.49, attackDistance=2, biography="【史】魏晋名士，“竹林七贤”之一。沛国人，淡泊名利，沉默寡言，嗜酒。曾担任建威参军。泰始初年，因无为而治的对策而被朝中视为无用，因此遭到罢免。豁达机敏，曾著有《酒德颂》。后寿终正寝。", advancedTroops="重步兵、长枪兵", combination="竹林七贤(成员:阮籍(魏)、刘伶(晋)、嵇康(魏)、山涛(晋)、向秀(晋)、阮咸(晋)、王戎(晋),加成属性:谋略、规避)", policyName="无为罢仕", policyText="势力已解锁的常规政策中每有一个未施政，使所有资源产量提升150" };
yield return new GeneralDefinition("s1_100712","阮籍",Homeland.Han,4,67,"青白分明","阮籍·魏·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="步", sourceUrl="https://stzb.163.com/herolist/100712.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="青白分明", nativeSkillText="1回合准备，选择自身以外随机单体，若为敌军，则造成一次策略攻击（伤害率175.0%，受谋略属性影响），若为友军，则造成一次恢复（恢复率175.0%，受谋略属性影响），重复三次，每次目标独立判定", defense=80, strategy=82, speed=37, cost=2.5, attackGrowth=0.64, defenseGrowth=1.06, strategyGrowth=1.39, speedGrowth=0.54, siege=21, siegeGrowth=1.2, attackDistance=2, biography="【史】三国时期著名诗人。博览群书，精通音律，任性不羁，崇奉老庄之学。不拘礼教，时人多有非议。又与嵇康、山涛等七人为友，世称“竹林七贤”。阮籍志向高远，然囿于乱朝，常恐罹谤遇祸，故而不问世事。曾多次以病辞官，更示人以狂放酣醉之状，司马昭称其“至慎”。景元四年魏帝曹奂下诏加封司马昭，阮籍执笔作劝进表，言辞清丽，时人重之。同年冬卒，时年五十四。", advancedTroops="重步兵、长枪兵", combination="竹林七贤(成员:阮籍(魏)、刘伶(晋)、嵇康(魏)、山涛(晋)、向秀(晋)、阮咸(晋)、王戎(晋),加成属性:谋略、规避)", policyName="营人善酿", policyText="令势力所有部队维持所需消耗降低5.0%，且步兵征兵消耗降低2.0%" };
yield return new GeneralDefinition("s1_100713","山涛",Homeland.Han,4,65,"缮甲厉兵","山涛·晋·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="弓", sourceUrl="https://stzb.163.com/herolist/100713.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="缮甲厉兵", nativeSkillText="令友军全体免疫怯战效果，并使其攻击伤害提升12.0%（受到谋略属性影响），持续2回合", defense=75, strategy=83, speed=40, cost=2.5, attackGrowth=0.81, defenseGrowth=0.93, strategyGrowth=1.38, speedGrowth=0.5, siege=11, siegeGrowth=0.63, attackDistance=3, biography="【史】魏晋时期大臣，“竹林七贤”之一。幼年丧父，生活困苦。四十岁时，才担任郡主簿、功曹、上计掾。曾判断司马懿称病必有用意，便弃官而去，未到两年司马懿果然发动了高平陵之变。曾向司马昭谏言：“废长立少，违礼不祥。国之安危，恒必由之。”于是司马昭才定下司马炎为世子，司马炎亦因此亲自拜谢山涛。历任太子少傅、散骑常侍、侍中、光禄大夫等职，官至司徒。\n【演】在《三国演义》中，山涛仅登场一次，以“废长立幼，违礼不祥”为理由，劝阻司马昭想要立司马攸为继承人的想法。", advancedTroops="长弓兵 、弩兵", combination="竹林七贤(成员:山涛(晋)、阮籍(魏)、刘伶(晋)、嵇康(魏)、向秀(晋)、阮咸(晋)、王戎(晋),加成属性:谋略、规避)", policyName="山公启事", policyText="令势力所有部队在其所属建筑补给范围内出征战斗后恢复伤兵15.0%" };
yield return new GeneralDefinition("s1_100714","向秀",Homeland.Han,4,23,"推己及人","向秀·晋·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="步", sourceUrl="https://stzb.163.com/herolist/100714.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="推己及人", nativeSkillText="当友军全体受到伤害后，自身有100.0%概率进入洞察状态，持续1回合", defense=71, strategy=81, speed=28, cost=2, attackGrowth=0.48, defenseGrowth=0.91, strategyGrowth=1.25, speedGrowth=0.29, siege=15, siegeGrowth=0.8, attackDistance=2, biography="【史】“竹林七贤”之一，官至散骑常侍。主张本体论玄学，万物自生、自化的崇有论哲学观。原本隐居山阳，在嵇康、吕安去世后应召前往洛阳任官，但是在朝期间向秀只做官不做事，消极无为。著有《思旧赋》、《难嵇叔夜养生论》。", advancedTroops="重步兵、长枪兵", combination="竹林七贤(成员:向秀(晋)、山涛(晋)、阮籍(魏)、刘伶(晋)、嵇康(魏)、阮咸(晋)、王戎(晋),加成属性:谋略、规避)", policyName="备位充数", policyText="令部队维持的粮草消耗提升5.0%，势力税收提升2500" };
yield return new GeneralDefinition("s1_100715","阮咸",Homeland.Han,4,42,"神解音律","阮咸·晋·步·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="步", sourceUrl="https://stzb.163.com/herolist/100715.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="神解音律", nativeSkillText="令我军群体恢复一定兵力（恢复率80.0%，受谋略属性影响），并使我军群体谋略属性提高20.0，持续1回合", defense=71, strategy=80, speed=30, cost=2.5, attackGrowth=0.46, defenseGrowth=0.88, strategyGrowth=1.33, speedGrowth=0.33, siege=19, siegeGrowth=1.25, attackDistance=2, biography="【史】阮籍之侄，“竹林七贤”之一，官至始平太守，为人不拘常规，妙解音律，时人称之为“神解”，传说弦乐器“阮”便是阮咸改造发明的。阮咸嗜酒，曾留下与猪群共饮的轶事。阮咸最终以寿终，无著作传世。", advancedTroops="重步兵、长枪兵", combination="竹林七贤(成员:阮咸(晋)、向秀(晋)、山涛(晋)、阮籍(魏)、刘伶(晋)、嵇康(魏)、王戎(晋),加成属性:谋略、规避)", policyName="神解远扬", policyText="提升名望上限1200" };
yield return new GeneralDefinition("s1_100716","王戎",Homeland.Han,4,80,"卿卿我我","王戎·晋·骑·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="骑", sourceUrl="https://stzb.163.com/herolist/100716.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="卿卿我我", nativeSkillText="我方出战武将有女性武将时，战斗中，女性武将每回合行动时有30.0%几率恢复一定兵力（恢复率80.0%，受谋略属性影响），同时自身每回合有30.0%几率使自身受到的攻击伤害和策略伤害降低20.0%（受谋略属性影响)，持续1回合", defense=82, strategy=86, speed=82, cost=2.5, attackGrowth=0.96, defenseGrowth=0.98, strategyGrowth=1.43, speedGrowth=0.98, siege=4, siegeGrowth=0.33, attackDistance=2, biography="【史】魏晋名士，幽州刺史王雄之孙、凉州刺史王浑之子。与阮籍交好，“竹林七贤”之一。承袭父爵贞陵亭侯，被司马昭辟为掾属。钟会曾向王戎询问伐蜀的计谋，王戎言：“非成功难，保之难也。”次年钟会果然叛乱被杀。历任散骑常侍、河东太守、荆州刺史，后迁为豫州刺史，加封建威将军，受诏伐吴，进攻武昌，因功进封安丰侯。官至司徒。\n【演】在《三国演义》中，王戎登场时为建威将军，伐吴之战中负责武昌地区的作战。", advancedTroops="重骑兵、轻骑兵", combination="竹林七贤(成员:王戎(晋)、阮咸(晋)、山涛(晋)、嵇康(魏)、向秀(晋)、阮籍(魏)、刘伶(晋),加成属性:谋略、规避)", policyName="强本节用", policyText="令所属部队骑兵在野外征兵的铜币消耗降低10.0%" };
yield return new GeneralDefinition("s1_100717","司马攸",Homeland.Han,4,48,"明德至亲","司马攸·晋·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="弓", sourceUrl="https://stzb.163.com/herolist/100717.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="明德至亲", nativeSkillText="对友军全体发动以下两种效果的一种：攻击、谋略属性提升40.0，持续2回合；受到攻击和策略伤害降低30.0%，持续2回合", defense=57, strategy=87, speed=48, cost=2.5, attackGrowth=0.6, defenseGrowth=0.79, strategyGrowth=1.45, speedGrowth=0.6, siege=11, siegeGrowth=0.73, attackDistance=2, biography="【史】小字桃符，司马炎的胞弟，司马昭的次子，后过继给司马师。司马攸聪慧温和，颇具人望，备受司马懿器重。司马炎立晋后，司马攸受封为齐王，并广施恩信，深得民心。东吴既平，司马炎健康恶化，而子嗣暗弱，朝中欲推司马攸继位之声愈烈。司马炎得知后，以正太子名位为由逼迫司马攸回到自己的封国，司马攸要求留守生母王元姬之墓，但不被允许，因此愤恨引疾，抱病辞行，最终吐血而亡，谥号“献”。\n【演】在《三国演义》中，司马攸是司马昭次子，性情温和，因司马师无子而过继给司马师。司马昭认为天下应该是司马师的，想要立司马攸为世子，后因群臣反对而作罢。", advancedTroops="长弓兵 、弩兵", combination="司马氏霸府(成员:司马攸(晋)、司马炎(晋)、司马昭(晋)、司马师(晋)、司马懿(魏)、司马懿(晋),加成属性:防御、谋略)", policyName="舍己为公", policyText="每天$12$时、$18$时城邑所在州存在灾害时，获得赈灾陈情，完成可获得80000粮草及3000铜钱" };
yield return new GeneralDefinition("s1_100718","文虎",Homeland.Han,4,92,"唯瞻父兄","文虎·晋·弓·4星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="弓", sourceUrl="https://stzb.163.com/herolist/100718.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="唯瞻父兄", nativeSkillText="对敌军群体发动一次攻击（伤害率150.0%），使我军大营进行攻击和策略攻击时的伤害提升10.0%，持续1回合", defense=74, strategy=28, speed=56, cost=2.5, attackGrowth=1.53, defenseGrowth=1.02, strategyGrowth=0.27, speedGrowth=0.54, siege=10, siegeGrowth=0.66, attackDistance=3, biography="【史】魏晋时期将领，文钦之子，文鸯之弟。与父兄一起，同毌丘俭起兵勤王，兵败后逃往吴国。又参与诸葛诞反抗司马氏的叛乱，因文钦被诸葛诞杀害，与文鸯一起重新归顺司马昭，被封为将军。\n【演】在《三国演义》中，文虎和正史的形象大体一致，在诸葛诞起兵时登场，诸葛诞杀害文钦后，投降司马昭。", advancedTroops="长弓兵 、弩兵", combination="一门虎将(成员:文虎(晋)、文鸯(晋)、文钦(魏),加成属性:攻击)", policyName="弃城投明", policyText="可担任军事设施参军，令设施所属己方部队维持消耗降低50.0%，并使该设施耐久上限降低30点" };
yield return new GeneralDefinition("s1_100721","成济",Homeland.Han,3,82,"浴血","成济·晋·步·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="步", sourceUrl="https://stzb.163.com/herolist/100721.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="浴血", nativeSkillText="普通攻击后，使攻击目标陷入动摇状态，每回合产生逃兵（伤害率75.0%），持续2回合", defense=52, strategy=22, speed=21, cost=2.5, attackGrowth=0.78, defenseGrowth=0.5, strategyGrowth=0.21, speedGrowth=0.2, siege=15, siegeGrowth=0.86, attackDistance=1, biography="【史】司马家族的部下，担任太子舍人。在甘露五年曹髦讨伐司马昭的政变中，受到贾充指使，当街刺杀天子曹髦。后被司马昭归罪，夷三族。\n【演】在《三国演义》中，成济的事迹与正史大体一致，受贾充指使而杀害曹髦，后被灭三族。", advancedTroops="禁卫", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100722","冯紞",Homeland.Han,3,31,"落石","冯紞·晋·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="弓", sourceUrl="https://stzb.163.com/herolist/100722.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="落石", nativeSkillText="对敌军群体发动策略攻击（伤害率92.2%，受谋略属性影响），并使其防御属性降低5.2（受谋略属性影响），持续1回合", defense=66, strategy=85, speed=48, cost=1.5, attackGrowth=0.26, defenseGrowth=0.55, strategyGrowth=0.71, speedGrowth=0.4, siege=12, siegeGrowth=0.6, attackDistance=4, biography="【史】西晋宠臣，博览群书，能言善辩。曾历任魏郡太守、步兵校尉、越骑校尉、左卫将军。善于逢迎媚上，得到晋武帝宠信。与贾充、荀勖结为朋党。曾上书建议晋武帝遣返齐王司马攸回封地，间接导致司马攸病重去世。后先后担任汝南太守、御史中丞、侍中。晋武帝早期谋划伐吴时，曾和贾充、荀勖大力反对。临终时被封为散骑常侍。\n【演】在《三国演义》中，羊祜上表建议伐吴时，贾充、荀勖、冯紞三人力劝不可，于是此次伐吴未能成行。", advancedTroops="弩兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100723","田续",Homeland.Han,3,85,"重伤","田续·晋·骑·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="骑", sourceUrl="https://stzb.163.com/herolist/100723.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="重伤", nativeSkillText="普通攻击后，对攻击目标再次发动攻击（伤害率115.0%），并使其攻击属性降低15.0，持续2回合", defense=48, strategy=34, speed=88, cost=2, attackGrowth=0.75, defenseGrowth=0.43, strategyGrowth=0.3, speedGrowth=0.78, siege=3, siegeGrowth=0.16, attackDistance=2, biography="【史】魏晋时期将领，议郎田畴的从孙。以镇西护军的身份参与伐蜀之战。曾违抗邓艾军令，险被斩杀。后邓艾受诬被囚，押往洛阳，监军卫瓘平定钟会叛乱后，派遣田续追讨邓艾，最终在绵竹斩杀邓艾邓忠父子。\n【演】在《三国演义》中，田续生平与正史大体一致，在邓艾偷渡阴平、将要进攻涪城时，田续建议邓艾，士卒疲惫需要休养，险些被邓艾以惑乱军心为由斩杀。后卫瓘平定钟会叛乱，田续主动请求并率兵追上邓艾父子，将其杀害。", advancedTroops="轻骑兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100724","王业",Homeland.Han,3,12,"狼烟","王业·晋·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="弓", sourceUrl="https://stzb.163.com/herolist/100724.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="狼烟", nativeSkillText="使敌军群体陷入恐慌状态，每回合损失一定兵力（伤害率47.6%，受谋略属性影响），持续2回合", defense=83, strategy=79, speed=70, cost=1.5, attackGrowth=0.1, defenseGrowth=0.69, strategyGrowth=0.66, speedGrowth=0.58, siege=10, siegeGrowth=0.5, attackDistance=3, biography="【史】魏晋时期官员。曹髦时期，担任散骑常侍。曹髦讨伐司马昭时，与王沈共同告密，使司马昭有所防备。晋朝时期先后担任中护军、尚书左仆射。\n【演】在《三国演义》中，王业的事迹与正史大体一致，在曹髦讨伐司马昭的政变过程中，为避免灭族之祸，向司马昭告密。", advancedTroops="长弓兵 ", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100744","王子服",Homeland.Han,3,39,"谨言","王子服·汉·步·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="步", sourceUrl="https://stzb.163.com/herolist/100280.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="谨言", nativeSkillText="使友军全体受到策略攻击的伤害降低16.0%（受谋略属性影响），持续2回合", defense=37, strategy=57, speed=31, cost=2.5, attackGrowth=0.26, defenseGrowth=0.25, strategyGrowth=0.4, speedGrowth=0.21, siege=17, siegeGrowth=0.69, attackDistance=1, biography="【史】东汉末年越骑校尉、偏将军。建安五年，服与董承、长水校尉种辑、议郎吴硕受衣带诏共谋曹操。后事发，为操所诛。\n【演】在《三国演义》中，他与董承、长水校尉种辑、议郎吴硕受衣带诏共谋曹操。后事发，为操所诛。", advancedTroops="长枪兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100745","曹豹",Homeland.Han,3,73,"投石轰击","曹豹·汉·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="弓", sourceUrl="https://stzb.163.com/herolist/100283.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="投石轰击", nativeSkillText="在本场战斗中使我军弓兵全体攻城属性提高13.0（受谋略属性影响）", defense=61, strategy=46, speed=46, cost=2.5, attackGrowth=0.5, defenseGrowth=0.42, strategyGrowth=0.31, speedGrowth=0.31, siege=9, siegeGrowth=0.4, attackDistance=2, biography="【史】初为陶谦部下，后仕刘备。刘备领徐州牧后，与袁术战于淮阴石亭，曹豹与张飞守下邳。豹反刘备，间迎吕布，致使吕布得以自称徐州刺史。\n【演】在《三国演义》中，吕布为曹豹的女婿。刘备讨袁术，留张飞守徐州，飞设宴请各官赴席。把酒至曹豹面前，豹只饮一杯，飞并怒其为吕布丈人，鞭豹至五十。豹深恨飞，阴与布谋，引布夺徐州。", advancedTroops="长弓兵 ", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100746","郑泰",Homeland.Han,3,50,"援军秘策","郑泰·汉·步·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="步", sourceUrl="https://stzb.163.com/herolist/100284.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="援军秘策", nativeSkillText="战斗开始后第5回合起，每回合恢复我军群体一定兵力（恢复率103.0%，受谋略属性影响）", defense=48, strategy=75, speed=23, cost=2.5, attackGrowth=0.35, defenseGrowth=0.33, strategyGrowth=0.51, speedGrowth=0.17, siege=16, siegeGrowth=0.64, attackDistance=1, biography="【史】东汉末官吏。郑泰年轻时已有才略，喜欢结交豪杰。后来郑泰获举孝廉，由三府辟命并由公车征召，但郑泰不应命。汉灵帝死后，汉少帝刘辩继位，并由大将军何进辅政，何进任命郑泰为尚书侍郎，迁待御史。同时何进密谋诛除宦官，打算召凉州牧董卓入京协助。由于何进不听郑泰的劝阻，郑泰弃官而去。后来郑泰与荀攸和何颙等合谋诛灭董卓，但秘密泄漏，郑泰从武关逃离长安，投奔后将军袁术，袁术则上表郑泰为扬州刺史。郑泰于上任的路上去世，享年四十一岁。\n【演】在《三国演义》中，郑泰生平与正史大体相当。", advancedTroops="重步兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100747","杨彪",Homeland.Han,3,61,"包扎","杨彪·汉·骑·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="汉", troop="骑", sourceUrl="https://stzb.163.com/herolist/100288.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="包扎", nativeSkillText="恢复我军群体一定兵力（恢复率98.0%，受谋略属性影响）", defense=58, strategy=81, speed=96, cost=2.5, attackGrowth=0.42, defenseGrowth=0.4, strategyGrowth=0.56, speedGrowth=0.67, siege=13, siegeGrowth=0.5, attackDistance=1, biography="【史】东汉末年名臣，太尉杨赐之子、名士杨修之父，出身东汉名门“弘农杨氏”。汉献帝时，杨彪历官三公（司空、司徒、太尉）。权臣董卓意图迁都时，他据理力争。献帝东迁时，杨彪尽节护主。曹操挟献帝定都许县后，将杨彪下狱，获释后又任太常。他见汉室衰微，便诈称脚疾，不理世事。曹魏建立后，拒绝出任太尉，改光禄大夫，待以客礼。黄初六年（225年），杨彪逝世，年八十四。其著作现仅存《答曹公书》一篇。\n【演】在《三国演义》中，杨彪为东汉太尉，与司徒王允等共同迎接失散的少帝和陈留王，后为司徒，与太尉黄琬共谏欲迁都的董卓，遭罢免，废为庶人。后任太尉，献计于献帝以离间李傕、郭汜二人。二人交战时，奉命同众官诣郭汜营中劝和，为郭汜所监，杨彪怒斥郭汜，郭汜恼怒，欲害之，中郎将杨密力劝，郭汜才放了杨彪与大司农朱儁，二人出营相抱而哭，昏绝于地。\n又建议东迁中的献帝依靠曹操，因与袁术为姻亲，被曹操诬陷下狱，经孔融力争才得以幸免。", advancedTroops="轻骑兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100748","朱灵",Homeland.Han,3,70,"奋起","朱灵·魏·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="弓", sourceUrl="https://stzb.163.com/herolist/100229.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="奋起", nativeSkillText="使自身进行攻击时的伤害提高35.0%，持续2回合", defense=41, strategy=47, speed=47, cost=2.5, attackGrowth=0.52, defenseGrowth=0.31, strategyGrowth=0.36, speedGrowth=0.36, siege=10, siegeGrowth=0.5, attackDistance=4, biography="【史】三国时期曹魏名将。官至后将军，封为高唐侯，谥号威侯。初为袁绍部将，后归顺曹操，随曹操征伐四方，屡建战功。\n【演】在《三国演义》中，朱灵于第二十一回登场。其时刘备与曹操同在朝中，刘备深感掣肘，欲求脱计。适时袁术以淮南甚乱，欲北投族兄袁绍。刘备以其必从徐州过，向曹操请兵击之。曹操准其议，就遣朱灵、路昭与刘备同行，并以朱、路二人监督刘备。大军到徐州，大败袁术，不久袁术败逃病死。\n刘备便驻徐州，使朱、路二人回许都。曹操大怒，欲斩朱、路二人，荀彧告免。朱灵后又从征马超、韩遂，与徐晃夜渡蒲阪津，据河西为营，为大破关西军立下功劳。", advancedTroops="长弓兵 ", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100749","牛金",Homeland.Han,3,86,"坚守突击","牛金·魏·骑·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100230.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="坚守突击", nativeSkillText="使自身攻击属性、防御属性提高24.0", defense=72, strategy=41, speed=95, cost=2.5, attackGrowth=0.65, defenseGrowth=0.55, strategyGrowth=0.31, speedGrowth=0.71, siege=3, siegeGrowth=0.18, attackDistance=1, biography="【史】初为曹仁部曲将，周瑜军数万人来攻，前锋数千人始至，曹仁遣牛金迎战。但对方兵力较多，牛金遂被围困。曹仁亲自攻入阵中救出牛金。司马懿使牛金轻骑饵诱蜀军，刚交战诸葛亮就退兵，追至祁山。蜀将马岱入寇，司马懿遣将军牛金击退，斩千余级。公孙渊反，司马懿率牛金、胡遵等步骑四万发自洛阳，后平定辽东。牛金官至后将军。\n【演】曹仁麾下骁将，与东吴交战时，将甘宁困于夷陵城，却被周瑜所救。之后，牛金欲夜袭周瑜营寨，但被周瑜识破，大败。", advancedTroops="轻骑兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100750","孙静",Homeland.Han,3,67,"犒劳","孙静·吴·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100223.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="犒劳", nativeSkillText="使自身进行策略攻击时的伤害提高35.0%，持续2回合", defense=75, strategy=81, speed=51, cost=2, attackGrowth=0.49, defenseGrowth=0.54, strategyGrowth=0.58, speedGrowth=0.38, siege=10, siegeGrowth=0.46, attackDistance=3, biography="【史】东汉末年长沙太守孙坚之弟，孙策、孙权之叔。孙坚初起义军时，孙静集合乡里及宗族子弟五六百人作为孙坚的基础队伍。孙静献计助孙策击败钱塘太守王朗，平定会稽。孙策上表任命孙静为奋武校尉，打算委以重任。但孙静留念故乡，不愿出外为官。建安四年（200年），孙权执掌大事，就地升任孙静为昭义中郎将。孙静后终老故乡。\n【演】在《三国演义》中，孙策进攻会稽，派人请孙静，孙静带家属与孙策在钱塘会面。孙静献计助孙策击败钱塘太守王朗，平定会稽。孙策死后，张昭安排孙静处理丧事。孙权统领时期，指派孙静驻守吴会。", advancedTroops="长弓兵 ", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100751","吕范",Homeland.Han,3,78,"齐射","吕范·吴·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100240.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="齐射", nativeSkillText="对敌军群体发动一次攻击（伤害率90.0%），并使其攻击属性降低16.0，持续2回合", defense=79, strategy=72, speed=61, cost=2.5, attackGrowth=0.58, defenseGrowth=0.6, strategyGrowth=0.55, speedGrowth=0.46, siege=14, siegeGrowth=0.6, attackDistance=4, biography="【史】东吴重臣。吕范年轻为汝南县吏，后避难寿春，结识孙策。随孙策、孙权征伐四方，对稳定江东做出了杰出的贡献，孙权将其比之于吴汉。官至前将军、假节、扬州牧，封南昌侯。黄武七年（228年），拜大司马，印绶未下，吕范已病卒。孙权悲痛不已，遣使者追赠大司马印绶。孙权还都建业后，以太牢礼祭祀吕范。\n【演】在《三国演义》中，吕范初为袁术谋士，后从孙策，与之平定江东。赤壁之战后，孙权与刘备表面为盟友，实则互竞诡谲。其时周瑜献美人计，欲以孙权之妹许配刘备，让刘备入赘为东吴女婿，吕范则负责说媒，并以“人不可中道而废人伦”与及“两家结秦晋之好”为由，说服刘备接受亲事。当刘备到甘露寺见吴国太之时，吕范更建议伏刀斧手以斩刘备，然而失败告终。\n在第八十五回中，陆逊统领吴军将举国来侵的刘备击退后，曹丕乘蜀吴交战之时安排曹仁、曹休、曹真三路袭吴，吕范则受命抵御曹休，并成功将敌军击败（事实上，洞口之役的结果是吕范败于曹休、臧霸等）。", advancedTroops="长弓兵 ", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100752","孙瑜",Homeland.Han,3,50,"毒泉","孙瑜·吴·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100247.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="毒泉", nativeSkillText="1回合准备，使敌军群体陷入恐慌状态，每回合损失一定兵力（伤害率85.0%，受谋略属性影响），持续2回合", defense=63, strategy=81, speed=49, cost=1.5, attackGrowth=0.36, defenseGrowth=0.45, strategyGrowth=0.57, speedGrowth=0.35, siege=10, siegeGrowth=0.46, attackDistance=4, biography="【史】孙坚之侄，昭义中郎将孙静第二子。初为恭义校尉。后领丹杨太守，得众万余人，加绥远将军。建安十一年（204）与周瑜共克麻、保二屯。后从孙权拒曹操于濡须（今安徽无为附近），迁奋威将军，后转屯牛渚，招降魏兵。又在军中立学，请马普为师。孙瑜喜好读书，虽军务繁忙也不停辍。年三十九而卒。\n【演】在《三国演义》中，孙瑜是孙权的堂弟，东吴的宗室成员，于三国演义第57回登场。周瑜以取蜀为借口，欲取荆州时，孙瑜受孙权派遣，率兵前来会合，支援周瑜。", advancedTroops="长弓兵 ", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100753","骆统",Homeland.Han,3,48,"火辎","骆统·吴·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="弓", sourceUrl="https://stzb.163.com/herolist/100248.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="火辎", nativeSkillText="1回合准备，对敌军群体发动策略攻击（伤害率75.0%，受谋略属性影响），并使其陷入燃烧状态，每回合损失一定兵力（伤害率75.0%，受谋略属性影响），持续1回合", defense=57, strategy=85, speed=47, cost=2.5, attackGrowth=0.36, defenseGrowth=0.44, strategyGrowth=0.64, speedGrowth=0.36, siege=10, siegeGrowth=0.5, attackDistance=2, biography="【史】三国时吴国将领、学者。陈国相骆俊之子。年二十，就担任乌程相，任内有政绩，使得民户过万。曾劝孙权尊贤纳士，省役息民。凌统卒，骆统领其部曲。因战功迁偏将军，封新阳亭侯，任濡须督。\n【演】在《三国演义》中，骆统在舌战群儒时出场，欲与赴东吴的诸葛亮辩论，被黄盖劝阻。", advancedTroops="弩兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100754","贺齐",Homeland.Han,3,90,"重伤","贺齐·吴·步·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="吴", troop="步", sourceUrl="https://stzb.163.com/herolist/100321.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="重伤", nativeSkillText="普通攻击后，对攻击目标再次发动攻击（伤害率115.0%），并使其攻击属性降低15.0，持续2回合", defense=61, strategy=63, speed=25, cost=2.5, attackGrowth=0.69, defenseGrowth=0.46, strategyGrowth=0.48, speedGrowth=0.2, siege=18, siegeGrowth=0.82, attackDistance=2, biography="【史】吴国名将。早年在平定山越的战争中立有大功，又讨平叛乱无数，身经百战，所向披靡，深受孙权器重。后来在与魏国的多次边境争斗中也屡立战功，官至后将军。", advancedTroops="重步兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100755","程远志",Homeland.Han,3,74,"疾风突击","程远志·群·步·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="步", sourceUrl="https://stzb.163.com/herolist/100181.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="疾风突击", nativeSkillText="使自身攻击属性、速度属性提高24.0", defense=71, strategy=65, speed=33, cost=2.5, attackGrowth=0.65, defenseGrowth=0.63, strategyGrowth=0.56, speedGrowth=0.3, siege=19, siegeGrowth=1, attackDistance=1, biography="【演】黄巾军将领，于三国演义第一回登场，统兵五万进犯涿郡。幽州刺史刘焉令校尉邹靖引刘备、关羽、张飞三人，统兵五百，前去破敌。在大兴山下，两军交战，程远志被关羽一刀挥为两段，余众溃散。", advancedTroops="长枪兵", combination="黄巾游勇(成员:马元义(群)、裴元绍(群)、程远志(群)、邓茂(群),加成属性:攻击、防御、速度、攻城)", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100756","裴元绍",Homeland.Han,3,88,"乱击","裴元绍·群·骑·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="骑", sourceUrl="https://stzb.163.com/herolist/100182.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="乱击", nativeSkillText="1回合准备，对敌军群体发动一次攻击（伤害率120.0%），并使其防御属性降低15.0，持续2回合", defense=74, strategy=50, speed=102, cost=2.5, attackGrowth=0.76, defenseGrowth=0.65, strategyGrowth=0.44, speedGrowth=0.89, siege=5, siegeGrowth=0.25, attackDistance=1, biography="【演】《三国演义》中的虚构人物。原黄巾军之武将。黄巾起义失败后，与周仓一同率领残部当了山贼。在关羽过五关时，与周仓一同希望成为关羽的部下，后被留守山中。不久后，因其欲夺偶然路过的赵云之马，反遭讨伐战败身死。", advancedTroops="轻骑兵", combination="黄巾游勇(成员:马元义(群)、裴元绍(群)、程远志(群)、邓茂(群),加成属性:攻击、防御、速度、攻城)", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100757","马元义",Homeland.Han,3,65,"文韬武略","马元义·群·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100183.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="文韬武略", nativeSkillText="使自身攻击属性、谋略属性提高24.0", defense=78, strategy=46, speed=58, cost=2, attackGrowth=0.54, defenseGrowth=0.64, strategyGrowth=0.38, speedGrowth=0.49, siege=13, siegeGrowth=0.58, attackDistance=2, biography="【史】东汉末年黄巾起义的组织者之一，是黄巾大方首领。光和六年（183年），马元义奉张角之命，筹划起事的准备工作。马元义聚集荆州、扬州信徒数万人约定于邺城相会，并收买中常侍封谞、徐奉等为内应，准备于次年（甲子年）三月初五（甲子日）内外同时起事。由于张角弟子济南人唐周的告密，马元义于于中平元年（184年）正月在河内郡山阳县被捕。由于马元义被害，迫使张角提前于二月起兵发动起义。\n【演】张角派马元义暗中收买中常侍封谞作为内应。张角将要起义时，由于其弟子唐周的告密。使得灵帝召大将军何进调兵诛马元义。", advancedTroops="长弓兵 ", combination="黄巾游勇(成员:马元义(群)、裴元绍(群)、程远志(群)、邓茂(群),加成属性:攻击、防御、速度、攻城)", policyName="", policyText="" };
