yield return new GeneralDefinition("s1_100760","曹昂",Homeland.Han,3,85,"凿穿","曹昂·魏·骑·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="魏", troop="骑", sourceUrl="https://stzb.163.com/herolist/100208.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="凿穿", nativeSkillText="对敌军单体发动一次攻击（伤害率135.0%）", defense=74, strategy=39, speed=99, cost=2.5, attackGrowth=0.64, defenseGrowth=0.56, strategyGrowth=0.3, speedGrowth=0.75, siege=7, siegeGrowth=0.33, attackDistance=1, biography="【史】曹操的长子。聪明且性情谦和，为曹操所喜爱，二十岁时即举孝廉。随曹操出征张绣时，因张绣突然袭击，曹昂为救曹操负责断后，与大将典韦一同战死于宛城。\n【演】在《三国演义》中，宛城之战，曹昂把自己的马让给曹操，曹操乘马脱险，而曹昂死于乱军之中。", advancedTroops="轻骑兵", combination="孟德之子(成员:曹昂(魏)、曹彰(魏)、曹植(魏)、曹丕(魏),加成属性:攻击、谋略)", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100761","许攸",Homeland.Han,3,57,"绝道","许攸·群·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100185.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="绝道", nativeSkillText="对敌军群体发动策略攻击（伤害率105.0%，受谋略属性影响），并使其防御属性降低6.0（受谋略属性影响），持续2回合", defense=41, strategy=88, speed=54, cost=2, attackGrowth=0.48, defenseGrowth=0.33, strategyGrowth=0.71, speedGrowth=0.45, siege=15, siegeGrowth=0.71, attackDistance=2, biography="【史】本为袁绍帐下谋士，官渡之战时其家人因犯法而被收捕，许攸因此背袁投曹，并为曹操设下偷袭袁绍军屯粮之所乌巢的计策，袁绍因此而大败于官渡。后许攸随曹操平定冀州，因自恃其功而屡屡口出狂言，终因触怒曹操而被害。\n【演】在《三国演义》中，许攸年轻时与曹操相友善，后来成为袁绍的谋士，多次为袁绍出谋划策，力主攻打曹操都城许昌。官渡之战之际，许攸因家人犯法被收治而投奔曹操，提供了重要情报，建议曹操偷袭乌巢，结果大获全胜。官渡之战后，许攸跟随曹操到达邺城，口出狂言，辱骂曹操，轻视曹军将士，被许褚一怒之下所斩，曹操见后深责许褚，下令厚葬许攸。", advancedTroops="弩兵", combination="勾心斗角(成员:郭图(群)、许攸(群)、审配(群),加成属性:谋略、攻击距离提高)", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100762","郭图",Homeland.Han,3,38,"乱阵","郭图·群·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="群", troop="弓", sourceUrl="https://stzb.163.com/herolist/100188.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="乱阵", nativeSkillText="使敌军群体进行策略攻击时的伤害降低15.0%（受谋略属性影响），持续2回合", defense=62, strategy=79, speed=53, cost=2, attackGrowth=0.31, defenseGrowth=0.5, strategyGrowth=0.65, speedGrowth=0.44, siege=10, siegeGrowth=0.54, attackDistance=4, biography="【史】袁绍帐下谋士。官渡之战时力主趁机偷袭曹营，在此计失败后为免于责罚而归罪于率军偷袭曹营的张郃、高览，致使二人背袁投曹。袁绍死后为其长子袁谭效力，后和袁谭一同被曹操所害。\n【演】在《三国演义》中，郭图生平与正史大体相当。", advancedTroops="长弓兵 ", combination="勾心斗角(成员:郭图(群)、许攸(群)、审配(群),加成属性:谋略、攻击距离提高)", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100763","荣晦",Homeland.Han,3,73,"游击","荣晦·晋·步·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="步", sourceUrl="https://stzb.163.com/herolist/100763.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="游击", nativeSkillText="使敌军单体陷入动摇，每回合产生逃兵（伤害率125.0%），持续2回合", defense=54, strategy=33, speed=24, cost=2, attackGrowth=0.52, defenseGrowth=0.45, strategyGrowth=0.22, speedGrowth=0.23, siege=17, siegeGrowth=0.73, attackDistance=3, biography="【史】魏晋时期武将。卫瓘担任司空时，荣晦曾因犯罪而被卫瓘责骂驱逐，心怀怨恨。司马玮矫诏带领部队收捕司马亮、卫瓘时，荣晦也在军中，趁机杀害卫瓘及其子孙。卫瓘平反时，卫瓘的后人上表要求报仇，因此荣晦被族诛。", advancedTroops="重步兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100764","王衍",Homeland.Han,3,33,"速战坚守","王衍·晋·弓·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="晋", troop="弓", sourceUrl="https://stzb.163.com/herolist/100764.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="速战坚守", nativeSkillText="使自身防御属性、速度属性提高24.0", defense=48, strategy=87, speed=46, cost=2, attackGrowth=0.27, defenseGrowth=0.34, strategyGrowth=0.63, speedGrowth=0.33, siege=9, siegeGrowth=0.41, attackDistance=3, biography="【史】西晋重臣，神情明秀，风姿详雅。曾经拜访山涛，山涛送走王衍后感叹：“误天下苍生者，未必非此人也。”先后担任太子舍人、黄门侍郎、中领军、尚书令等职，后更升任司空、司徒。然而王衍虽身居高位，却不在意国家治理，而只考虑自全之计，遭受时人鄙夷。永嘉五年（311年），石勒击败晋军，王衍与石勒相见时，想要避祸而劝石勒称帝，石勒怒斥王衍：“你名盖四海，身居重任，仕朝一生，竟说自己不参与国事！破坏天下，正是你的罪状。”然后将王衍杀死。王衍时年五十六岁。", advancedTroops="长弓兵 ", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100765","黄皓",Homeland.Han,3,39,"劫粮","黄皓·蜀·骑·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100765.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="劫粮", nativeSkillText="使敌军群体受到策略攻击时的伤害提高13.0%（受谋略属性影响），持续2回合", defense=52, strategy=56, speed=90, cost=2, attackGrowth=0.25, defenseGrowth=0.36, strategyGrowth=0.46, speedGrowth=0.68, siege=2, siegeGrowth=0.1, attackDistance=2, biography="【史】三国时期蜀国宦官，受到后主刘禅宠信。董允在世时，对后主尽职尽责，黄皓位不过黄门丞。董允去世后，陈祗替代董允担任侍中，与黄皓内外勾结，黄皓开始干预政事。陈祗死后，黄皓先后升任中常侍、奉车都尉，权柄滔天。曾离间刘禅与弟弟刘永的关系，导致刘永多年见不到刘禅。大臣不亲附黄皓的，也会遭到贬斥。邓艾破蜀后，听说黄皓奸诈险恶，想要杀掉黄皓。后因黄皓准备厚礼贿赂邓艾的左右，最终免于一死。\n【演】在《三国演义》中，黄皓在姜维北伐期间，黄皓收受邓艾的贿赂，散布谣言，导致刘禅两次下诏姜维班师回朝。姜维两次在大好形势下不得不返回成都，劝说刘禅杀掉黄皓未果后，率兵前往沓中避祸。在钟会邓艾伐蜀期间，黄皓又请巫婆进行占卜祷告，以至于刘禅没有见到姜维的告急表文，最终误了大事。而在结局中，黄皓虽然贿赂邓艾暂时逃过一死，却被司马昭下令凌迟处死。其余实际与史实相似。", advancedTroops="重骑兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100766","麋芳",Homeland.Han,3,74,"坚守","麋芳·蜀·步·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="步", sourceUrl="https://stzb.163.com/herolist/100766.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="坚守", nativeSkillText="使自身受到攻击的伤害降低35.0%，持续2回合", defense=73, strategy=42, speed=26, cost=2.5, attackGrowth=0.56, defenseGrowth=0.55, strategyGrowth=0.36, speedGrowth=0.21, siege=19, siegeGrowth=0.82, attackDistance=2, biography="【史】三国时期蜀国将领。徐州东海人，麋竺之弟，刘备妻子麋夫人的兄弟。曾担任彭城相，与哥哥麋竺共同辞官追随刘备，后来担任南郡太守。建安二十四年（219年）关羽北伐襄樊时，麋芳与士仁未能及时供给军资，关羽说“等回来一定收拾你们。”据吴录记载，南郡城中失火，军器被焚烧了很多，关羽以此责备麋芳。之后二人心中不安，在士仁投降东吴后，麋芳也放弃抵抗，投降东吴，导致关羽兵败被害。其兄麋竺虽然被刘备劝慰原谅，但依然羞愧而死。担任吴国将领期间，曾被虞翻多次羞辱。\n【演】在《三国演义》中写作“糜芳”，多次担任守城等任务。在关羽北伐之前，他与士仁饮酒失火，烧毁军器，险些被关羽下令斩杀，费诗以出师先斩将不利为由进行劝谏，改为杖责四十。后来投降东吴，刘备称帝后伐吴，他与士仁听说小兵要杀害自己来换取刘备的原谅，二人杀死马忠重新投奔刘备，但被刘备下令处死，关兴亲自用刀剐之，以祭关公。其余事迹与史实相似。", advancedTroops="长枪兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100767","士仁",Homeland.Han,3,52,"铁壁","士仁·蜀·骑·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100767.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="铁壁", nativeSkillText="使自身受到攻击和策略攻击时的伤害降低18.0%", defense=55, strategy=75, speed=89, cost=2, attackGrowth=0.28, defenseGrowth=0.42, strategyGrowth=0.55, speedGrowth=0.67, siege=5, siegeGrowth=0.24, attackDistance=2, biography="【史】三国时期蜀国将领。幽州广阳人，《三国志》中大部分记载为士仁，唯《关羽传》记载为傅士仁，有学者认为是在传播抄写过程中出现的错误，后《资治通鉴》《三国演义》等皆写作傅士仁。关羽北伐襄樊之时驻扎在公安。吴兵依吕蒙白衣渡江之计进犯荆州，士仁被虞翻说降，之后在麋芳守江陵城时随吕蒙一起出现，于是麋芳也一起投降。\n【演】在《三国演义》中，士仁被写作“傅士仁”，在关羽北伐襄樊时出场，与麋芳饮酒失火，烧毁军器，险些被关羽下令斩杀，费诗以出师先斩将不利为由进行劝谏，改为杖责四十。后来投降东吴，刘备称帝后伐吴，与麋芳听说小兵要杀害自己来换取刘备的原谅，二人杀死马忠重新投奔刘备，但被刘备下令处死，关兴亲自用刀剐之，以祭关公。", advancedTroops="轻骑兵", combination="", policyName="", policyText="" };
yield return new GeneralDefinition("s1_100768","廖立",Homeland.Han,3,31,"固阵","廖立·蜀·骑·3星。历史/奖励/待归属档案；不进入试玩招募。战法名为资料展示，效果尚未逐条实现。"){ s1=true, recruitable=false, faction="蜀", troop="骑", sourceUrl="https://stzb.163.com/herolist/100768.html", evidence="历史/奖励/待归属档案；不进入试玩招募", nativeSkill="固阵", nativeSkillText="使自身受到策略攻击的伤害降低35.0%，持续2回合", defense=40, strategy=73, speed=91, cost=2, attackGrowth=0.44, defenseGrowth=0.28, strategyGrowth=0.59, speedGrowth=0.63, siege=4, siegeGrowth=0.18, attackDistance=2, biography="【史】三国时期蜀国谋臣。曾经得到诸葛亮的赞誉，认为他与庞统都是“楚之良才”，担任长沙太守。建安二十年，吴国侵犯荆州南三郡，廖立逃脱回到刘备身边，改为巴郡太守，后迁侍中、长水校尉。自以为才名仅次于诸葛亮，但未被重视，因此经常抱怨。因出言讽刺先帝刘备、关羽、马良兄弟，被诸葛亮贬为平民。诸葛亮死后，廖立认为不会再有人敢用自己，感叹“吾终为左衽矣！”\n【演】在《三国演义》中，廖立在诸葛亮死时出场，记载与史实相似。", advancedTroops="轻骑兵", combination="", policyName="", policyText="" };
} } }
